  str_monster_name_2000271_en = "Lumo Ranger",
  str_monster_desc_2900063 = "ว่ากันว่าเป็นสมาชิกขององค์กรลึกลับที่เรียกว่าอิคลิพส์ นอกจากมีการโจมตีที่ทรงพลังแล้ว ยังสามารถสั่งการอิคลิพไซท์ได้อีกด้วย",
  str_monster_desc_2900141 = "สมาชิกขององค์กรลึกลับที่เรียกว่าอิคลิพส์ ซึ่งรวมตัวเป็นอสรพิษคู่แฝดกับไชร์น้องสาวของเธอ เธอจะทำทุกวิถีทางเพื่อให้บรรลุเป้าหมายของตนเอง",
  str_monster_desc_2900181 = "สมาชิกขององค์กรลึกลับที่เรียกว่าอิคลิพส์ ซึ่งรวมตัวเป็นอสรพิษคู่แฝดกับเชลต์พี่สาวของเธอ เธอเป็นคนหุนหันพลันแล่นที่สังหารศัตรูด้วยความโหดเหี้ยมและทารุณ",
  str_monster_desc_2900201 = "ว่ากันว่าเป็นสมาชิกขององค์กรลึกลับที่เรียกว่าอิคลิพส์ นอกจากมีการโจมตีที่ทรงพลังแล้ว ยังสามารถสั่งการอิคลิพไซท์ได้อีกด้วย",
  str_monster_desc_2900211 = "รุนแรงและใหญ่โตมหึมา มันคืออิคลิพไซท์ทรงพลังที่น่าจะแบกความทุกข์ทนอย่างไร้ที่สิ้นสุดเอาไว้ อยู่ให้ห่างไว้จะดีที่สุด",
  str_monster_desc_2900221 = "การผสานรวมกันของเชลต์และไชร์ การทนทุกข์กับความเจ็บปวดแสนสาหัสทำให้มันมีความต้องการอันแรงกล้าที่จะล้างแค้น จึงเป็นอิคลิพไซท์ที่โหดเหี้ยมและทรงพลัง",
  str_monster_desc_2900231 = "สัตว์ร้ายที่คอยปกป้องโคลอสซัสแมนทิซซึ่งมีเทคโนโลยีโบราณลึกลับ ระวังมันไว้ให้ดี",
  str_monster_desc_2900232 = "สัตว์ร้ายที่คอยปกป้องโคลอสซัสแมนทิซซึ่งมีเทคโนโลยีโบราณลึกลับ ระวังมันไว้ให้ดี",
  str_monster_desc_2900241 = "พลังทำลายล้างของมันเพียงพอที่จะทำลายล้างได้ทั้งกองทัพ ว่ากันว่าเป็นบริวารที่ภักดีของสมาชิกองค์กรอิคลิพส์",
  str_monster_desc_2900251 = "มันมีความว่องไวมาก สามารถทำตัวเหมือนวิญญาณที่ไปมาโดยปราศจากร่องรอย วิธีการทั่วไปไม่น่าจะทำอะไรมันได้ ยังรู้จักกันในชื่อนักล่าวิญญาณอีกด้วย",
  str_monster_desc_2000011 = "ด้วยทักษะการต่อสู้ที่ล้ำหน้าเดรตเชอร์ไปไกลมาก จึงเป็นหน่วยต่อสู้หลักของอิคลิพไซท์ นอกจากนี้ยังเรียกกันอีกอย่างว่ากัปตัน และมักจะเห็นบัญชาการเหล่าเดรตเชอร์อยู่เสมอ",
  str_monster_desc_2000071 = "อิคลิพไซท์ตัวใหญ่ยักษ์ที่มีหน้าที่ทำลายป้อมปราการทั้งหลาย และเรียกกันว่าเดโมลิชเชอร์",
  str_monster_desc_2000101 = "มีหน้าที่ตรวจสอบความเคลื่อนไหวของออโรเรียน และเรียกกันว่าพลสอดแนม มักโจมตีพวกออโรเรียนร่วมกับอิคลิพไซท์ตัวอื่น ๆ",
  str_monster_desc_2000111 = "ทาสรับใช้ของอีวิลอายที่มี ATK สกิลและ RES สกิลแข็งแกร่ง บางครั้งจะพบว่าพวกมันคอยช่วยเดรตเชอร์อีกด้วย",
  str_monster_desc_2000121 = "อิคลิพไซท์ที่เชี่ยวชาญในการตรวจจับความเคลื่อนไหวของออโรเรียน และยังเรียกอีกอย่างหนึ่งว่าซีเออร์ บางครั้งมันสามารถตรวจจับจากระยะไกลได้อีกด้วย",
  str_monster_desc_2000131 = "กองทัพสัตว์เลื้อยคลานสีเทาที่มีหน้าที่ในการต่อสู้พื้นฐานหลายอย่าง เรียกอีกอย่างว่าคลีนเนอร์",
  str_monster_desc_2000141 = "สิ่งมีชีวิตร่างเตี้ยที่คอยถือกล่องสีดำที่ใช้ขนส่งอุปกรณ์ให้กับองค์กรอิคลิพส์ เรียกอีกอย่างว่ารันเนอร์",
  str_monster_desc_2000151 = "พวกนี้คือนักสู้ของอิคลิพไซท์ พวกมันทรงพลังในการต่อสู้และสามารถบัญชาการอิคลิพไซท์ได้ เรียกอีกอย่างว่าเจ้าหน้าที่",
  str_monster_desc_2000161 = "มีความสามารถในการพรางตัวที่เก่งกล้า พวกมันมักแทรกซึมเข้าไปในการรวมตัวของออโรเรียนเพื่อทำการลอบสังหาร จึงเรียกกันว่ามือสังหาร",
  str_monster_desc_2000171 = "หนึ่งใน \"อิคลิพไซท์ร่างวัตถุ\" มีรูปร่างเป็นผลึกสีดำ และถือโดยแชโดว์หรืออิคลิพไซท์ตัวอื่น ๆ มักจะถูกปล่อยออกมาต่อสู้ในช่วงเวลาที่สำคัญของการรบ",
  str_monster_desc_2000181 = "หนึ่งใน \"อิคลิพไซท์ร่างวัตถุ\" มีรูปร่างเป็นผลึกสีดำ และถือโดยแชโดว์หรืออิคลิพไซท์ตัวอื่น ๆ มักจะถูกปล่อยออกมาต่อสู้ในช่วงเวลาที่สำคัญของการรบ",
  str_monster_desc_2000211 = "ไม่เหมาะสำหรับการต่อสู้ แต่ฟื้นฟู HP ให้อิคลิพไซท์ตัวอื่นได้ ว่ากันว่าพัฒนามาจากแชโดว์ไกสต์ บางครั้งก็เรียกว่าฮีลเลอร์",
  str_monster_desc_2000221 = "ไม่เหมาะสำหรับการต่อสู้ แต่สามารถทำให้หนามงอกขึ้นมาจากพื้น เพดาน และกำแพงอื่น ๆ เพื่อโจมตีผู้ที่ผ่านมาได้! บางครั้งเรียกว่าสไปเกอร์",
  str_monster_desc_4000221 = "ไม่มีกำลังรบ",
  str_monster_desc_2000231 = "เท้าของมันสามารถดูดซับลูมินารอบ ๆ ตัวเพื่อกลายเป็นอันทรงพลัง บางทีก็ถือว่าพัฒนามาจากกลูมกูล และเรียกว่า \"ดูดซับพลังงาน\" ด้วย",
  str_monster_desc_2000241 = "อีวิลอายชั้นสูงที่มีความสามารถด้านการสังเกตสูงมาก ทำให้ยากสำหรับออโรเรียนที่จะไม่ถูกตรวจจับ รู้จักกันในชื่อซีกเกอร์",
  str_monster_desc_2000251 = "สมาชิกรุ่นเยาว์ที่เป็นฐานหลักของกองกำลังทหารลูโมโพลิส มีจำนวนมากมายและออกลาดตระเวนกันอย่างขันแข็ง",
  str_monster_desc_2000261 = "รับภาระหน้าที่ในการปกป้องเมืองตลอดเวลาโดยไม่บ่นแม้แต่คำเดียว ไม่เคยหยุดพัก และถือว่าเป็นกระดูกสันหลังขององครักษ์",
  str_monster_desc_2000271 = "องครักษ์คอยทำหน้าที่พลสอดแนมด้วยเช่นกัน หลังจากผ่านการฝึกฝนพิเศษจะมีความสามารถในการเคลื่อนที่เร็ว และมีความคล่องแคล่วว่องไว",
  str_monster_desc_2000281 = "ทหารคุ้มกันที่ติดโล่ป้องกันชั้นสูง ด้วยความสามารถในการทนต่อการต่อสู้อันดุเดือด ทำให้พวกมันเป็นกำแพงแข็งแกร่งที่คอยปกป้องพวกพ้องของตัวเอง",
  str_monster_desc_2000291 = "พลหอกที่ได้รับการฝึกฝนการต่อสู้ การโจมตีที่หนักหน่วงของพวกมันทำให้ไม่มีใครหยุดยั้งได้ในสนามรบ",
  str_monster_desc_2000293 = "พลหอกที่ได้รับการฝึกฝนการต่อสู้ การโจมตีที่หนักหน่วงของพวกมันทำให้ไม่มีใครหยุดยั้งได้ในสนามรบ",
  str_monster_desc_2000301 = "อิคลิพไซท์หุ้มเกราะจากแหล่งกบดานทมิฬ รัตติกาลสีขาว ก่อนหน้านี้พวกมันเคยเหี้ยมโหด แต่หลังจากที่ถูกจับได้ก็กลับกลายเป็นแหล่งความบันเทิง",
  str_monster_desc_2000302 = "อิคลิพไซท์หุ้มเกราะรุ่นพัฒนา แม้ว่าเกราะของพวกมันจะสวยงามกว่า แต่ก็ไม่สามารถหลีกหนีโชคชะตาในการเป็นแหล่งความบันเทิงของผู้อื่นได้",
  str_monster_desc_2000311 = "ชอบต่อสู้กับออโรเรียนด้วยดาบคู่และมีทักษะสูงมาก แต่มักไม่ทำงานร่วมกับอิคลิพไซท์ตัวอื่น ๆ และมักเรียกกันว่าพลดาบ",
  str_monster_desc_2000321 = "พัฒนามาจากแมลงเคลื่อนที่เร็วในช่วงก่อนสงคราม เคลื่อนที่ได้อย่างรวดเร็วและจัดการได้ยากมาก เรียกกันอีกชื่อหนึ่งว่าเชสเซอร์",
  str_monster_desc_2000341 = "นักปล้นสะดมมืออาชีพที่หากินด้วยการขโมยของจากอารยธรรมโบราณ เนื่องจากใช้พลังงานทั้งหมดไปกับการลักขโมย ความสามารถในการต่อสู้ของพวกมันจึงต่ำมาก เมื่อเผชิญหน้ากับศัตรูก็ต้องหนีอย่างเดียวเท่านั้น",
  str_monster_desc_2000351 = "ว่ากันว่านี่คือครัชเชอร์ในกลุ่มที่อ่อนแอกว่า เชื่อกันว่าเป็นครัชเชอร์ที่ได้รับบาดเจ็บสาหัสที่พัฒนาขึ้นหลังจากได้รับการรักษา",
  str_monster_desc_2000411 = "เมื่ออยู่ท่ามกลางพลังงานที่เข้มข้น อิคลิพไซท์อีวิลอายบางส่วนได้เกิดการกลายพันธุ์แบบประหลาดขึ้น",
  str_monster_desc_2000421 = "กล่าวกันว่าเป็นการกลายพันธุ์ของ Shadow Eclipsite สามารถเพิ่ม ATK ของ Eclipsites อื่นได้",
  str_monster_desc_2000431 = "อิคลิพไซท์พิเศษที่สร้างขึ้นโดยบรรพบุรุษของหนอนทราย กระแสพลังความมืดของมันไม่เสถียรอย่างมากและจะระเบิดเมื่อตาย",
  str_monster_desc_2000441 = "อิคลิพไซท์บางส่วนได้รับผลกระทบจากพลังงานที่เข้มข้นและพัฒนาไปอย่างมาก ทำให้พวกมันมีความต้านทานสูงต่อธาตุบางชนิด",
  str_monster_desc_2000442 = "อิคลิพไซท์ประเภทนี้ได้สะสมพลังธาตุไว้มากมาย จนส่งผลต่อธาตุของสภาพแวดล้อมรอบตัว",
  str_monster_desc_2000451 = "ทหารลูโมโพลิสที่ถูกเกิร์ตเซิร์ดหลอกได้สูญเสียความสามารถในการคิด และจะโจมตีหลังจากถูกควบคุมโดยอิคลิพไซท์ พวกมันจะเดินทัพเข้าสู่สนามรบตามคำสั่งของเกิร์ตเซิร์ด",
  str_monster_desc_2000401 = "อิคลิพไซท์ระดับต่ำที่ไร้ซึ่งสติปัญญาใด ๆ พวกมันทำได้เพียงแค่เชื่อฟังคำสั่งของผู้ที่เรียกมาและต่อต้านการโจมตีให้พวกเขาเท่านั้น",
  str_monster_desc_2000491 = "ร่างโคลนที่สร้างขึ้นโดยอิคลิพไซท์ระดับสูงที่มีความสามารถพิเศษ ดูเหมือนต้นฉบับของมันเปี๊ยบจนถึงขั้นสร้างความสับสนในหมู่ทหารศัตรูได้เลย",
  str_monster_desc_2000501 = "อิคลิพไซท์พวกนี้มีตะขอพิเศษไว้ดึงศัตรูเข้ามาเพื่อโจมตีเป็นกลุ่ม ดังนั้นระวังให้ดี",
  str_monster_desc_2000511 = "อิคลิพไซท์ประเภทนี้มีคริสตัลสีเทาที่ปล่อยรังสีพิเศษที่ขัดขวางกระแสลูมินาของเป้าหมาย ทำให้ควบคุมได้อย่างยากลำบาก",
  str_monster_desc_2000521 = "สัตว์กลายพันธุ์ที่เกิดขึ้นหลังจากอิคลิพไซท์กัดกินซากศพของอิคลิพไซท์ตัวอื่น พวกมันสามารถปล่อยสนามพลังที่ล็อกลูมินาไว้ทำให้กระแสลูมินาไม่สามารถไหลได้",
  str_monster_desc_2000531 = "อิคลิพไซท์โพรเบอร์กลายพันธุ์ ว่ากันว่ามันกลายพันธุ์จนมีความสามารถมองเห็นระยะไกล พร้อมทั้งมีวิธีโจมตีระยะไกลที่ทรงพลังและแม่นยำอีกด้วย",
  str_monster_desc_2000541 = "อิคลิพไซท์วอร์มองเกอร์ที่กลายพันธุ์ พวกมันไม่เพียงแต่มีพลังการต่อสู้ที่เพิ่มขึ้น แต่ยังมีความสามารถพิเศษในการกัดกร่อนลูมินา",
  str_monster_desc_2000551 = "อิคลิพไซท์ประเภทใหม่ที่ปรากฏขึ้นในดินแดนลับ ว่ากันว่าพวกมันเกิดจากความรู้สึกแค้นเคืองของเผ่าพันธุ์โบราณที่ถูกอิคลิพไซท์กำจัด นี่เป็นวิธีเดียวที่อธิบายที่มาของความสามารถในการสาปแช่งอันทรงพลังที่พวกมันเชี่ยวชาญ",
  str_monster_desc_2000561 = "อิคลิพไซท์หายาก พวกมันดูเหมือนแฟนท่อมที่ล่องลอย เคลื่อนที่เร็ว และไม่มีใครโจมตีได้ เรียกกันอีกอย่างหนึ่งว่าภูตผี",
  str_monster_desc_2000571 = "อิคลิพไซท์พิเศษเหล่านี้คือประจักษ์พยานของพลังระเบิดของไวท์ชูมเมอร์ พวกมันเกิดขึ้นจากส่วนผสมระหว่างความชั่วร้ายและความเกลียดชังของเธอ เนื่องจากไม่สามารถเคลื่อนที่ได้ จึงใช้ออร่ามืดปกคลุมท้องฟ้า ซึ่งเพียงพอที่จะทำให้มีความสามารถในการสาปแช่งที่ทรงพลัง",
  str_monster_desc_2000581 = "ว่ากันว่าเป็นอีกสายพันธุ์หนึ่งของแคซซึมซึ่งเป็นอิคลิพไซท์ระดับต่ำ มันสนใจการเรียกอิคลิพไซท์ระดับสูง และสามารถทำลายตัวเองได้ด้วยแรงมหาศาล ทางเดียวที่จะหยุดสิ่งนี้ได้คือต้องกำจัดมันให้ได้ก่อนที่มันจะระเบิด",
  str_monster_desc_2000601 = "อิคลิพไซท์พิเศษที่เล็กและแทบจะมองไม่เห็นด้วยตาเปล่า ตัวของมันได้บวมขึ้นเป็นขนาดที่เห็นในปัจจุบันเนื่องจากผลกระทบของอารมณ์ด้านลบที่แรงกล้า",
  str_monster_desc_2000602 = "ภาพมายาที่เกิดขึ้นจากลูมินาติกส์ของดอว์น ซึ่งมีพลังเวทมนตร์แฝงอยู่",
  str_monster_desc_2000611 = "A special Eclipsite that was small and barely visible to the naked eye. Its body has swelled to its current size due to the effect of strong negative emotions.",
  str_monster_desc_2000701 = "อิคลิพไซท์พิเศษเหล่านี้ได้ตื่นขึ้นจากการหลับลึก พวกมันมีจำนวนมากแต่กลยุทธ์ค่อนข้างเรียบง่าย แต่ระวังด้วยนะเพราะพวกมันมีความสามารถในการเปลี่ยนรูปร่างด้วย!",
  str_monster_desc_2000702 = "ปราสาทปรักหักพังที่จมลึกอยู่ก้นทะเล เมื่อเสียงระฆังดังขึ้น กษัตริย์ผู้โดดเดี่ยวจะปลดปล่อยความพิโรธของเขาเข้าใส่ศัตรู",
  str_monster_desc_2000703 = "เดิมทีม้าศึกตัวนี้เป็นแค่ซากศพ ก่อนที่กษัตริย์ผู้โดดเดี่ยวจะปลุกมันให้ตื่นขึ้น ความแข็งแกร่งและความภักดีจากอดีตที่ยังคงอยู่ทำให้มันโจมตีศัตรูทั้งหมดของเจ้านายของมันโดยไร้ข้อกังขา",
  str_monster_desc_2000704 = "เดิมทีเป็นผู้ช่วยราชา สามารถมองเห็นเส้นทางในช่องว่างที่ผู้อื่นไม่สามารถมองเห็นได้ จากนั้นจะเคลื่อนที่เข้าโจมตีอย่างรวดเร็ว",
  str_monster_desc_2000705 = "เดิมทีเคยเป็นชนชั้นสูง การล้างแค้นผลักดันให้เธอมาที่ทะเลนี้ ซึ่งเธอได้ชุบชีวิตราชาโบราณในตำนานขึ้นมา... อย่างไรก็ดี พลังมืดที่เธอเรียกใช้ก็ได้กลืนกินจิตวิญญาณของเธอไปด้วย ทำให้เธอกลายเป็นอิคลิพไซท์",
  str_monster_desc_2000711 = "เบี้ยหลงทางพวกนี้ได้รับพลังจากช่องว่าง แม้ว่ากลยุทธ์จะยังคงเรียบง่าย แต่ประสิทธิภาพการต่อสู้กลับเพิ่มขึ้นอย่างมาก ห้ามประมาทเลยนะ",
  str_monster_desc_2000712 = "ป้อมที่ทำลายทุกอย่างในเส้นทาง เสียงระฆังของมันจะกลายเป็นฝันร้ายสุด ๆ ของศัตรูทุกตัว",
  str_monster_desc_2000713 = "ด้วยเสียงร้องที่น่าสะพรึงกลัวและกีบเท้าสะเทือนโลก เมื่อนักขี่เหล่านี้พุ่งเข้าหาศัตรู สิ่งเดียวที่หยุดพวกเขาได้คือความตายเท่านั้น",
  str_monster_desc_2000714 = "คำพูดที่โหดร้ายและความเสื่อมทรามที่ดังกึกก้อง... คอยระวังการโจมตีจากด้านข้างให้ดี",
  str_monster_desc_2000715 = "แคโรไลน์... ผู้คลั่งอำนาจที่กลายเป็นส่วนหนึ่งของช่องว่าง และได้รับพลังอำนาจเหนือประมาณ",
  str_monster_desc_2000901 = "ลือกันว่ามีอิคลิพไซท์ชนิดใหม่ได้ถูกสร้างขึ้นโดยอิคลิพส์เพื่อทะลายแนวป้องกันของออโรเรียน โดยมันจะทำลายภูมิประเทศรอบตัวมันด้วยการทำลายตัวเอง",
  str_monster_desc_2001001 = "อิคลิพไซท์ที่ครั้งหนึ่งเคยอาศัยอยู่ในห้วงลึกของดินแดนลับ เป็นเลิศเรื่องการโจมตีจากใต้ดิน นอกจากนี้ยังว่ากันว่าสามารถขุดเส้นทางใต้ดินให้อิคลิพไซท์ตัวอื่นได้อีกด้วย",
  str_monster_desc_2001301 = "เหตุการณ์เริ่มสงบแล้ว และตัวตนของศัตรูที่คุ้นเคยแต่ก็ห่างเหินกำลังจะเผยออกมา ได้เวลาพิสูจน์ความมุ่งมั่นของคุณแล้ว",
  str_monster_desc_2101301 = "สมุนของอิคลิพไซท์ อิคลิพไซท์ระดับสูงเรียกมา",
  str_monster_desc_4001301 = "สมุนของอิคลิพไซท์ อิคลิพไซท์ระดับสูงเรียกมา",
  str_monster_desc_2001401 = "หนวดซิมไบโอติกของคิตตี้พุส พวกมันจะส่งดาเมจที่ได้รับไปที่ร่างต้นโดยตรง",
  str_monster_desc_2900271 = "อิคลิพไซท์ประเภทนี้ผ่านการกลายพันธุ์ที่แปลกประหลาด ว่ากันว่าพลังการต่อสู้เทียบเท่ากับอิคลิพไซท์ชั้นสูง มันคือหัวหน้าของอิคลิพไซท์สวมเกราะทั้งหมดและมี HP สูงมาก",
  str_monster_desc_2900262 = "ออโรเรียนที่ถูกกัดกร่อนโดยพลังมืดอันแกร่งกล้า สูญเสียสติสัมปชัญญะในตนเองไปจนหมดสิ้นและอันตรายอย่างมาก",
  str_monster_desc_2900263 = "ในอดีต อีฟเสียสติไปเพราะ \"การรักษา\" ของสตรีลึกลับคนหนึ่ง ซึ่งทำให้เธอสูญเสียการควบคุมพลังของตนเองและเผาเมืองใต้ดิน \"แห่งนั้น\" จนราบคาบ ความแค้นและความรู้สึกผิดกำลังฉีกทึ้งหัวใจของเธอเมื่อโศกนาฏกรรมดังกล่าวได้เกิดขึ้นอีกซ้ำแล้วซ้ำเล่า... ช่วยระงับโทสะของเธอที",
  str_monster_desc_2900264 = "เด็กสาวผู้ลึกลับที่คุณเจอที่หุบเขาตาแดง เธอ \"สั่ง\" ให้พวกอิคลิพไซท์นำตัวอีฟไปโดยไม่มีผู้ใดทราบสาเหตุ",
  str_monster_desc_2900281 = "อิคลิพไซท์ประเภทหนึ่งที่มีความชาญฉลาดเพียงเล็กน้อยและไม่มีแรงใจอยู่ในตัว ไม่มีผู้ใดล่วงรู้เป้าหมายของมัน และได้แต่เดาว่ามันมีความเกี่ยวข้องกับวิกฤตดาร์กโอเวอร์ เรียกอีกชื่อหนึ่งว่าดาร์กโอเวอร์โอเมน",
  str_monster_desc_2900391 = "แม้ว่าจะเคลื่อนที่ได้ช้า แต่ก็มี DEF ที่แข็งแกร่ง และสามารถยิงระเบิดหุบเหวที่มีพลังมหาศาลได้ เรียกอีกอย่างหนึ่งว่าทรานสปอร์ตเตอร์",
  str_monster_desc_2900401 = "เดิมทีเคยเป็นเคเลสไทต์ แต่มาเข้าร่วมกับอิคลิพไซท์และมีพลังเพิ่มขึ้นมหาศาล",
  str_monster_desc_2900402 = "เดิมทีเคยเป็นเคเลสไทต์ แต่มาเข้าร่วมกับอิคลิพไซท์และมีพลังเพิ่มขึ้นมหาศาล",
  str_monster_desc_2900403 = "เดิมทีเคยเป็นเคเลสไทต์ แต่มาเข้าร่วมกับอิคลิพไซท์และมีพลังเพิ่มขึ้นมหาศาล",
  str_monster_desc_2900411 = "เดิมทีเคยเป็นสมาชิกของหน่วยผู้พิทักษ์ลูโมโพลิส เขาคือผู้ที่เอาชนะเชลต์ได้ และยินดีที่จะทำลายลูโมโพลิสเพื่อพวกเขา",
  str_monster_desc_2900421 = "หลังจากที่โนซาร์ดพ่ายแพ้ องค์กรไม่ทราบฝ่ายได้นำร่างของมันกลับไปทำการทดลองและแปรสภาพให้เป็นสัตว์ประหลาดที่น่าสะพรึงกลัว",
  str_monster_desc_2900422 = "อิคลิพไซท์ขนาดใหญ่ที่คล้ายคลึงกับมังกรยักษ์ ซ่อนตัวอยู่ในหุบเขาเขี้ยวเพลิงลุกโชน",
  str_monster_desc_2900431 = "มีหนอนทรายยักษ์ดึกดำบรรพ์ยึดครองพื้นที่แห่งนี้ตั้งแต่ที่มันถูกทำลาย เมื่อไม่นานมานี้ หลังจากที่ตื่นขึ้นจากการหลับใหลอันยาวนานก็เริ่มโจมตีผู้รุกรานที่ล่วงล้ำเข้ามาในพื้นที่",
  str_monster_desc_2900441 = "อิคลิพส์ได้แปรสภาพอัมบราฮัลก์ให้ทรงพลังมากยิ่งขึ้น นับแต่นั้นมาก็ได้รับมอบหมายให้สำรวจซากหอคอยและรับมือกับเหตุไม่แน่นอนทั้งหลาย",
  str_monster_desc_2900451 = "เดิมทีเป็นสัตว์ประหลาดที่เหมือนผี เริ่มพัฒนาขึ้นเพราะพลังแห่งแสงสว่างหลังจากที่ได้เข้ามายังดินแดนแห่งนี้ สามารถสร้างภาพมายาในสนามรบได้มากมายหลายแบบโดยใช้แสงหักเห",
  str_monster_desc_2900452 = "ประตูมิติที่เกิดขึ้นจากโฟโรชั่นอิคลิพไซท์ ใช้เพื่อซ่อนตัวและซุ่มโจมตีเมื่อพบจุดอ่อนของศัตรู",
  str_monster_desc_2900501 = "พัฒนามาจากไซฟอร์บ ดูดซับลูมินาเอาไว้อย่างมากจนไม่สามารถควบคุมสีของแสงโดยรอบได้ นอกจากนี้ยังใช้มานาเพื่อจับออโรเรียนที่อยู่ใกล้เคียงเพื่อโจมตีได้",
  str_monster_desc_2900601 = "สัตว์กลายพันธุ์ที่เกิดขึ้นหลังจากที่โซลมอร์ฟขององค์กรอิคลิพส์ได้ดูดซับพลังของหอคอยเข้าไป พวกมันปลดปล่อยลูมินาที่ดูดซับเข้าไปได้อย่างรวดเร็วเพื่อทำการโจมตีสังหารที่ทรงพลัง",
  str_monster_desc_2900611 = "สัตว์กลายพันธุ์ที่องค์กรอิคลิพส์สร้างขึ้นโดยใช้ส่วนประกอบจากอิคลิพไซท์ระดับสูงอย่างแฟนท่อม พวกมันมีความสามารถในการแยกร่างที่เก่งกล้า และทำลายได้โดยการกำจัดตัวมันและตัวโคลนทั้งหมดเท่านั้น",
  str_monster_desc_2900641 = "คาราคาไลต์หลายตัวได้รวมร่างกันและกลายพันธุ์เป็นอิคลิพไซท์ระดับสูง มีความเชี่ยวชาญด้านอิคลิพเซียมที่ทรงพลังยิ่งกว่าเดิม เทคนิคพิเศษในการกักกันลูมินาทำให้การรับมือกับมันเป็นเรื่องที่ยากลำบากมาก",
  str_monster_desc_2900651 = "ว่ากันว่าตอนที่ยีนของทาบาอัดถูกฉีดเข้าไปในร่างของอิคลิพไซท์ที่ทรงพลัง อิคลิพไซท์รูปร่างหน้าตาคล้ายทาบาอัดจะถือกำเนิดขึ้น ด้วยความสามารถอันทรงพลังยิ่งขึ้น และยังเชื่อฟังอย่างไม่มีข้อกังขาอีกด้วย",
  str_monster_desc_2900661 = "ของเล่นใหม่อีกอย่างหนึ่งของฟอร์เซคิน ตรงกันข้ามกับบอร์ดอมตัวเก่า มันมีความสามารถอันน่าสะพรึงกลัวที่สามารถกัดกร่อนลูมินาได้นอกเหนือจากพลังมหาศาลที่มี จึงไม่ควรทำเป็นเล่นเด็ดขาด",
  str_monster_desc_2900671 = "หลังจากที่เมล็ดพันธุ์ในร่างกายของเธอฝังตัวและเติบโต ร่างที่ดูดซับพลังงานปริมาณมหาศาลเอาไว้ก็แตกต่างไปจากเดิมอย่างสิ้นเชิง แม้ว่ารูปลักษณ์ภายนอกจะเปลี่ยนแปลงเพียงเล็กน้อยก็ตาม",
  str_monster_desc_2900681 = "อิคลิพไซท์ฟลิกเกอร์กลายพันธุ์ มันมีความว่องไวอย่างมาก และสามารถทำตัวเหมือนวิญญาณที่ไปมาโดยปราศจากร่องรอย วิธีการทั่วไปไม่น่าจะทำอะไรมันได้",
  str_monster_desc_2900701 = "หุ่นยนต์ที่ทิ้งไว้โดยอารยธรรมโบราณ ออกแบบมาพิเศษให้สามารถทำงานต่อไปได้แม้ว่าจะถูกทำลายไปบางส่วน รับมือได้ยากอย่างยิ่ง",
  str_monster_desc_2900711 = "หุ่นยนต์ที่ปรากฏตัวขึ้นหลังจากการแยกตัวของ T-1024 ก่อนอื่นมันจะตามหา T-256s อีกตัวหนึ่งก่อน จากนั้นก็พยายามรวมตัวกันเป็น T-1024 ตัวใหม่",
  str_monster_desc_2910711 = "หุ่นยนต์เปี่ยมประสิทธิภาพที่ไม่ทราบที่มา มีความสามารถในการบุกโจมตีที่ไม่ควรประมาท",
  str_monster_desc_29107141 = "\"บี๊ป! บี๊ป!\"",
  str_monster_desc_29107111 = "\"บี๊ป! บี๊ซซซ!\"",
  str_monster_desc_2800241 = "\"คุณกำลังมองหาอะไรอยู่ อย่าคิดว่าจะเจอข้อมูลอะไรเกี่ยวกับฉันได้จากที่นี่ ไม่ว่าจะออโรเรียนหรือเคเลสไทต์ก็ไม่สามารถเข้าใจการไล่ล่าระดับสูงได้หรอก\"",
  str_monster_desc_2900801 = "ราชาโบราณที่ถูกฝังลึกอยู่ในมหาสมุทรมานานชั่วกัปชั่วกัลป์ ราชินีผู้มากเล่ห์ได้ปลุกให้ตื่นขึ้น และตอนนี้สาบานว่าจะจับศัตรูขังไว้ในช่องว่างชั่วนิรันดร์",
  str_monster_desc_2900811 = "ราชาโบราณในสถานะเดือดดาลจะควบคุมและเล่นสนุกกับผู้รุกรานทั้งหมดทั้งปวงจนกว่าความตายจะมารับตัวไป",
  str_monster_desc_2900911 = "ร่ำลือกันว่าเป็นอิคลิพไซท์ระดับสูงที่เคยเข้าร่วมการต่อสู้ที่ดุเดือดหลายครั้งก่อนหน้านี้ ไม่ทราบจำนวนที่แน่ชัดและมีความสามารถในการบินที่หายาก ตอนนี้พวกมันได้ตื่นขึ้นจากการหลับใหลและพร้อมที่จะพุ่งชนออโรเรียนไปสู่ฝันร้ายครั้งใหม่",
  str_monster_desc_2900912 = "อิคลิพไซท์พวกนี้ติดตามไฮลินเจอร์และสามารถช่วยเหลือนายของมันในการต่อสู้",
  str_monster_desc_2901001 = "เดิมทีเป็นชนชั้นสูงของลูโมโพลิส หลังจากถูกขับไล่ออกจากเมือง ความขุ่นเคืองต่อประเทศชาติที่เคยอยู่ได้ก่อตัวจนถึงขั้นทรยศไปอยู่ฝ่ายอิคลิพส์และพยายามโค่นล้มการปกครองของลูโมโพลิส เมื่อแผนการล้มเหลว เขาก็จมดิ่งสู่ความวิกลจริตยิ่งกว่าเดิม เขามีความเกลียดชังเป็นเชื้อเพลิงคอยผลักดัน...",
  str_monster_desc_2901101 = "เนื่องจากไม่สามารถเอาชนะความกลัวได้ อีกทั้งหมดหวังที่จะทำความทะเยอทะยานให้เป็นจริง เขาจึงทำการเปลี่ยนร่างชั่วคราวที่แสนอันตรายโดยไม่คิดให้ถี่ถ้วน และกลายพันธุ์เป็นสิ่งมีชีวิตที่น่าสะพรึงกลัวนี้",
  str_monster_desc_2901201 = "วีรบุรุษโบราณที่ยอมกลายมาเป็นอิคลิพไซท์เพื่อต่อสู้กับเหล่าอิคลิพไซท์ ทว่าตอนนี้เขาเป็นเพียงมอนสเตอร์ไร้สำนึกเท่านั้น",
  str_monster_desc_2901300 = "อิคลิพไซท์ลึกลับไม่ทราบแหล่งกำเนิด มีตัวตนที่ไม่สอดคล้องกับความเป็นจริงที่คุณรู้จัก",
  str_monster_desc_2901301 = "เหตุการณ์เริ่มสงบแล้ว และตัวตนของศัตรูที่คุ้นเคยแต่ก็ห่างเหินกำลังจะเผยออกมา ได้เวลาพิสูจน์ความมุ่งมั่นของคุณแล้ว",
  str_monster_desc_2901401 = "สหายคู่ใจของเกรเทล โดยปกติจะนิ่งเงียบ แต่จะบ้าคลั่งอย่างมากเมื่อต่อสู้ ต้องระวังมันให้ดี",
  str_monster_desc_2901501 = "สหายคู่ใจของเกรเทล ขี้เล่นและกระฉับกระเฉง ชอบจัดการกับศัตรูเป็นกลุ่มโดยเฉพาะ",
  str_monster_desc_2901601 = "สหายคู่ใจของเกรเทล มีสองขาอันทรงพลังที่สามารถผลักศัตรูทั้งหมดให้กระเด็นออกไปได้",
  str_monster_desc_2901701 = "สหายคู่ใจของเกรเทล ดูแล้วเหมือนแมวที่มีหลายขา... น่ารักอยู่นะ แต่ก็พิลึกชอบกล",
  str_monster_desc_2901801 = "ผู้อาศัยอยู่ในเมืองที่สาบสูญและเป็นลูกสาวของซีมัส นักสำรวจแห่งอิลลูมินา ดูเหมือนพวกเธอจะตั้งตนเป็นเจ้าของสถานที่แห่งนี้",
  str_monster_desc_2901901 = "อดีตหัวหน้ากองพลวิสป์ ผู้ซึ่งอุทิศตนเพื่อต่อสู้กับผู้บุกรุกเกาะเมฆา",
  str_monster_desc_2901911 = "นากิที่บ้าคลั่งจะโจมตีทุกคนที่เธอเห็นว่าเป็นผู้บุกรุก",
  str_monster_desc_2902001 = "จอมเผด็จการที่มาจากอีกเกาะหนึ่งทางตะวันออกไกลเพื่อปกครองเกาะเมฆา\nเขาจะทำทุกอย่างเพื่อประกาศอำนาจอธิปไตยในดินแดนแห่งนี้",
  str_monster_desc_2902101 = "ด้วยความยึดมั่นในความคิดของตนเอง เขาจึงกลายเป็นชายที่น่ารังเกียจและสาบานว่าจะกำจัดทุกคนที่แข็งข้อ",
  str_monster_desc_2902201 = "อิคลิพไซท์ทรงพลังที่เคยอยู่ตามลำพังในซากโบราณมาหลายปี มันบ้าคลั่งโดยสมบูรณ์และจะสู้กับคนนอกจนตัวตาย",
  str_monster_desc_2902202 = "อดีตทหารอิลลูมินาที่กลายเป็นอิคลิพไซท์ภายใต้อิทธิพลของพลังความมืด ความเกลียดชังเข้าครอบงำสติและช่วงชิงเกียรติยศในอดีตของเขาไปหมดแล้ว",
  str_monster_desc_2902301 = "ปัญญาประดิษฐ์ในฐานใต้ดินของอีราเวลที่คอยปกป้องฐานแห่งนี้มาหลายพันปี และเป็นผู้ที่คอยขับไล่ศัตรูที่บุกรุกเข้ามา",
  str_monster_desc_2902401 = "ปัญญาประดิษฐ์ในฐานใต้ดินของอีราเวลที่ดูร่างใหญ่และหนักอึ้ง คือเพื่อนของคลอเดีย",
  str_monster_desc_2902501 = "พ่อบ้านเหรียญทองของตระกูลแอนเดอร์เซนผู้ไม่เคยละเลยต่อคราบสกปรก ขยะ หรือแมลงที่น่ารังเกียจ",
  str_monster_desc_2902601 = "ว่ากันว่ามันคือ \"พี่ชาย\" ของแฟนท่อมในรัตติกาลนิรันดร์ มันสามารถใช้กลวิธีต่าง ๆ ตามช่วงเวลาของวันและจัดการได้ยากนัก",
  str_monster_desc_2902701 = "\"คุณกำลังมองหาอะไรอยู่ อย่าคิดว่าจะเจอข้อมูลอะไรเกี่ยวกับฉันได้จากที่นี่ ไม่ว่าจะออโรเรียนหรือเคเลสไทต์ก็ไม่สามารถเข้าใจการไล่ล่าระดับสูงได้หรอก\"",
  str_monster_ability_2900063 = "โจมตีเป้าหมายด้านหน้าด้วยกรงเล็บยักษ์และสามารถบินขึ้นไปบนอากาศเพื่อระเบิดพื้นที่ที่กำหนดบนพื้นดิน",
  str_monster_ability_2900141 = "มันคือผู้มากทักษะในการโจมตีระยะประชิด การโจมตีของมันจะทำให้เป้าหมายมึนงงพร้อมกับเรียกกลูมกูล หลังจากบ้าคลั่ง การโจมตีปกติของมันจะกลายเป็นการโจมตีสองเท่า พร้อมทั้งมีขอบเขตสกิลสูงขึ้นอย่างมาก และมันสามารถเรียกแชโดว์ไกสต์และกลูมกูลพร้อมกันได้อีกด้วย",
  str_monster_ability_2900142 = "เก่งกาจในการต่อสู้ระยะใกล้ มีความสามารถในการเรียกอิคลิพไซท์ตัวอื่น ขณะอยู่ในโหมดบ้าคลั่งจะฟื้นฟู 20% ของพลังชีวิตสูงสุด หลังจากโหมดบ้าคลั่งจบลง การโจมตีปกติของมันสามารถโจมตีได้สองครั้ง และระยะสกิลก็เพิ่มขึ้นอย่างมาก",
  str_monster_ability_2900181 = "ผู้มากทักษะในการโจมตีระยะไกล ทำให้เป้าหมายมึนงงและเรียกแชโดว์ไกสต์มา เมื่อบ้าคลั่ง การโจมตีปกติของเธอจะโจมตีสองครั้งด้วยระยะสกิลที่เพิ่มขึ้นอย่างมาก สามารถเรียกแชโดว์ไกสต์และกลูมกูลพร้อมกันได้",
  str_monster_ability_2900182 = "เก่งกาจในการต่อสู้ระยะไกล การโจมตีสามารถทำให้เป้าหมายกระเด็นถอยหลังได้ มีความสามารถในการเรียกอิคลิพไซท์ตัวอื่น ขณะอยู่ในโหมดบ้าคลั่ง จะฟื้นฟู 20% ของพลังชีวิตสูงสุด หลังจากโหมดบ้าคลั่งจบลง การโจมตีปกติของมันสามารถโจมตีได้สองครั้ง และระยะสกิลก็เพิ่มขึ้นอย่างมาก",
  str_monster_ability_2900201 = "เก่งเรื่องการใช้ร่างกายที่มีขนาดใหญ่โจมตีศัตรูด้านหน้า จะขุดโพรงลงไปใต้พื้นดินและทำดาเมจกับเป้าหมายที่อยู่ใกล้เคียงเมื่อโผล่ขึ้นมา นอกจากนี้ยังเรียกเบิสต์บัคได้อีกด้วย",
  str_monster_ability_2900211 = "การโจมตีระยะประชิดจะตามมาด้วยการผลักกระเด็น สามารถเรียกกองหินออกมาโจมตีได้ เป้าหมายที่ถูกโจมตีจะกระเด็นถอยหลัง พื้นที่ที่ถอยไปจะเกิดกองหินขึ้นมา สามารถโจมตีทั้งจอได้ด้วย และดาเมจที่สร้างได้จะกำหนดโดยจำนวนของหิน",
  str_monster_ability_2900221 = "การโจมตีปกติจะมาพร้อมการผลักกระเด็น สามารถเปลี่ยนพื้นที่การต่อสู้ให้เป็นลูมินาธาตุของตนได้ และปลดปล่อยการโจมตีหลากหลายรูปแบบตามธาตุของตน: ไฟ - ดาเมจพื้นที่วงกว้างด้วยเอฟเฟกต์เผาไหม้, สายฟ้า - ดาเมจทั้งจอที่สุ่มสร้างสไปค์เพสต์",
  str_monster_ability_2900231 = "การโจมตีระยะใกล้ของฟิเล็กซ์มาพร้อมกับการผลักกระเด็น และ ATK สกิลของเขาจะทำให้เป้าหมายมึนงง",
  str_monster_ability_2900232 = "วานี่สามารถใช้พลังงานเพื่อโจมตีจากระยะไกลและฟื้นฟู HP ให้ฟิเล็กซ์ได้",
  str_monster_ability_2900241 = "มันจะปาระเบิดเพลิงเข้าใส่สมรภูมิ ทำให้ยูนิตที่ผ่านมาถูกเผาไหม้ ทั้งยังพุ่งเข้าใส่และทำให้ศัตรูมึนงงได้เมื่อโจมตีโดน โดยใช้ออร่าดาบโจมตีเป้าหมายสองแถวตรงหน้า",
  str_monster_ability_2900251 = "มันจะโจมตีเป็นพื้นที่รูปบวก และเรียกลูกสมุนร่างโคลนมาต่อสู้เคียงข้าง หลังจากโคลนแล้วจะดูดซับ HP ของร่างโคลนก่อนหน้าเพื่อฟื้นฟู HP ให้ตัวเอง เมื่อ HP ของมันน้อยกว่า 50% การโจมตีปกติจะกลายเป็นการโจมตีสองครั้ง การโจมตีพื้นที่จะกลายเป็นโจมตีทั้งจอ",
  str_monster_ability_2000011 = "ยูนิตต่อสู้หลักของอิคลิพไซท์ เชี่ยวชาญการต่อสู้ระยะใกล้ด้วยกรงเล็บ",
  str_monster_ability_2000071 = "อิคลิพไซท์ตัวใหญ่มีหน้าที่ทำลายป้อมปราการทั้งหลาย มีความสามารถเหลือเฟือที่จะทำลายสิ่งปลูกสร้าง",
  str_monster_ability_2000101 = "พลสอดแนมของอิคลิพไซท์ที่สามารถใช้แสงที่เปล่งออกจากปากโจมตีศัตรูจากระยะไกล",
  str_monster_ability_2000111 = "มีชื่อเสียงด้านการใช้บาเรียต้านการโจมตีมากกว่า",
  str_monster_ability_2000121 = "อิคลิพไซท์ที่มีความสามารถในการเรียกลูกสมุนในระดับต่ำ ไม่สามารถเคลื่อนที่ได้ด้วยตัวเองและต่อสู้โดยการเรียกเดรตเชอร์",
  str_monster_ability_20001211 = "อิคลิพไซท์ที่มีความสามารถในการเรียกลูกสมุนระดับต่ำ ไม่สามารถเคลื่อนที่ได้ด้วยตัวเองและต่อสู้ด้วยการเรียกอิคลิพไซท์",
  str_monster_ability_20001221 = "อิคลิพไซท์ที่มีความสามารถในการเรียกลูกสมุนในระดับต่ำ ไม่สามารถเคลื่อนที่ได้ด้วยตัวเองและต่อสู้โดยการเรียกสเปลล์ฮาวนด์",
  str_monster_ability_20001231 = "อิคลิพไซท์ที่มีความสามารถในการเรียกลูกสมุนในระดับต่ำ ไม่สามารถเคลื่อนที่ได้ด้วยตัวเองและต่อสู้โดยการเรียกดาร์กวอสป",
  str_monster_ability_20001241 = "อิคลิพไซท์ที่มีความสามารถในการเรียกลูกสมุนในระดับต่ำ ไม่สามารถเคลื่อนที่ได้ด้วยตัวเองและต่อสู้โดยการเรียกเดรดเบลด",
  str_monster_ability_20001251 = "อิคลิพไซท์ที่มีความสามารถในการเรียกลูกสมุนในระดับต่ำ ไม่สามารถเคลื่อนที่ได้ด้วยตัวเองและต่อสู้โดยการเรียกสแลชเชอร์",
  str_monster_ability_20001261 = "Eclipsite ที่มีความสามารถในการเรียกพื้นฐาน ไม่สามารถเคลื่อนที่ได้เองและต่อสู้โดยอัญเชิญ Prober",
  str_monster_ability_2000131 = "อิคลิพไซท์ระดับต่ำ มีความสามารถเพียงแค่โจมตีพื้นฐานตามสัญชาตญาณเท่านั้น",
  str_monster_ability_2000141 = "อิคลิพไซท์ที่มี ATK ระดับทั่วไป มีหน้าที่รวบรวมเสบียง",
  str_monster_ability_2000151 = "ชำนาญการใช้สองหมัดขนาดใหญ่ต่อสู้แบบประชิดตัว การฟาดค้อนลงบนพื้นจะทำดาเมจและทำให้เป้าหมายมึนงง",
  str_monster_ability_2000161 = "ใช้หอกโจมตีเป้าหมายและรับความสามารถในการเรียกแชโดว์ไกสต์",
  str_monster_ability_2000171 = "อิคลิพไซท์ร่างวัตถุประเภท II: อิคลิพไซท์รักษา มีรูปร่างเป็นผลึกสีดำและสามารถรักษาอิคลิพไซท์ตัวอื่นได้เมื่อปล่อยออกมา",
  str_monster_ability_2000181 = "อิคลิพไซท์ร่างวัตถุประเภท I: อิคลิพไซท์ระยะไกล มีรูปร่างเป็นผลึกสีดำ สามารถร่วมการต่อสู้ได้เมื่อปล่อยออกมา แต่พลังการต่อสู้ค่อนข้างอ่อนแอ",
  str_monster_ability_2000211 = "อิคลิพไซท์ที่มีความสามารถในการรักษา มีหน้าที่ฟื้นฟู HP ให้อิคลิพไซท์ตัวอื่นเป็นหลัก",
