  str_monster_desc_21601191 = "ชาวอิลลูมินาที่เพิ่งมาใหม่ เป็นอัจฉริยะในการต่อสู้ แต่เป็นคนสันโดษ หุนหันพลันแล่น และมีปัญหาในการสื่อสาร เธอต้องการได้รับเกียรติยศในการต่อสู้และพิสูจน์ตัวเองอย่างยิ่ง",
  str_monster_desc_21601171 = "ทหารผ่านศึกที่เคยรบในแนวป้องกันของอิลลูมินา ตั้งแต่ปลดเกษียณจากหน้าที่ประจำก็หันมาทำงานในหน่วยพลาธิการ ภายนอกดูขึงขัง แต่ภายในนั้นอ่อนโยน เป็นสหายที่พึ่งพาได้ในสนามรบ",
  str_monster_desc_21601291 = "รองผู้บัญชาการหน่วยทหารรับจ้างอัมบราตัน ผู้มีเกียรติ รอบรู้ทุกอย่างในเมือง ตอนนี้เขากำลังทำงานอย่างหนักเพื่อขยายกองกำลังของทหารรับจ้าง",
  str_monster_desc_21500991 = "ทหารรับจ้างเร่ร่อนในอัมบราตัน เกิดมาพร้อมคำสาปทำให้เป็นโลหิตจางและต้องพึ่งพาดาบเวทมนตร์เพื่อเอาตัวรอด",
  str_monster_desc_21500751 = "บุคลากรฝ่ายเทคโนโลยีของเรดีเซล เวรนช์ที่มั่นใจในเทคโนโลยีการสื่อสารของเธอมาก เธอชอบบ่นและตะคอกคนอื่นในช่องสื่อสารแต่กลับหงุดหงิดเมื่อเจอปัญหา",
  str_monster_desc_21300531 = "พ่อค้าจากเรดีเซล เวรนช์ เขาคือนักซื้อขายหน้าเงินทั่วไปผู้ไม่เคยพลาดโอกาสสร้างกำไร... แม้ในเวลาที่ต้องเจอกับงานยาก ก็ได้มีดสั้นนี่แหละช่วยเอาไว้",
  str_monster_desc_21400401 = "เด็กสาวผู้ชื่นชอบระเบิดและมักจะตื่นเต้นผิดวิสัยเมื่อมีอะไรระเบิด ความบ้าคลั่งเช่นนี้คือตั๋วสู่เรดีเซล เวรนช์ ในฐานะสมาชิกเรดีเซล เธอใช้เวลาทั้งหมดไปกับการศึกษาวัตถุระเบิด และไม่สนใจเลยแม้แต่นิดว่าชีวิตจะตกอยู่ในอันตรายหรือไม่",
  str_monster_ability_21601191 = "เชี่ยวชาญการโจมตีระยะไกล ทำดาเมจในพื้นที่แถวแนวตั้ง",
  str_monster_ability_21601171 = "เชี่ยวชาญการโจมตีระยะประชิด ใช้สกิลทำดาเมจพื้นที่เป็นวงกว้างใส่ศัตรูรอบตัว",
  str_monster_ability_21601291 = "เชี่ยวชาญการโจมตีระยะไกล ใช้สกิลโจมตีทั้งจอเพื่อทำดาเมจและติดตราปรสิตให้ศัตรู ทุกครั้งที่ศัตรูเคลื่อนที่จะได้รับดาเมจจากตราปรสิต",
  str_monster_ability_21500991 = "เชี่ยวชาญการโจมตีแบบ AOE สกิลจะเพิ่ม ACT และ ATK ให้เธอเองและทำดาเมจพื้นที่วงกว้าง",
  str_monster_ability_21500751 = "เชี่ยวชาญการโจมตีระยะไกล การโจมตีของเธอจะติดสถานะพิษให้ศัตรู",
  str_monster_ability_21300531 = "เชี่ยวชาญการโจมตีระยะประชิด การโจมตีของเขาจะติดสถานะเลือดไหลให้ศัตรู",
  str_monster_ability_21400401 = "เธอไม่เคลื่อนที่แต่จะใช้การโจมตีแบบ AOE เปลี่ยนธาตุของช่องที่อยู่ในระยะ และติดสถานะเผาไหม้ให้ศัตรู",
  str_monster_name_1300221 = "ริค เลื่อยไฟฟ้า",
  str_monster_desc_1300221 = "เด็กชายตัวเตี้ยที่บ้าบิ่นและเอะอะโวยวายผู้ไม่เคยหยุดนิ่งและมักสวมหมวกกระต่ายอยู่เสมอ เขาผลักดันขีดจำกัดของตัวเองในการต่อสู้อยู่ตลอดเวลาและมักมีคนเข้าใจผิดว่าเขารนหาที่ตาย ที่ยังอยู่รอดได้นี่ก็มหัศจรรย์มากแล้ว",
  str_monster_ability_1300221 = "ริค เลื่อยไฟฟ้าทำดาเมจใส่ยูนิตศัตรูที่อยู่ใกล้ที่สุดแถวช่องสีแดง",
  str_monster_name_1300521 = "โดฟ",
  str_monster_desc_1300521 = "คนส่งจดหมายที่ทำงานให้สหพันธรัฐอิลลูมินา แต่เธอก็ไม่ใช่สมาชิก แค่ให้บริการด้านไปรษณีย์เท่านั้น แถมยังขี้เกียจและไม่ใส่ใจหน้าที่การงานอีกด้วย ยอมทำทุกอย่างเพื่อที่จะผัดผ่อนหรือหลบเลี่ยงการทำงาน",
  str_monster_ability_1300521 = "โดฟทำดาเมจใส่ยูนิตศัตรูที่อยู่ใกล้ที่สุดแถวช่องสีเขียว",
  str_monster_name_1400321 = "แองเจิล",
  str_monster_desc_1400321 = "เจ้าหน้าที่ศาลยุติธรรมแห่งลูโมและนางฟ้าปีกเดียว เธอเป็นคนจิตใจอ่อนไหวง่ายและรักเกียรติยศศักดิ์ศรีของตนมาก แม้ว่าอายุจะยังน้อย แต่เธอก็ใช้ชีวิตในช่วงสงครามมาแล้ว",
  str_monster_ability_1400321 = "แองเจิลทำดาเมจใส่ยูนิตศัตรูที่อยู่ใกล้ที่สุดแถวช่องสีเหลือง",
  str_monster_name_1501491 = "รอย",
  str_monster_desc_1501491 = "ผู้จัดการพลาธิการแห่งเรดีเซล เวรนช์ แม้ว่าเขาจะดูไร้ระเบียบ แต่ที่จริงแล้วเขาเป็นคนที่รอบคอบมากและปกป้องทุกคนในเรดีเซล เวรนช์",
  str_monster_ability_1501491 = "รอยทำดาเมจใส่ยูนิตศัตรูที่อยู่ใกล้ที่สุดแถวช่องสีเหลือง",
  str_monster_name_1400411 = "มิสบลังค์",
  str_monster_desc_1400411 = "หญิงสาวผู้สงบนิ่งและสง่างาม ทำหน้าที่เป็นผู้นำทางสำหรับคนใหม่ที่เพิ่งมาถึงลูโมโพลิส สงบเสงี่ยมแม้ในยามภัยพิบัติ บ่งบอกถึงอดีตที่ไม่ธรรมดา แต่ถ้ามีใครถามเรื่องนี้ เธอมักจะตอบด้วยรอยยิ้มที่เป็นปริศนา",
  str_monster_ability_1400411 = "มิสบลังค์ไม่เพียงทำดาเมจใส่ยูนิตศัตรูที่อยู่ใกล้ที่สุดแถวช่องสีน้ำเงินเท่านั้น แต่ยังจะเปลี่ยนช่องทั้งหมดรอบตัวเธอให้เป็นสีน้ำเงินด้วย",
  str_monster_name_1300471 = "โซยา",
  str_monster_desc_1300471 = "นักวิจัยอัจฉริยะแห่งสหพันธรัฐอิลลูมินาผู้กระหายในการศึกษาหาความรู้จนไม่สนใจอย่างอื่น... กับผู้บัญชาการกองทัพคนหนึ่งเท่านั้น แม้เธอจะดูเงียบ ๆ แต่ถ้าบุ่มบ่ามเข้าหาเธอก็อาจจะโดนเยาะเย้ยได้ เพื่อประโยชน์ของทุกคน อย่าไปกวนเธอให้บ่อยนักจะดีกว่า",
  str_monster_ability_1300471 = "โซยาฟื้นฟู HP ให้กับเพื่อนร่วมทีมที่เหลือ HP ต่ำสุด",
  str_monster_name_1300531 = "โจมู",
  str_monster_desc_1300531 = "พ่อค้าจากเรดีเซล เวรนช์ เขาคือนักซื้อขายหน้าเงินทั่วไปผู้ไม่เคยพลาดโอกาสสร้างกำไร... แม้ในเวลาที่ต้องเจอกับงานยาก ก็ได้มีดสั้นนี่แหละช่วยเอาไว้",
  str_monster_ability_1300531 = "โจมูจะสร้างดาเมจใส่ศัตรูภายในวงรอบตัว 1 ชั้น",
  str_monster_name_1201631 = "ทัวร์ด็อก",
  str_monster_desc_1201631 = "บุคคลปริศนาที่มาจากทางตอนเหนือ หลงใหลในการสร้างสรรค์ผลงานเกม ทุกครั้งที่พบเจอกับใครก็มักจะถามว่า \"คุณมีไอเดียอะไรไหม?\"",
  str_monster_ability_1201631 = "มีความมุ่งมั่นแรงกล้าต่อการเต้นรำ",
  str_monster_name_1600061 = "คาร์ลีน",
  str_monster_desc_1600061 = "กัปตันสวนลูโมคนนี้เป็นบุตรสาวของชวาตส์ หญิงสูงศักดิ์ผู้นี้ไม่มีทางอ่อนข้อให้กับสิ่งเลวทราม เธอเคารพกฎระเบียบและรังเกียจความชั่วเป็นที่สุด สิ่งที่น่าอัศจรรย์ยิ่งกว่านั้นก็คือ เธอกลายมาเป็นอัศวินได้ด้วยความพยายามของตนเองโดยไม่พึ่งพาอิทธิพลของบิดา",
  str_monster_ability_1600061 = "คาร์ลีนไม่เพียงทำดาเมจใส่ยูนิตศัตรูที่อยู่ใกล้ที่สุดแถวช่องสีน้ำเงินเท่านั้น แต่ยังจะสร้างดาเมจใส่ศัตรูอื่น ๆ ในแถวแนวตั้งเดียวกันและผลักพวกมันให้ถอยไปด้วย",
  str_monster_name_1600111 = "ชาโรนา",
  str_monster_desc_1600111 = "ผู้บัญชาการกองทัพแห่งสหพันธรัฐอิลลูมินาและหญิงงามผู้เยือกเย็นที่ครอบครองพลังแห่งมังกร แม้ว่าภายนอกเธอจะดูเย็นชา แต่ชาโรนาก็เป็นคนที่คุณไว้วางใจได้ พื้นเพของเธอเป็นปริศนา หลังจากเข้าร่วมกับสหพันธรัฐ เธอก็ได้เป็นผู้บัญชาการกองทัพเพราะมีผลงานทางการทหารที่ยอดเยี่ยม เธอม้กพกดาบเพลิงสีฟ้าที่เป็นสัญลักษณ์แทนบรรพบุรุษของเธอติดตัวไว้เสมอ",
  str_monster_ability_1600111 = "ชาโรนาทำดาเมจใส่ศัตรูภายในวงรอบตัว 2 ชั้น",
  str_monster_name_1500331 = "ไวซ์",
  str_monster_desc_1500331 = "สมาชิกของสหพันธรัฐอิลลูมินาผู้มีจิตใจอ่อนโยน นอกจากมีพรสวรรค์ ขยันขันแข็ง และกระตือรือร้นอย่างมากแล้ว เธอยังได้รับการฝึกฝนอย่างหนักตั้งแต่ยังเด็กเนื่องจากนายทหารระดับสูงเห็นแววของเธอ ปัจจุบันได้รับการแต่งตั้งเป็นกัปตันทีมสำรวจที่รับผิดชอบในการค้นหาและขุดค้นซากโบราณ",
  str_monster_ability_1500331 = "ไวซ์ไม่เพียงทำดาเมจใส่ยูนิตศัตรูที่อยู่ใกล้ที่สุดแถวช่องสีน้ำเงินเท่านั้น แต่ยังจะสร้างดาเมจต่อเนื่องใส่ศัตรูที่อยู่ใกล้ที่สุดด้วย",
  str_monster_name_1600021 = "ฮิอิโระ",
  str_monster_desc_1600021 = "หญิงสาวผู้มีทักษะการต่อสู้อันเก่งกาจไม่มีผู้ใดเทียบ ในฐานะผู้บัญชาการกองทัพของสหพันธรัฐอิลลูมินา เธอเป็นที่กล่าวขวัญในเรื่องความเข้มงวด จริงจัง และมุ่งมั่น ดาบคาตานะในมือและความมั่นใจที่มาพร้อมกับความรอบคอบในทุกครั้งที่เผชิญการต่อสู้ ทำให้เธอคว้าชัยชนะมาได้นับครั้งไม่ถ้วน",
  str_monster_ability_1600021 = "ฮิอิโระไม่เพียงทำดาเมจใส่ยูนิตศัตรูที่อยู่ใกล้ที่สุดแถวช่องสีเขียวเท่านั้น แต่ยังจะสร้างซากุระแดงฉานใส่ศัตรูที่อยู่ใกล้ที่สุดด้วย",
  str_monster_name_2800601 = "บูลล็อก 8",
  str_monster_desc_2800601 = "จากการออกแบบเพื่อแรลลี่โดยเฉพาะ ยานพาหนะจึงถูกดัดแปลงให้เหมาะสมกับภูมิประเทศที่สมบุกสมบัน และไม่เพียงมีความทนทานเท่านั้น แต่ยังติดอาวุธไว้เพียบด้วย",
  str_monster_ability_2800601 = "ร่ายสกิลโดยไม่มีนักขับไม่ได้",
  str_monster_name_2000191 = "โตโต้",
  str_monster_desc_2000191 = "ในโลกแห่งความเป็นจริงแล้ว สแลชเชอร์น้อยทุกตัวต่างก็มีความฝัน เพียงแต่ไม่มีใครสนใจที่จะถามมันเท่านั้นแหละ",
  str_monster_name_1500901 = "บาร์บาร่า",
  str_monster_desc_1500901 = "นักร้องไอดอลของเรดีเซล เวรนช์ ดูภายนอกแล้วบาร์บาร่าอ่อนโยนและนิสัยดีแต่จะเผยด้านฉุนเฉียวออกมาเมื่อพบแฟนคลับที่ข้ามเส้นกันเกินไป เธอเดินทางไปทุกที่เพื่อก้าวสู่ความเป็นไอดอลที่โด่งดังที่สุด",
  str_monster_ability_1500901 = "Barbara สร้างความเสียหายแก่ศัตรูทั้งหมดที่ครอบครองกระเบื้องสีแดง",
  str_monster_name_1501141 = "เจเนวีฟ",
  str_monster_desc_1501141 = "นักล่ารางวัลชั้นสูงของทรู ออเดอร์ที่เป็นคนร่าเริงและชอบดื่มเหล้าจินเป็นครั้งคราว ขณะนี้เธอกำลังสร้างเครือข่ายข่าวกรองเพื่อตามหาบุคคลคนหนึ่งอยู่",
  str_monster_ability_1501141 = "Genevieve กระโดดใส่ศัตรูที่อยู่ในแนวทแยงจากตำแหน่งของเธอ และหลังจากลงสู่พื้น สร้างความเสียหาย 1 กลุ่มที่อยู่รอบๆ หากมีเป้าหมายอยู่ที่จุดลงจอด เธอจะสร้างความเสียหายอย่างรุนแรงต่อเป้าหมายและกระแทกพวกมันให้ถอยกลับไป",
  str_monster_name_1600141 = "ชวาตส์",
  str_monster_desc_1600141 = "ผู้ว่าการและผู้ปกครองคนปัจจุบันของลูโมโพลิส ตำแหน่งและสถานะทำให้เขาอยู่เหนือผู้คนทั้งหลาย ความสำเร็จเช่นนี้มิใช่ได้มาเปล่า ๆ และเขาก็มีความเปล่าเปลี่ยวเป็นเพื่อนอยู่เสมอ ถึงอย่างนั้นชวาตส์ก็ยังใช้เวลานับไม่ถ้วนรักษาความสงบในลูโมโพลิส และพยายามทำหน้าที่ให้ดีที่สุดอยู่เสมอโดยไม่ยอมให้การ์ดตก",
  str_monster_ability_1600141 = "Schwartz สร้างความเสียหายแก่ศัตรูทั้งหมดในสนามรบพร้อมกับเรียก Lumo Guards เพื่อกำจัดศัตรูของเขา",
  str_monster_name_2001701 = "เวลเลอร์",
  str_monster_desc_2001701 = "อิคลิพไซท์ที่ออกมาในยามค่ำคืนเป็นหลัก ในช่วงกลางวันมันจะนอนหมดแรงอยู่กับพื้นและไม่สามารถขยับตัวได้",
  str_monster_ability_2001701 = "ช่วงกลางวันมันจะนอนหมดแรงอยู่กับพื้นและอยู่ในท่าป้องกันตัว เมื่อค่ำคืนมาเยือนมันจึงจะคืนสู่สถานะที่แท้จริง",
  str_monster_name_3902501 = "มินอส",
  str_monster_name_3902501_en = "มินอส",
  str_monster_alias_3902501 = "Codex ความอ้างว้าง",
  str_monster_desc_3902501 = "1. มอนสเตอร์ทมิฬจะเสริมพลังให้ตัวเองอย่างต่อเนื่องตามปริมาณดาเมจที่พวกมันได้รับ การเสริมพลังแต่ละสแต็กจะเพิ่ม ATK 10%\n2. มอนสเตอร์จะเพิ่ม ATK 8% และเพิ่ม DEF 5% ในแต่ละรอบ",
  str_monster_ability_3902501 = "แต่ละรอบจะเรียกช่องอ่อนแอในตำแหน่งแบบสุ่ม และเมื่อเดินผ่านช่องอ่อนแอจะทำดาเมจกับเป้าหมาย 1 ตัว สกิลชาร์จได้จะทำดาเมจทั้งจอ",
