  str_monster_desc_3903201 = "1. มอนสเตอร์ทมิฬจะเสริมพลังให้ตัวเองอย่างต่อเนื่องตามปริมาณดาเมจที่พวกมันได้รับ การเสริมพลังแต่ละสแต็กจะเพิ่ม ATK 10%\n2. มอนสเตอร์จะเพิ่ม ATK 8% และเพิ่ม DEF 5% ในแต่ละรอบ",
  str_monster_desc_3903301 = "1. มอนสเตอร์ทมิฬจะเสริมพลังให้ตัวเองอย่างต่อเนื่องตามปริมาณดาเมจที่พวกมันได้รับ การเสริมพลังแต่ละสแต็กจะเพิ่ม ATK 10%\n2. มอนสเตอร์จะเพิ่ม ATK 8% และเพิ่ม DEF 5% ในแต่ละรอบ",
  str_monster_ability_3903201 = "แต่ละรอบจะเรียกหนวดในตำแหน่งแบบสุ่มเพื่อขัดขวางการเดินของออโรเรียน โดย HP ของหนวดจะเพิ่มขึ้นทุกรอบ สกิลจะทำดาเมจพื้นที่ และสกิลชาร์จได้จะทำดาเมจทั้งจอ",
  str_monster_ability_3903301 = "แต่ละรอบจะเรียกคริสตัลสีเลือดในตำแหน่งแบบสุ่มเพื่อขัดขวางการเดินของออโรเรียน เมื่อเบริลผู้ร้ายกาจเดินผ่านคริสตัล เธอจะทุบคริสตัลและได้รับ ATK เพิ่ม สกิลจะทำดาเมจพื้นที่ และสกิลชาร์จได้จะทำดาเมจทั้งจอ",
  str_monster_name_3903401 = "ชวาตส์",
  str_monster_name_3903401_en = "ชวาตส์",
  str_monster_ability_2900913 = "โจมตีจุดที่ผู้เล่นยืนอยู่ในรอบที่แล้ว มอนสเตอร์ตนนี้จะคืนชีพที่ตำแหน่งเดิมหลังจากตายผ่านไประยะหนึ่ง",
  str_monster_name_2903001 = "ผู้พิทักษ์แกนพลัง",
  str_monster_name_2903001_en = "Core Guardian",
  str_monster_desc_2903001 = "ผู้พิทักษ์ขนาดยักษ์ที่คอยปกป้องแกนพลังงานของเรือ มันจะตื่นขึ้นมาต่อสู้เมื่อแกนพลังงานมีภัยคุกคาม",
  str_monster_ability_2903001 = "สิ่งมีชีวิตที่ทรงพลังตัวนี้มีความสามารถที่จะเปลี่ยนแปลงได้ทั้งกระดาน แต่มันก็มีจุดอ่อนด้วยเช่นกัน",
  str_monster_name_2001801 = "วงล้อครัชเชอร์",
  str_monster_desc_2001801 = "ระบบป้องกันอย่างหนึ่งของแกนพลังงานที่ทำลายได้ยาก มันจะโจมตีศัตรูอย่างไม่จบสิ้น",
  str_monster_ability_2001801 = "สิ่งมีชีวิตที่ไม่สามารถทำลายได้ เมื่อ HP ของมันลดลงเหลือศูนย์ มันจะเข้าสู่สถานะอัมพาต ซึ่งจะคงกระพันและฟื้นฟู HP อัตโนมัติในแต่ละรอบ เมื่อ HP ของมันเต็มแล้ว มันจะกลับมาเคลื่อนที่และโจมตีได้อีกครั้ง",
  str_monster_name_2001802 = "โมดูลแช่แข็ง",
  str_monster_desc_2001802 = "โมดูลทำความเย็นทำให้ผู้พิทักษ์แกนพลังที่ทรงพลังทำงานได้ตามปกติ\nมันอาจเป็นจุดอ่อนอย่างเดียวของผู้พิทักษ์ตัวนี้ก็ได้ แต่ถ้าคุณผลุนผลันเข้าไป ก็อาจจะถูกเผาด้วยความร้อนที่มันแผ่ออกมา",
  str_monster_ability_2001802 = "รบกวนพื้นที่และทำดาเมจใส่ออโรเรียนสำหรับทุกช่องที่เดินภายในพื้นที่ที่\nถูกรบกวน",
  str_monster_desc_2900311 = "อิคลิพไซท์ที่ทรงพลังอย่างเหลือเชื่อ ว่ากันว่ามันผ่านสงครามมานับไม่ถ้วน เป็นสิ่งมีชีวิตที่แข็งแกร่งที่รอดชีวิตจากกระสุนและระเบิด ไม่มีใครรู้ว่าศัตรูมากมายแค่ไหนพ่ายแพ้ภายใต้คมดาบของมัน",
  str_monster_passiveskill_name_2900144 = "ไม่ทันตั้งตัว: กลูมกูล",
  str_monster_passiveskill_desc_2900144 = "เรียกรูนแบบสุ่มตำแหน่ง ซึ่งจะกลายเป็นกลูมกูลใน 3 รอบ",
  str_monster_passiveskill_name_2900184 = "ไม่ทันตั้งตัว: แชโดว์ไกสต์",
  str_monster_passiveskill_desc_2900184 = "เรียกรูนแบบสุ่มตำแหน่ง ซึ่งจะกลายเป็นแชโดว์ไกสต์ภายใน 3 รอบ",
  str_monster_passiveskill_name_2000451 = "ทาสสังเวย",
  str_monster_passiveskill_desc_2000451 = "เมื่อตาย จะฟื้นฟู HP ให้ผู้เล่นจำนวนหนึ่ง",
  str_monster_passiveskill_name_2900611 = "เดธเลส: ร่างโคลน",
  str_monster_passiveskill_desc_2900611 = "เมื่อตาย จะแยกร่างเป็นตัวที่เล็กลง",
  str_monster_passiveskill_name_2900641 = "คาราคาลูน: ปนเปื้อน",
  str_monster_passiveskill_desc_2900641 = "ทำดาเมจเล็กน้อยกับผู้เล่นและล็อกช่องในวงรอบตัว 1 ชั้นของผู้เล่น",
  str_monster_passiveskill_name_2900661 = "แชตเทอร์บลาสต์: รอยแยกพสุธา",
  str_monster_passiveskill_desc_2900661 = "สร้างช่องที่เสียหาย 2 ช่องแบบสุ่มในสนามรบ",
  str_monster_passiveskill_name_2900671 = "ชูมเมอร์: ทำลายล้าง",
  str_monster_passiveskill_desc_2900671 = "เมื่อปิศาจของชูมเมอร์ทั้งหมดทำงาน ชูมเมอร์จะร่ายสกิลที่พิฆาตทุกสิ่งบนหน้าจอ",
  str_monster_passiveskill_name_2902200 = "โต้กลับยามราตรี",
  str_monster_passiveskill_desc_2902200 = "ทำดาเมจใส่เป้าหมายในวงรอบตัว 2 ชั้น และฟื้นฟู HP บางส่วนตามค่าฟกช้ำที่สะสมไว้",
  str_monster_passiveskill_name_2902301 = "คลอเดีย: แพลตฟอร์ม",
  str_monster_passiveskill_desc_2902301 = "คลอเดียจะไม่โดนดาเมจจากการโจมตีปกติเมื่อเธอยืนอยู่บนแพลตฟอร์มหรือแอชเชอร์",
  str_monster_passiveskill_name1_2902301 = "คลอเดีย: เทเลพอร์ต",
  str_monster_passiveskill_desc1_2902301 = "เมื่อแพลตฟอร์มที่คลอเดียเหยียบอยู่ถูกทำลาย หรือแอชเชอร์สลบไป คลอเดียจะเทเลพอร์ตไปยังแพลตฟอร์มอื่นในวงรอบตัว 2 ชั้นหรือลงมายืนบนพื้น",
  str_monster_passiveskill_name_9000101 = "บินสู่ฟ้า",
  str_monster_passiveskill_desc_9000101 = "ศัตรูตัวนี้สามารถข้ามห้วงอเวจีได้",
  str_monster_passiveskill_name_2000311 = "ฟันสองครั้ง",
  str_monster_passiveskill_desc_2000311 = "เดรดเบลดโจมตีเป้าหมายได้สองครั้ง",
  str_monster_passiveskill_name_2000221 = "สไปค์เพสต์",
  str_monster_passiveskill_desc_2000221 = "สร้างสไปค์เพสต์ขึ้นมาตามทางที่มันเดินผ่าน",
  str_monster_passiveskill_name_2000511 = "สับสน",
  str_monster_passiveskill_desc_2000511 = "เมื่อโจมตีโดนผู้เล่น จะเพิ่มรอบคูลดาวน์ของสกิลใช้งานของออโรเรียนรายนี้",
  str_monster_passiveskill_name_2000521 = "พันธนาการลูมินา",
  str_monster_passiveskill_desc_2000521 = "ล็อคไทล์ใน 1 คลัสเตอร์โดยรอบหลังจากย้าย สูญเสียเอฟเฟกต์เมื่อมึนงง หวาดกลัว เป็นอัมพาต หรือได้รับผลกระทบจากการควบคุมอื่น ๆ",
  str_monster_passiveskill_name_2000551 = "ความเกลียดชัง",
  str_monster_passiveskill_desc_2000551 = "เมื่อโจมตีจะติดคำสาปให้กับออโรเรียนธาตุเดียวกัน ออโรเรียนต้องสาปจะไม่สามารถโจมตีหรือใช้สกิลใช้งานได้",
  str_monster_passiveskill_name1_2000551 = "สลายความแค้น",
  str_monster_passiveskill_desc1_2000551 = "เมื่อถูกฆ่า จะลบคำสาปที่ Cursed Fay วางไว้บน Aurorians ที่มีธาตุเดียวกัน",
  str_monster_passiveskill_name_2001701 = "พาเหรดเวลเลอร์",
  str_monster_passiveskill_desc_2001701 = "มันจะนอนหมดแรงอยู่กับพื้นในท่าป้องกันตัวในช่วงกลางวัน เมื่อค่ำคืนมาเยือนมันจึงจะคืนสู่สถานะที่แท้จริงและออกโจมตีออโรเรียน",
  str_monster_passiveskill_name_2901001 = "ชายในกรอบรูป",
  str_monster_passiveskill_desc_2901001 = "ซ่อนตัวเมื่ออยู่บนช่องที่เสียหาย ได้รับเฉพาะดาเมจพื้นที่ รวมทั้งต้านดาเมจโจมตีปกติและดาเมจสกิลที่มีการเลือกช่อง",
  str_monster_passiveskill_name_2901301 = "แพ้แสงออโรรา",
  str_monster_passiveskill_desc_2901301 = "ดาเมจที่ได้รับในช่วงออโรราไทม์จะเพิ่มขึ้นอย่างมาก",
  str_monster_passiveskill_name_2001301 = "จุดสำคัญออโรรา",
  str_monster_passiveskill_desc_2001301 = "ออโรเรียนจะโจมตีได้ในช่วงออโรราไทม์เท่านั้น",
  str_monster_passiveskill_name_2903001 = "ผู้พิทักษ์แกนพลังสมบูรณ์",
  str_monster_passiveskill_desc_2903001 = "เมื่อผู้พิทักษ์แกนพลังกำลังระวังภัย จะได้รับเฉพาะดาเมจเป้าหมายเดียวจากการโจมตีที่ไม่มีการเลือกช่อง และต้านดาเมจโจมตีปกติและดาเมจพื้นที่",
  str_monster_passiveskill_name1_2903001 = "ผู้พิทักษ์แกนพลังอัมพาต",
  str_monster_passiveskill_desc1_2903001 = "เผยจุดอ่อนเพิ่มเติมหลังจากผู้พิทักษ์แกนพลังเป็นอัมพาต และสูญเสียการต้านทานดาเมจ",
  str_monster_passiveskill_name_2000901 = "นับเวลาทำลายตัวเอง",
  str_monster_passiveskill_desc_2000901 = "ทำลายตัวเองหลังจากนับถอยหลังจนถึงศูนย์ ทำลายช่องที่อยู่ใต้ตัวมัน",
  str_monster_passiveskill_name_2001801 = "วงล้อครัชเชอร์อัมพาต",
  str_monster_passiveskill_desc_2001801 = "เมื่อ HP ของวงล้อครัชเชอร์ลดลงเหลือศูนย์ มันจะเข้าสู่สถานะอัมพาต เมื่อ HP ของมันเต็มอีกครั้ง มันจะกลับมาเคลื่อนที่และโจมตีได้",
  str_monster_passiveskill_name_2001802 = "โมดูลแช่แข็งล้มเหลว",
  str_monster_passiveskill_desc_2001802 = "จุดอ่อนของผู้พิทักษ์แกนพลัง เมื่อ HP ของโมดูลแช่แข็งลดเหลือศูนย์ ผู้พิทักษ์แกนพลังจะเข้าสู่สถานะอัมพาต",
  str_monster_passiveskill_name_2900301 = "โล่โบว์ลิงเกอร์",
  str_monster_passiveskill_desc_2900301 = "โล่พลังงานปกป้องโบว์ลิงเกอร์ไม่ให้ได้รับดาเมจ (ใช้เดธไรเดอร์โจมตีตรงพื้นที่ที่ไม่มีโล่ เพื่อให้เป็นอัมพาตและทำดาเมจให้กับโบว์ลิงเกอร์ได้ดี)",
  str_monster_passiveskill_name_2910281 = "โล่แหล่งจ่ายพลังงาน",
  str_monster_passiveskill_desc_2910281 = "ประภาคารดาร์กซัมมอนเนอร์แต่ละจุดในสนามรบจะลดดาเมจที่ดาร์กซัมมอนเนอร์ได้รับ",
  str_monster_passiveskill_name_2010481 = "ลูมิวอลล์",
  str_monster_passiveskill_desc_2010481 = "ออโรเรียนจะทำดาเมจกับลูมิวอลล์ได้ก็ต่อเมื่อโฟโรชั่นเข้าไปซ่อนตัวอยู่ในลูมิวอลล์นี้ ส่วนลูมิวอลล์ด้านอื่น ๆ จะทำการโจมตีไม่ได้",
  str_monster_passiveskill_name_2901201 = "แสงลวง",
  str_monster_passiveskill_desc_2901201 = "เคลย์มอร์มีความสามารถที่จะเชื่อมต่อและเคลื่อนที่ไปตามช่องสีเดียวกันได้",
  str_monster_passiveskill_name1_2901201 = "สุสานอมตะ",
  str_monster_passiveskill_desc1_2901201 = "หลังจากที่เสียงเรียกจากหลุมศพสลายไป เคลย์มอร์จะได้รับสกิลสวนกลับที่ทำดาเมจให้กับออโรเรียนตาม ATK ของออโรเรียนที่ร่ายสกิลและฟื้นฟู HP ของตัวเอง",
  str_monster_passiveskill_name_2900312 = "ฟันสองครั้ง",
  str_monster_passiveskill_desc_2900312 = "ออเจียนโจมตีเป้าหมายสองครั้ง",
  str_monster_passiveskill_name1_2900312 = "ขุดหลุม",
  str_monster_passiveskill_desc1_2900312 = "เพิ่มระยะทางการเดิน 2 ช่องและฟื้นฟูในรอบต่อไป",
  str_monster_passiveskill_name_3900451 = "พลังจอมทมิฬ",
  str_monster_passiveskill_desc_3900451 = "เมื่อมอนสเตอร์ทมิฬได้รับดาเมจ เอฟเฟกต์ชนะทางธาตุจะเพิ่มขึ้น 100%\nมอนสเตอร์ทมิฬจะเสริมพลังให้ตัวเองอย่างต่อเนื่องตามปริมาณดาเมจที่พวกมันได้รับ การเสริมพลังแต่ละสแต็กจะเพิ่ม ATK 10%\nมอนสเตอร์ทมิฬจะเพิ่ม ATK 8% และเพิ่ม DEF 5% ในแต่ละรอบ",
  str_monster_passiveskill_name_3910281 = "แม่เหล็กพลังงาน",
  str_monster_passiveskill_desc_3910281 = "ประภาคารดาร์กซัมมอนเนอร์แต่ละจุดในสนามรบจะเพิ่ม ATK ของดาร์กซัมมอนเนอร์",
  str_monster_passiveskill_name_3903101 = "โล่ทมิฬ",
  str_monster_passiveskill_desc_3903101 = "ต้านทานดาเมจในช่วงที่ลงมือ",
  str_monster_passiveskill_name_3903301 = "จอมทมิฬ: อัญเชิญคริสตัล",
  str_monster_passiveskill_desc_3903301 = "สร้างคริสตัลสีเลือดแบบสุ่มตำแหน่งในสนามรบทุกรอบ (จำกัดจำนวนสูงสุด)",
  str_monster_passiveskill_name_3903201 = "จอมทมิฬ: กำเนิดจากความกลัว",
  str_monster_passiveskill_desc_3903201 = "สร้างหนวดหมึกแบบสุ่มตำแหน่งในสนามรบทุกรอบ (จำกัดจำนวนสูงสุด)",
  str_monster_passiveskill_name_3902501 = "จอมทมิฬ: กำหนดจุดอ่อน",
  str_monster_passiveskill_desc_3902501 = "สร้างช่องอ่อนแอแบบสุ่มตำแหน่งในสนามรบทุกรอบ",
  str_monster_passiveskill_name_2901341 = "หัวใจแตกสลาย",
  str_monster_passiveskill_desc_2901341 = "ลด DEF ของ Fearmonger ทุกครั้งที่มินเนี่ยน Fearmonger ตาย",
  str_monster_passiveskill_name_29009211 = "เกราะพินาศ",
  str_monster_passiveskill_desc_29009211 = "ไฮลินเจอร์มี DEF เริ่มต้นสูงมาก แต่จะต่ำลงเมื่อสุขภาพจิตของออโรเรียนลดลง ต่ำสุดถึง 40%",
  str_monster_passiveskill_name_2912101 = "กลืนกินผี",
