  str_monster_name_2903901 = "คาสต้า",
  str_monster_name_2903901_en = "Casta",
  str_monster_desc_2903901 = "ดูห่างเหิน แต่จริงๆ แล้วมีความรับผิดชอบสูง ร่วมมือกับพอลลักซ์เพื่อสร้างทหารรับจ้างคู่ขนานนามว่า \"เลือดของเรเวน\" เพื่อปกป้องเด็กๆ ที่อาศัยอยู่ในโบสถ์ได้ดียิ่งขึ้น",
  str_monster_ability_2903901 = "โจมตีศัตรูในระยะประชิดด้วยดาบปลายปืนหรือโจมตีพวกเขาจากระยะไกลด้วยกระสุน โจมตีศัตรูด้วยทักษะต่างๆ ตามตำแหน่งของพวกเขา",
  str_monster_passiveskill_name_29039011 = "รูเล็ตรัสเซีย: เคาน์เตอร์",
  str_monster_passiveskill_desc_29039011 = "เมื่อใดก็ตามที่ Aurorian ใช้ Active Skill Casta จะย้าย 2 แผ่นไปทาง Aurorian เมื่อมีออโรเรียนอยู่ภายใน 1 กลุ่มของ Casta รอบๆ เธอจะใช้ทักษะเพื่อโจมตี Aurorian",
  str_monster_passiveskill_desc_29039012 = "เมื่อใดก็ตามที่ Aurorian ใช้ Active Skill Casta จะย้าย 3 แผ่นไปทาง Aurorian เมื่อมีออโรเรียนอยู่ภายใน 1 กลุ่มของ Casta รอบๆ เธอจะใช้ทักษะเพื่อโจมตี Aurorian",
  str_monster_passiveskill_desc_29039013 = "เมื่อใดก็ตามที่ Aurorian ใช้ Active Skill Casta จะย้าย 3 แผ่นไปทาง Aurorian และใช้เกราะนับ 2 ชั้นให้กับตัวเอง เมื่อมี Aurorian อยู่ภายใน 1 กลุ่มของ Casta รอบๆ เธอจะใช้สกิลเพื่อโจมตี Aurorian",
  str_monster_name_2903701 = "ปืนใหญ่อัตตาจร",
  str_monster_name_2903701_en = "Self-Propelled Cannon",
  str_monster_desc_2903701 = "ยามที่ทรงพลังสามารถลาดตระเวนได้ด้วยตัวเอง ทั้งปืนใหญ่หลักและไหล่ปืนนั้นทรงพลังอย่างเหลือเชื่อ ยามเพียงคนเดียวสามารถสร้างความเสียหายได้มาก",
  str_monster_ability_2903701 = "สามารถใช้ป้อมปราการเพื่อสร้างความเสียหายอย่างต่อเนื่องแก่ศัตรูและขับไล่ศัตรูที่เข้ามาใกล้เกินไป ยามจะเสริมกำลังตัวเองเมื่อรับรู้ถึงภัยคุกคามครั้งใหญ่",
  str_monster_ability_4000445 = "โจมตีเป้าหมายด้วยการโจมตีระยะประชิด และแปลงชิ้นส่วนทั้งหมดตามเส้นทางการเคลื่อนที่เป็นชิ้นส่วนขององค์ประกอบของตัวเอง ทำให้เกิดจุดแหลมตลอดทาง",
  str_monster_passiveskill_name_4000445 = "เมอร์คไมท์ เฟลม",
  str_monster_passiveskill_desc_4000445 = "สร้าง spikepests ตามเส้นทางการเคลื่อนไหวและแปลงกระเบื้องที่ผ่านเป็นสีแดง",
  str_monster_name_21500781 = "โรบิน",
  str_monster_name_21500781_en = "Robyn",
  str_monster_desc_21500781 = "สมาชิกสเปียร์โรว์ในอัมบราตัน เป็นคนขี้อายที่ชอบเก็บตัว เธอมักจะเกาะติดเดย์นาผู้เป็นพี่สาว ขณะพยายามเอาชีวิตรอดในอัมบราตัน",
  str_monster_ability_21500781 = "Dayna จะมีพลังมากขึ้นเมื่อพ่ายแพ้",
  str_monster_name_21400481 = "เดย์นา",
  str_monster_name_21400481_en = "Dayna",
  str_monster_desc_21400481 = "เป็นหัวหน้ากลุ่มสเปียร์โรว์แม้อายุยังน้อย เธอมีชื่อเสียงเรื่องการตั้งฐานที่มั่นอันมั่นคงตามตรอกซอยที่มืดมิดและสกปรกในอัมบราตันด้วยความมุ่งมั่นอันไร้ที่ติ และอาวุธลับอันแสนร้ายกาจ",
  str_monster_ability_21400481 = "เชี่ยวชาญการโจมตีระยะไกล ทำดาเมจในพื้นที่แถวแนวตั้ง",
  str_monster_name_21400911 = "โคลอี้",
  str_monster_name_21400911_en = "Chloe",
  str_monster_desc_21400911 = "นักดนตรีผู้อ่อนโยนและเป็นมิตรของลูโมโพลิสที่จมอยู่กับความทรงจำเศร้าสร้อยอย่างง่ายดาย เธอเสียครอบครัวไปเพราะสงครามเลยอาศัยอยู่ด้วยความทุกข์และทำใจปล่อยวางยาก",
  str_monster_ability_21400911 = "เพิ่ม ATK ของพันธมิตรตามจำนวนกระเบื้องสีน้ำเงินบนสนาม",
  str_monster_ability_21400912 = "เพิ่ม ATK ของพันธมิตรตามจำนวนกระเบื้องสีน้ำเงินบนสนาม ยังเพิ่ม ACT",
  str_monster_name_21200501 = "คอร์กอน",
  str_monster_name_21200501_en = "Korgon",
  str_monster_desc_21200501 = "ถึงจะยิ้มแต่ก็ยังเป็นฉลามที่น่ากลัว! เขาเป็นผู้ปกป้องนิคมขนาดเล็ก และแม้ว่าภายนอกจะดูดุร้ายน่ากลัว แต่ที่จริงเป็นคนรักแมวที่อ่อนโยนมาก",
  str_monster_ability_21200501 = "ทำการโจมตีอันทรงพลังที่สามารถทำให้กระเด็นถอยหลังเมื่อโจมตีโดนเป้าหมาย",
  str_monster_name_21300491 = "เซลูซิด",
  str_monster_name_21300491_en = "Seleucid",
  str_monster_desc_21300491 = "นักรบผู้แข็งแกร่งและตัวสูงที่มักจะเดินทั่วอัมบราตันในชุดเกราะเต็มยศและดาบขนาดใหญ่ เขาเป็นคนพูดน้อยและไม่เคยถอดหมวกเกราะออกเลย โดยจะชอบใช้กำลังรุนแรงพูดแทนมากกว่า",
  str_monster_ability_21300491 = "รีเซ็ตไทล์ที่ไม่ใช่สีน้ำเงินภายใน 1 คลัสเตอร์รอบๆ ขณะสร้างความเสียหาย",
  str_monster_ability_4900251 = "ทำการโจมตีพื้นที่รูปกากบาทและเรียกร่างโคลนมาต่อสู้เคียงข้างกัน เมื่อโคลนตัวเอง มันจะดูดซับ HP ของร่างโคลนตัวเดิมเพื่อฟื้นฟู HP และเพิ่ม ATK เมื่อมีร่างโคลน ร่างจริงของ Phantom ก็สามารถหลบการโจมตีได้ แต่จะได้รับความเสียหายเมื่อร่างโคลนได้รับบาดเจ็บ",
  str_monster_ability_4910252 = "เมื่อมาถึง มันจะกลายเป็นบ้าและเรียกร่างโคลนออกมาต่อสู้เคียงข้างกัน หาก Phantom ดูดซับร่างโคลน มันจะฟื้น HP และเพิ่ม ATK อย่างมาก",
  str_monster_passiveskill_name_290370113 = "ปฏิกิริยาของกลไก",
  str_monster_passiveskill_desc_290370113 = "ย้าย 1 แผ่นและเรียก 1 T256 ข้างหน้า",
  str_monster_name_4910181 = "เรจินา",
  str_monster_name_4910181_en = "Regina",
  str_monster_desc_4910181 = "ธรรมชาติที่กล้าหาญและโผงผาง รวมทั้งความหุนหันพลันแล่นของเธอเป็นเครื่องหมายของจิตวิญญาณชาวร็อกแอนด์โรลตัวจริง! สไตล์ดนตรีที่ดุดันทำให้เธอโด่งดังอย่างมากในเรดีเซล เวรนช์ ไม่เพียงแต่สร้างแรงบันดาลใจให้กับกองทหารเท่านั้น แต่ยังเป็นผู้นำในการจู่โจมอีกด้วย",
  str_monster_ability_4910181 = "ไล่ล่าศัตรูและโจมตีด้วยการกระทำที่น่ากลัว",
  str_monster_name_4903101 = "บาร์บาร่า",
  str_monster_name_4903101_en = "Barbara",
  str_monster_desc_4903101 = "นักร้องไอดอลของเรดีเซล เวรนช์ ดูภายนอกแล้วบาร์บาร่าอ่อนโยนและนิสัยดีแต่จะเผยด้านฉุนเฉียวออกมาเมื่อพบแฟนคลับที่ข้ามเส้นกันเกินไป เธอเดินทางไปทุกที่เพื่อก้าวสู่ความเป็นไอดอลที่โด่งดังที่สุด",
  str_monster_ability_4903101 = "ขว้าง \"ระเบิด\" ไปที่สนามเพื่อขัดขวางศัตรู",
  str_monster_ability_49031011 = "เรียกไอเทมมาที่สนามเพื่อขัดขวางศัตรู",
  str_monster_name_4910301 = "ซินซา",
  str_monster_name_4910301_en = "Sinsa",
  str_monster_desc_4910301 = "ผู้นำที่พูดจาโผงผางของเรดีเซล เวรนช์ ผู้ซึ่งสนิทสนมกับสมาชิกของเขาอย่างมากและหวงน้องสาวมากอีกด้วย เขาคือผู้ที่อุทิศตนเพื่อให้แน่ใจว่าทั้งแก๊งจะมีชีวิตรอด",
  str_monster_ability_4910301 = "ผู้โจมตีที่ทรงพลังซึ่งความแข็งแกร่งจะเปลี่ยนไปหลังจากความพ่ายแพ้ของอีฟ",
  str_monster_name_4911051 = "อีฟ",
  str_monster_name_4911051_en = "Eve",
  str_monster_desc_4911051 = "น้องสาวของซินซาที่ตกอยู่ใต้อำนาจอิคลิพไซท์และไม่สามารถควบคุมตัวเองได้ตั้งแต่เล็ก เธอกลับมามีความไร้เดียงสาหลังจากได้รับการรักษาแล้ว",
  str_monster_ability_4911051 = "มีความสามารถในการโจมตีที่แม่นยำและความเสียหายเป็นบริเวณกว้าง",
  str_monster_ability_4900141 = "เก่งในการโจมตีระยะประชิดและมีความสามารถในการเรียก Eclipsites อื่น ๆ หลังจากที่มันเปลี่ยน Rabid การโจมตีปกติของมันจะสร้างความเสียหายสองครั้งด้วยระยะสกิลที่เพิ่มขึ้นอย่างมาก",
  str_monster_ability_4900181 = "เก่งในการโจมตีระยะไกลที่จะทำให้เป้าหมายมึนงงและเรียก Eclipsites หลังจากที่มันเปลี่ยน Rabid การโจมตีปกติของมันจะสร้างความเสียหายสองครั้งด้วยระยะสกิลที่เพิ่มขึ้นอย่างมาก",
  str_monster_passiveskill_name_21500781 = "พี่น้องบอนด์",
  str_monster_passiveskill_desc_21500781 = "Robyn แข็งแกร่งขึ้นเมื่อ Dayna พ่ายแพ้",
  str_monster_ability_4900641 = "เก่งในการใช้การโจมตีพื้นที่ขนาดใหญ่ ล็อคองค์ประกอบของกระเบื้องรอบๆ หลังจากที่มันเคลื่อนที่",
  str_monster_ability_4900661 = "Shatterblast จะบดขยี้กระเบื้องเมื่อเริ่มการต่อสู้ การโจมตีนี้สามารถทำให้เป้าหมายกระเด็นถอยหลังได้",
  str_monster_name_2903801 = "แอสเตอร์",
  str_monster_name_2903801_en = "Astor",
  str_monster_desc_2903801 = "วิญญาณหญิงที่เร่ร่อนโดยไม่มีเจ้านายหรือเจตจำนงของตนเอง นอกเหนือจากรูปลักษณ์ของผู้หญิงแล้ว สิ่งที่เหลืออยู่ก็คือความเป็นปฏิปักษ์ต่อสิ่งมีชีวิต ด้วยพิธีกรรมอันชั่วร้าย วิญญาณนี้สามารถรวมเข้ากับ Darkflow เพื่อสร้างตัวตนเหนือธรรมชาติที่ทรงพลัง",
  str_monster_ability_2903801 = "อาละวาดผ่านพื้นที่ที่กำหนดและดูดซับพลังงานของ Deathly Candles เพื่อเสริมความแข็งแกร่งให้กับตัวเอง",
  str_monster_ability_39038011 = "ออกอาละวาดผ่านพื้นที่ที่กำหนด ปลุกพลังของ Deathly Candles เพื่อสร้างความเสียหาย",
  str_monster_passiveskill_name_2903801 = "แสงเทียนปรารถนา",
  str_monster_passiveskill_desc_2903801 = "เมื่อไม่มี Aurorians อยู่ในระยะโจมตี Astor จะเริ่มจุดเทียน Deathly Candles ในบริเวณใกล้เคียง (หาก Deathly Candles ทั้งหมดติดสว่าง Astor จะฟื้นฟู 20% ของ HP สูงสุดของเธอ)\nนอกจากนี้ Deathly Candle ที่จุดไฟแต่ละอันยังช่วยลดความเสียหายของ Astor 10%",
  str_monster_passiveskill_name_39038011 = "แสงเทียนปรารถนา",
  str_monster_passiveskill_desc_39038011 = "เมื่อไม่มี Aurorians อยู่ในระยะโจมตี Astor เริ่มจุด Deathly Candles ในสนามรบ\nหากจุด Deathly Candles ทั้งหมด Astor จะสร้างความเสียหายอย่างหนักแก่ Aurorians",
  str_monster_passiveskill_name_39038012 = "แสงเทียนปรารถนา",
  str_monster_passiveskill_desc_39038012 = "เมื่อไม่มี Aurorians อยู่ในระยะโจมตี Astor เริ่มจุด Deathly Candles ในสนามรบ\nหากจุด Deathly Candles ทั้งหมด Astor จะสร้างความเสียหายอย่างหนักแก่ Aurorians\nหากไม่ได้จุด Deathly Candles ทั้งหมด Astor จะสร้างความเสียหายเล็กน้อยแก่ Aurorians",
  str_monster_passiveskill_name_2903802 = "แสงเทียนปรารถนา",
  str_monster_passiveskill_desc_2903802 = "เมื่อไม่มี Aurorians อยู่ในระยะโจมตี Astor จะเริ่มจุดเทียน Deathly Candles ในบริเวณใกล้เคียง (หาก Deathly Candles ทั้งหมดติดสว่าง Astor จะฟื้นฟู 20% ของ HP สูงสุดของเธอ)\nนอกจากนี้ Deathly Candle แต่ละอันที่ติดไฟจะเพิ่มการลดความเสียหายของ Astor และ Deathly Candle ที่ดับลงแต่ละครั้งจะเพิ่ม ATK ของ Astor",
  str_monster_name_2903600 = "ดอกไดอาโวลา",
  str_monster_name_2903601 = "เดียโวล่า",
  str_monster_name_2903601_en = "Diavola",
  str_monster_desc_2903601 = "Diavola ชอบที่จะซ่อนตัวและกำจัดศัตรูอย่างลับ ๆ ล่อ ๆ ด้วยพิษ",
  str_monster_ability_2903601 = "เดียโวล่าขยับไม่ได้ มันมีความต้านทานที่แข็งแกร่ง ร่างกายของมันถูกห่อหุ้มด้วยหนามพิษ ดอกไม้ของมันสามารถดึงดูดดอว์นสไปรต์ได้ แต่ก็เผยให้เห็นจุดอ่อนของมันเช่นกัน",
  str_monster_desc_2000609 = "ภาพลวงตาที่สร้างขึ้นโดย Diavola ที่มีพลังวิเศษ",
  str_monster_ability_2000609 = "ยึดติดกับ Diavola และเพิ่ม ATK เมื่ออยู่ภายใน 1 กลุ่มของ Diavola",
  str_monster_passiveskill_name_2903600 = "การหลีกเลี่ยงความเสียหาย",
  str_monster_passiveskill_desc_2903600 = "ดอกไม้ของ Diavola สามารถได้รับความเสียหายจากทักษะ Sniper เท่านั้น และจะต้านทานต่อการโจมตีปกติและความเสียหายในพื้นที่ เมื่อดอกไม้ของมันมี HP เหลือเป็นศูนย์ Diavola จะเป็นอัมพาตและจะไม่สร้าง Toxin ให้กับ Aurorians อีกต่อไป",
  str_monster_passiveskill_name_2903601 = "การกัดกร่อน",
  str_monster_passiveskill_desc_2903601 = "เมื่อตื่นขึ้น Diavola จะโต้กลับทุกการโจมตีปกติ สร้าง Toxin 1 กองต่อ Aurorian",
  str_monster_passiveskill_name_2000609 = "รักษา",
  str_monster_passiveskill_desc_2000609 = "เมื่อ Dawn Sprite พ่ายแพ้ มันจะฟื้นฟู HP ของทีมเล็กน้อย และลดจำนวน Toxin Stack ของทีม",
  str_monster_passiveskill_desc_2000639 = "ฟื้นฟู HP จำนวนหนึ่งให้กับ Dawn Sprite หลังจากที่ Aurorians พ่ายแพ้",
  str_monster_name_2001901 = "โคมไฟวิญญาณ",
  str_monster_name_2001901_en = "Lantern Spirit",
  str_monster_desc_2001901 = "Eclipsite ที่ดัดแปลงโดย Asmodeus ความต้องการของมันถูกควบคุมโดย Asmodeus ดังนั้นมันจึงเชื่อฟังทุกคำสั่งของเธอ",
  str_monster_ability_2001901 = "การโจมตีสร้างสายโซ่ที่ทำให้ทั้งความเสียหายที่ได้รับและ HP ที่ฟื้นคืนมาระหว่างฝ่ายที่เชื่อมโยงถูกแชร์",
  str_monster_passiveskill_name_2001901 = "โซ่",
  str_monster_passiveskill_desc_2001901 = "เมื่อฝ่ายใดฝ่ายหนึ่งเชื่อมต่อกันด้วยสายโซ่ได้รับความเสียหายหรือฟื้นฟู HP อีกฝ่ายจะได้รับความเสียหายเท่ากันหรือฟื้นฟู HP เท่ากัน เมื่อโซ่เชื่อมต่อกับ Aurorian มันจะขาดหลังจากมีความยาวเกินกำหนด",
  str_monster_passiveskill_name_2001902 = "เทเลพอร์ต",
  str_monster_passiveskill_desc_2001902 = "Lantern Spirit สามารถเทเลพอร์ตได้หากสามารถผ่านกระเบื้องที่ Aurorian เปิดอยู่และย้ายไปที่กระเบื้องอีกด้านหนึ่ง",
  str_monster_name_2903401 = "แอสโมเดอุส",
  str_monster_name_2903401_en = "Asmodeus",
  str_monster_desc_2903401 = "เจตภูตผู้ทรงพลังมีความสามารถที่น่าสะพรึงกลัวในการมองทะลุความปรารถนาทั้งหมดของฝ่ายตรงข้ามและสนุกกับการบงการพวกมัน",
  str_monster_ability_2903401 = "เมื่อ Asmodeus มีภูมิคุ้มกันต่อความเสียหายจากการโจมตีปกติและ Asmodeus ที่มีภูมิคุ้มกันต่อความเสียหายจากทักษะทั้งคู่อยู่ในสนาม HP ของพวกมันจะถูกแบ่งปันผ่าน Chain of Desire และเธอยังสามารถทรมานเหยื่อของเธอด้วย Chain of Nightmares",
  str_monster_passiveskill_name_29034001 = "Asmodeus: ห่วงโซ่แห่งความปรารถนา",
  str_monster_passiveskill_desc_29034001 = "เมื่อ Asmodeus คนใดคนหนึ่งที่เชื่อมต่อด้วย Chain of Desire ได้รับความเสียหายหรือฟื้นฟู HP Asmodeus อีกคนหนึ่งจะได้รับความเสียหายในปริมาณที่เท่ากันหรือฟื้นฟู HP ในปริมาณที่เท่ากัน หลังจาก Asmodeus ดำเนินการ Dark Regions จะถูกสร้างขึ้นภายใต้ Chain of Desire",
  str_monster_passiveskill_name_29034002 = "Asmodeus: สลับออก",
  str_monster_passiveskill_desc_29034002 = "ก่อนที่ Asmodeus จะดำเนินการ ร่างทั้งสองของเธออาจสลับตำแหน่งเพื่อให้เธอตามล่าเป้าหมายได้ง่ายขึ้น",
  str_monster_passiveskill_name_2903401 = "Asmodeus: ห่วงโซ่แห่งฝันร้าย",
  str_monster_passiveskill_desc_2903401 = "Aurorians ที่เชื่อมต่อกันด้วย Chain of Nightmares จะได้รับความเสียหายทุกช่องที่พวกเขาสำรวจ การออกจากระยะของ Chain of Nightmares จะทำให้มันพัง",
  str_monster_passiveskill_name_2903411 = "Asmodeus: การแยกวิญญาณ",
  str_monster_passiveskill_desc_2903411 = "เมื่อการเชื่อมโยงระหว่าง Aurorians และ Chain of Nightmares ถูกตัดขาด Aurorians จะได้รับความเสียหายสูง",
  str_monster_name_2903501 = "เซอร์ริทัส",
  str_monster_name_2903501_en = "Cerritus",
  str_monster_desc_2903501 = "Eclipsite ใหม่ที่พบในระหว่างการสำรวจดูเหมือนจะแตกต่างจาก Eclipsite ที่ทรงพลัง เว้นแต่จะบ้าคลั่งกว่าและทำลายล้างได้มากกว่า",
  str_monster_ability_2903501 = "Cerritus โจมตี Aurorians โดยการพุ่งชนพวกเขา และมีความสามารถอันทรงพลังในการเรียก Pebbles และเปลี่ยนภูมิประเทศ Cerritus แข็งแกร่งขึ้นเมื่อการต่อสู้ดำเนินไป การโจมตีที่ไม่ฆ่า Cerritus มีแต่จะทำให้แข็งแกร่งขึ้น! ทุกสองสามรอบ Cerritus คำรามด้วยความโกรธและเข้าสู่สภาวะบ้าคลั่ง",
  str_monster_passiveskill_name_29034011 = "Cerritus: โกรธหอน",
  str_monster_passiveskill_desc_29034011 = "ทุกๆ 2 รอบ Cerritus จะหอนด้วยความโกรธและฮีล ได้รับ ATK และการเคลื่อนไหว แต่สูญเสีย DEF ในขณะเดียวกัน มันก็เรียกก้อนกรวดออกมาทั่วสนาม",
  str_monster_passiveskill_name_29034012 = "Cerritus: หอนโกรธ",
  str_monster_passiveskill_desc_29034012 = "ทุก ๆ 2 รอบ Cerritus จะหอนด้วยความโกรธและฮีล ได้รับ ATK และการเคลื่อนไหว แต่สูญเสีย DEF ในขณะเดียวกัน มันก็เรียกก้อนกรวดออกมาทั่วสนาม",
  str_monster_passiveskill_name_2903501 = "Cerritus: หอนโกรธ",
  str_monster_passiveskill_desc_2903501 = "ทุกๆ 2 รอบ Cerritus จะหอนด้วยความโกรธและฮีล ได้รับ ATK และการเคลื่อนไหว แต่สูญเสีย DEF ในขณะเดียวกัน มันก็เรียกก้อนกรวดออกมาทั่วสนาม",
  str_monster_passiveskill_desc_2903504 = "ทุกๆ 2 รอบ Cerritus จะหอนด้วยความโกรธและฮีล เพิ่ม ATK และการเคลื่อนไหว ในขณะเดียวกัน มันก็เรียกก้อนกรวดออกมาทั่วสนาม",
  str_monster_ability_9200164 = "ใช้หอกโจมตีเป้าหมายและสามารถเสริม Eclipsites อื่น ๆ ได้",
  str_monster_name_21600381 = "แฟนท่อม",
  str_monster_name_2902902 = "จอร์มังกานด์",
  str_monster_name_2902902_en = "Jormungand",
  str_monster_desc_2902902 = "สุริยุปราคาที่เกิดในสภาวะสุดขั้วของวันสิ้นโลก มันมีรูปร่างบิดเบี้ยวและสูญเสียความสามารถในการคิดอย่างชาญฉลาดไปนานแล้ว สิ่งที่เหลืออยู่คือความปรารถนาที่จะก้าวไปข้างหน้าและกลืนกินทุกสิ่งที่ขวางหน้า",
  str_monster_ability_2902902 = "โครงสร้างร่างกายของ Jormungand ช่วยให้สามารถจำลองตัวเองได้ตลอดเวลา มันกลืนกินสิ่งกีดขวางที่ขวางหน้า แม้กระทั่งร่างกายของมันเอง",
  str_monster_passiveskill_name_2902902 = "Jormungand: ไม่รู้จักพอ",
  str_monster_passiveskill_desc_2902902 = "Jormungand โจมตีอีกครั้งเมื่อใดก็ตามที่ Aurorian ใช้ Active Skill",
  str_monster_passiveskill_name_2902901 = "Jormungand: การจำลองแบบ",
  str_monster_passiveskill_desc_2902901 = "ในช่วงเริ่มต้นของรอบสัตว์ประหลาด Jormungand จำลองตัวเอง โดยมีความยาวเพิ่มขึ้น 1 กลุ่มใหม่",
  str_monster_passiveskill_name_2900251 = "หลบหลีก",
  str_monster_passiveskill_desc_2900251 = "เคลื่อนไหวด้วยความว่องไวและมีโอกาสหลบการโจมตี (ไม่สามารถหลบได้เมื่อเป็นอัมพาต)",
  str_monster_name_2002001 = "เวนเม็กซ์",
  str_monster_desc_2002001 = "กล่าวกันว่าเป็นญาติห่างๆ ของสายพันธุ์ Eclipsite ที่สามารถระเบิดตัวเองได้ ยกเว้นสายพันธุ์นี้สามารถปล่อยลูกบอลเมือกพิษ สร้างความเสียหายอย่างมากต่อสิ่งมีชีวิต",
  str_monster_ability_2002001 = "พ่นพิษเป็นเส้นตรงหรือตำแหน่งของ Aurorian ทำให้ศัตรูและพรรคพวกติดพิษได้ในระยะของพิษ",
  str_monster_ability_2904201 = "มีความสามารถในการโจมตี Aurorians จากระยะไกลและสามารถเปิดการโจมตีแบบเต็มหน้าจอได้ สามารถอัญเชิญภูตผีที่ไม่สามารถโจมตีแต่ล้อมรอบ Aurorian ได้",
  str_monster_passiveskill_name_2904201 = "กลลวง",
  str_monster_passiveskill_desc_2904201 = "เมื่อการเป็นอมตะสิ้นสุดลง ภูตผี Dreamwalker 2 ตัวจะถูกเรียกมาล้อมรอบ Aurorians ภูตผีไม่สามารถโจมตีและไม่สามารถถูกโจมตีได้",
  str_monster_passiveskill_desc_2904203 = "เมื่อการอยู่ยงคงกระพันสิ้นสุดลง ภูตผี Dreamwalker 2 ตัวจะถูกเรียกมาล้อมรอบ Aurorians ภูตผีไม่สามารถถูกโจมตีได้",
  str_monster_name_2904001 = "เบนนูการ์เดียน",
  str_monster_name_2904001_en = "Bennuguardian",
  str_monster_desc_2904001 = "ผู้พิทักษ์โบราณที่อาศัยอยู่ในส่วนลึกของ Secret Territory ตื่นขึ้นเนื่องจากการรบกวนจากผู้บุกรุกบ่อยครั้ง แม้แต่ Eclipsites ก็ยังกลัวความสามารถอันทรงพลังของมัน เดินไปรอบ ๆ สนามรบอย่างไร้จุดหมาย",
  str_monster_ability_2904001 = "มีพลังอันยิ่งใหญ่ สะสม Fury เมื่อถูกโจมตี เมื่อ Fury ถึงระดับหนึ่ง จะเข้าสู่สถานะ Enraged ลดความเสียหายที่ได้รับและร่ายทักษะที่ทรงพลังเพิ่มเติม หาก Bennuguardian อยู่ยงคงกระพันเมื่อดำเนินการ มันจะใช้พลังงานฟื้นฟูเพื่อฟื้นฟู HP เต็ม",
  str_monster_name_2904202 = "ผู้ท่องความฝัน ภาพหลอน",
  str_monster_passiveskill_name_29040011 = "การเกิดใหม่ Bennu",
  str_monster_passiveskill_desc_29040011 = "หาก Bennuguardian อยู่ยงคงกระพันเมื่อดำเนินการ มันจะใช้พลังงานฟื้นฟูเพื่อฟื้นฟู HP เต็ม กอง Fury ของมันถูกล้างในเวลาเดียวกัน",
  str_monster_passiveskill_name_29040012 = "Bennu โกรธ",
  str_monster_passiveskill_desc_29040012 = "Bennuguardian สะสม Fury เมื่อถูกโจมตี เมื่อ Fury สะสมครบ 50 หน่วย จะเข้าสู่สถานะ Enraged ลดความเสียหายที่ได้รับและร่ายทักษะโจมตีที่ทรงพลังเพิ่มเติมหลังจากดำเนินการในแต่ละรอบ หลังจากใช้ทักษะนี้ สถานะโกรธของ Bennuguardian จะจางหายไป",
  str_monster_name_2002101 = "โคเซ็น",
  str_monster_name_2002101_en = "Cozen",
  str_monster_desc_2002101 = "มีความสามารถที่โดดเด่นในการผสมผสานเข้ากับสภาพแวดล้อม บางครั้งมันก็ดูเหมือนกับดักธรรมดา อย่างไรก็ตาม เมื่อมันเปิดเผยตัว มันก็ระเบิดอาละวาดอย่างอาฆาต",
  str_monster_ability_2002101 = "มักจะซ่อนอยู่ใน Crud เมื่อการนับถอยหลังสิ้นสุดลง มันจะปรากฏตัวขึ้นและโจมตีพวกออโรเรียน",
  str_monster_passiveskill_name_2002101 = "หยาบ",
  str_monster_passiveskill_desc_2002101 = "เมื่อการนับถอยหลังของ Crud สิ้นสุดลง Cozen จะปรากฏตัวขึ้นและโจมตี Aurorians",
  str_monster_name_2904301 = "รีกัล",
  str_monster_name_2904401 = "เรเควียม",
  str_monster_name_2904501 = "ฟรอสต์ไฟร์",
  str_monster_name_2904601 = "มิธอส",
  str_monster_name_2904301_en = "Regal",
  str_monster_name_2904401_en = "Requiem",
  str_monster_name_2904501_en = "Frostfire",
  str_monster_name_2904601_en = "Mythos",
  str_monster_passiveskill_name_2904301 = "Regal Hoarfrost",
  str_monster_passiveskill_desc_2904301 = "มีความสามารถในการโต้กลับ ได้รับ Vis 1 แต้มทุกครั้งที่ Aurorian ร่าย Active Skills เมื่อ Vis สะสมครบ 10 แต้ม จะได้รับเอฟเฟกต์เพิ่ม ATK แบบซ้อนได้เมื่อเริ่มรอบของมอนสเตอร์ อยู่จนจบการต่อสู้",
  str_monster_passiveskill_name_2904401 = "บังสุกุล Taboo Breaker",
  str_monster_passiveskill_desc_2904401 = "มีความสามารถในการโต้กลับ ได้รับ Vis 1 แต้มทุกครั้งที่ Aurorian ร่าย Active Skills เมื่อ Vis สะสมครบ 10 แต้ม ทำการโจมตีเต็มหน้าจอเมื่อเริ่มรอบของมอนสเตอร์ สร้างความเสียหายให้กับเป้าหมายทั้งหมด",
  str_monster_passiveskill_name_2904501 = "Frost Fire: ความผิดพลาด",
  str_monster_passiveskill_desc_2904501 = "มีความสามารถในการโต้กลับ ได้รับ Vis 1 แต้มทุกครั้งที่ Aurorian ร่าย Active Skills เมื่อ Vis สะสมครบ 10 แต้ม ทำเครื่องหมายพื้นที่ของสนาม และเมื่อเริ่มรอบของมอนสเตอร์ ปลดปล่อยความเสียหายอย่างรุนแรงในพื้นที่ที่ทำเครื่องหมายไว้",
  str_monster_passiveskill_name_2904601 = "เพลงกล่อมเด็ก: The Hunt",
  str_monster_passiveskill_desc_2904601 = "มีความสามารถในการโต้กลับ ได้รับ Vis 1 แต้มทุกครั้งที่ Aurorian ร่าย Active Skills เมื่อ Vis สะสมครบ 10 แต้ม ทำเครื่องหมายพื้นที่ของสนาม และเมื่อเริ่มรอบของมอนสเตอร์ ปลดปล่อยความเสียหายอย่างรุนแรงในพื้นที่ที่ทำเครื่องหมายไว้",
  str_monster_name_2904101 = "โหย",
  str_monster_name_2904101_en = "Yoh",
  str_monster_desc_2904101 = "เมื่อเป็นผู้นำของงู เขาถูกกดขี่โดย Aurorians เพื่อใช้เป็นเครื่องมือในการนำทาง ปีแห่งความเกลียดชังที่เพิ่มขึ้นทำให้เขากลายเป็นศัตรูที่ทรงพลัง",
  str_monster_ability_2904101 = "มีความสามารถทางเวทมนตร์ที่ทรงพลังและสามารถควบคุมกระสุนเพื่อสร้างความเสียหายแก่ศัตรู",
  str_monster_name_2002202 = "คำ",
  str_monster_desc_2002202 = "Yoh ฉายคำพูดในใจของเขาให้เป็นจริงเพื่อโจมตีศัตรูของเขา",
  str_monster_ability_2002202 = "เมื่อภาพลวงตาไม่ทำงาน Yoh ควบคุม \"Words\" เหวี่ยงพวกมันเหมือนกระสุนปืนเพื่อโจมตี Aurorian โดยตรง (ชาวออโรเรียนสามารถทำลายขีปนาวุธในช่วงเวลานี้เพื่อหลีกเลี่ยงการได้รับความเสียหาย)",
  str_monster_desc_49031011 = "บุคลากรฝ่ายเทคโนโลยีของเรดีเซล เวรนช์ที่มั่นใจในเทคโนโลยีการสื่อสารของเธอมาก เธอชอบบ่นและตะคอกคนอื่นในช่องสื่อสารแต่กลับหงุดหงิดเมื่อเจอปัญหา",
  str_monster_ability_4903103 = "ย้ายไปยังตำแหน่งที่ไกลที่สุดจากเป้าหมายเสมอ สกิลสร้างความเสียหายเป็นบริเวณกว้าง ทักษะที่ชาร์จได้จะสร้างความเสียหายเต็มหน้าจอและทำให้เป้าหมายกระเด็นถอยหลัง",
  str_monster_ability_4900232 = "Vani สามารถใช้ Energy เพื่อโจมตีจากระยะไกล",
  str_monster_passiveskill_name_48004341 = "ชุบชีวิต",
  str_monster_passiveskill_desc_48004341 = "Mara Sol ฟื้น HP 50% เมื่อใกล้ตาย จากนั้นจึงเพิ่มความสามารถในการโต้กลับ แต่ยังได้รับความเสียหายเพิ่มขึ้นด้วย สกิลติดตัวนี้สามารถใช้ได้ครั้งเดียวเท่านั้น",
  str_monster_passiveskill_name_48004342 = "แคซซึม",
  str_monster_passiveskill_desc_48004342 = "มีผลหลังจาก Mara Sol ฟื้นคืนชีพ เมื่อไรก็ตามที่ Aurorian ใช้สกิลเรียกใช้ Mara Sol จะเรียก Chasm มาที่สนาม",
  str_monster_ability_4000124 = "Eclipsite ที่มีความสามารถในการอัญเชิญระดับต่ำ ไม่สามารถเคลื่อนไหวได้ด้วยตัวเองและต่อสู้โดยอัญเชิญ Chasms",
  str_monster_name_2002301 = "ผู้ช่วยที่ไม่มีเสียง",
  str_monster_desc_2002301 = "เป็นไปได้ว่า \"ผู้ให้คำปรึกษา\" ของ Eclipsite บางประเภทเห็นว่าพวกเขาทั้งสองรักษา Eclipsites อื่น ๆ ได้อย่างไร ข้อแตกต่างคือ Eclipsite นี้มีแนวโน้มที่จะอยู่ใกล้พันธมิตรที่ตัวใหญ่กว่าเพื่อใช้ประโยชน์สูงสุดจากเอฟเฟกต์พิเศษของสกิล",
  str_monster_ability_2002301 = "Aphonic Assistant เคลื่อนไปยังทิศทางที่มี Eclipsites จำนวนมากที่สุด สามารถฟื้นฟู HP ของ Eclipsites อื่นได้ ยิ่งกระเบื้องครอบครองโดย Eclipsites อื่น ๆ ภายในระยะทักษะของ Aphonic Assistant มากเท่าไหร่ ผลของการรักษาก็จะยิ่งแข็งแกร่งขึ้นเท่านั้น",
  str_monster_name_2904801 = "หนอนทรายสีชมพู",
  str_monster_name_2904801_en = "Pink Sandworm",
  str_monster_desc_2904804 = "หนอนทรายหายากที่มีถิ่นกำเนิดในทะเลทราย Rediesel มันถูกปกคลุมไปด้วยเกล็ดสีชมพูเนื่องจากการกลายพันธุ์ที่ไม่เหมือนใคร ทำให้มันมีพลังและดุร้ายกว่าหนอนทรายตัวอื่นๆ เนื่องจากลักษณะที่หายากและพิเศษของมัน นักทำนายที่ไร้ยางอายบางคนจึงอ้างว่าเกล็ดของมันเป็นสมบัติหายากที่สามารถสร้างเป็นยาวิเศษที่สามารถทำให้ความปรารถนาของทุกคนเป็นจริงได้ แต่ความจริงแล้วมันก็เป็นเพียงเกล็ดสีชมพูธรรมดาที่ไม่มีฟังก์ชั่นพิเศษใดๆ .",
  str_monster_ability_2904801 = "เจาะดินเพื่อหาตำแหน่งของเป้าหมาย แล้วระเบิดออกในที่โล่ง เก่งกาจในการพ่นทรายดำโจมตีเป้าหมายที่อยู่ข้างหน้า",
  str_monster_name_2904701 = "นายพรานกล",
  str_monster_name_2904701_en = "Mechanical Huntsman",
  str_monster_desc_2904701 = "ผู้พิทักษ์โบราณที่สร้างขึ้นเพื่อจุดประสงค์เดียวในการปกป้องความลับของดินแดนนี้ การโจมตีของมันยากที่จะหลบหนี และยังมีการฟื้นฟูตัวเองอย่างเหลือเชื่อเพื่อให้มันทำงานได้ตลอดไป คงไม่มีใครอยากเผชิญหน้าเพียงลำพัง",
  str_monster_ability_2904701 = "สร้างเขตป้องกันภายใน 2 กลุ่มรอบๆ ตัวมันเองทุกรอบ Aurorians ภายในเขตป้องกันจะได้รับความเสียหายเพิ่มเติมเมื่อใดก็ตามที่พวกเขาโจมตีหรือเคลื่อนไหว หาก Mechanical Huntsman อยู่ยงคงกระพันเมื่อดำเนินการ มันจะใช้พลังงานฟื้นฟูเพื่อฟื้นฟู HP เต็ม",
  str_monster_name_2904901 = "อัศวินทั้งสี่",
  str_monster_name_2904901_en = "อัศวินทั้งสี่",
  str_monster_desc_2904901 = "แม้ว่าพวกเขาจะดูเหมือนสมาชิกคณะลูกขุนทั่วไป แต่หมวกปูนปลาสเตอร์บนหัวทำให้พวกเขาดูน่าสงสัยมาก ปรากฎว่ามี Eclipsites ซ่อนอยู่ใต้พวกมัน! สิ่งที่น่าสับสนคือพวกเขาดูเหมือนจะทำตามคำสั่งของใครบางคน...",
  str_monster_ability_2904901 = "Four Knights มีการโจมตีที่ทรงพลังและความสามารถในการเทเลพอร์ตที่ยอดเยี่ยม เมื่อใดก็ตามที่ 1 ใน 4 อัศวินถูกโจมตีหรือฟื้น HP อัศวินคนอื่นๆ จะได้รับความเสียหายเท่ากันหรือฟื้น HP เท่ากัน",
  str_monster_passiveskill_name_2904901 = "อัศวินทั้งสี่: ซึ่งกันและกัน",
  str_monster_passiveskill_desc_2904901 = "เมื่อใดก็ตามที่ 1 ใน 4 อัศวินถูกโจมตีหรือฟื้น HP อัศวินคนอื่นๆ จะได้รับความเสียหายเท่ากันหรือฟื้น HP เท่ากัน",
  str_monster_name_2905501 = "เดม่อนฮาติ",
  str_monster_name_2905501_en = "เดม่อนฮาติ",
  str_monster_desc_2905501 = "ความทรงจำในอดีตท่วมท้นหัวใจของเธอ ทำให้ Demon Hound ที่น่ากลัวกลายเป็นความเกลียดชังที่เข้าควบคุม",
  str_monster_ability_2905501 = "เมื่อ Demon Hati ใกล้จะตาย เธอสามารถใช้พลังงานฟื้นฟูเพื่อฟื้นฟู HP ของตัวเองให้เต็ม เธอจะใช้ทักษะที่ทรงพลังและปรับปรุงตัวเองด้วย Demon Hati สร้างความเสียหายได้มากขึ้นเมื่อ HP ของเธอลดลงและตอบโต้ Active Skills",
  str_monster_ability_2905502 = "Demon Hati ใช้ HP ส่วนหนึ่งเพื่อโจมตีและฟื้นฟู HP ที่เสียไปส่วนหนึ่ง หาก Aurorian ถูกโจมตี Demon Hati สร้างความเสียหายได้มากขึ้นเมื่อ HP ของเธอลดลง!",
  str_monster_ability_2905503 = "เมื่อ Demon Hati ใกล้จะตาย เธอสามารถใช้พลังงานฟื้นฟูเพื่อฟื้นฟู HP ของตัวเองให้เต็ม เธอจะใช้ทักษะที่ทรงพลังและปรับปรุงตัวเองด้วย Demon Hati สร้างความเสียหายได้มากขึ้นเมื่อ HP ของเธอลดลง!",
  str_monster_ability_2905504 = "เมื่อ Demon Hati ใกล้จะตาย เธอสามารถใช้พลังงานฟื้นฟูเพื่อฟื้นฟู HP ของตัวเองให้เต็ม เธอจะใช้ทักษะที่ทรงพลังและปรับปรุงตัวเองด้วย Demon Hati สร้างความเสียหายได้มากขึ้นเมื่อ HP ของเธอลดลงและตอบโต้ Active Skills",
  str_monster_passiveskill_name_2905501 = "Demon Hati: การพักฟื้น",
  str_monster_passiveskill_desc_2905501 = "เมื่อ Demon Hati เหลือ HP ต่ำ เธอจะใช้พลังงานฟื้นฟูเพื่อฟื้นฟูตัวเองให้ HP เต็ม",
  str_monster_passiveskill_name_2905502 = "Demon Hati: Nether Flames",
  str_monster_passiveskill_desc_2905502 = "เมื่อใดก็ตามที่ Demon Hati ใช้พลังงานฟื้นฟู เธอจะกลายเป็น Demon Hati: Ominous Flame ในรอบนี้ เทเลพอร์ตไปข้างๆ Aurorians และใช้ 15% ของ HP ปัจจุบันของเธอเพื่อสร้างความเสียหายอย่างใหญ่หลวงต่อ Aurorians หากเธอโจมตีโดนเป้าหมาย จะฟื้น 15% ของ HP ที่เสียไป",
  str_monster_passiveskill_name_2905503 = "Demon Hati: การยังชีพ",
  str_monster_passiveskill_desc_2905503 = "Demon Hati ฟื้น HP บางส่วนที่หายไปเมื่อสร้างความเสียหายแก่ Aurorians",
  str_monster_passiveskill_name_2905504 = "Demon Hati: ดุร้าย",
  str_monster_passiveskill_desc_2905504 = "ยิ่ง HP ของ Demon Hati ต่ำลง ความเสียหายที่ทำได้จากสกิลก็จะยิ่งมากขึ้นเท่านั้น",
  str_monster_passiveskill_name_2905505 = "Demon Hati: ตอบโต้",
  str_monster_passiveskill_desc_2905505 = "เมื่อใดก็ตามที่ Aurorian ใช้ Active Skill Demon Hati จะเทเลพอร์ตไปหา Aurorian ให้ใกล้ที่สุดเท่าที่จะเป็นไปได้ภายใน 1 กลุ่มที่อยู่รอบๆ จากนั้นโจมตีเป้าหมายภายใน 1 กลุ่มรอบๆ",
  str_monster_passiveskill_name_2905506 = "Demon Hati: ตอบโต้",
  str_monster_passiveskill_desc_2905506 = "เมื่อใดก็ตามที่ Aurorian ใช้ Active Skill Demon Hati จะเทเลพอร์ตไปหา Aurorian ให้ใกล้ที่สุดเท่าที่จะเป็นไปได้ภายใน 2 กลุ่มที่อยู่รอบๆ จากนั้นโจมตีเป้าหมายภายใน 1 กลุ่มที่อยู่รอบๆ",
  str_monster_name_2905101 = "ช่างเจาะ",
  str_monster_name_2905101_en = "Driller",
  str_monster_desc_2905101 = "หุ่นยนต์ต่อสู้ที่พัฒนาโดย Illumina มันทำงานได้ดีมากในการทดสอบภายใน แต่ยังไม่ได้รับการทดสอบในการต่อสู้จริง",
  str_monster_ability_2905101 = "Driller มี 2 สถานะ มันเคลื่อนที่ไปรอบ ๆ สนามในสถานะปกติและขุดสนามพลังงานและสนามสนับสนุนตามจำนวนที่กำหนดทุกรอบ เมื่อมีสนามพลังงานจำนวนหนึ่งบนสนาม มันจะดูดซับและประกอบแท่นขุดเจาะ",
  str_monster_name_2905102 = "แท่นเจาะ",
  str_monster_name_2905102_en = "Driller Platform",
  str_monster_name_2905001 = "สไปเดอร์ควีน",
  str_monster_name_2905001_en = "Spider Queen",
  str_monster_desc_2905001 = "Eclipsite พิเศษนี้มีลักษณะคล้ายแมงมุมและได้เรียนรู้พฤติกรรมของกลุ่มแมงมุมในเส้นทางวิวัฒนาการของมัน มันซ่อนตัวอยู่ในความมืดที่แสงแดดส่องไม่ถึง",
  str_monster_ability_2905001 = "มีความสามารถในการสืบพันธุ์ที่แข็งแกร่ง มันสานใยแมงมุมในสภาพแวดล้อมการล่าสัตว์",
  str_monster_name_2002401 = "ฟักไข่แมงมุม",
  str_monster_desc_2002401 = "ผู้สืบทอดของราชินีแมงมุมผู้มีความตระหนักรู้ในตนเองที่อ่อนแอและปฏิบัติตามคำสั่งของเธอทุกอย่าง",
  str_monster_ability_2002401 = "ตามคำสั่งของราชินีแมงมุม Spider Hatchlings จะรวมตัวกันเป็นกลุ่มและโจมตีเหยื่อของพวกมัน",
  str_monster_passiveskill_name_2002401 = "การรวบรวมข้อมูลเว็บ",
  str_monster_passiveskill_desc_2002401 = "Spider Hatchlings คลานไปตามใยและจะสร้างเส้นทางของตัวเองเมื่อไม่มีที่ไป",
  str_monster_name_2905201 = "ฟิเจอรัลด์",
  str_monster_name_2905201_en = "ฟิเจอรัลด์",
  str_monster_desc_2905201 = "ในฐานะหนึ่งในเจตภูตที่ทรงพลังที่สุด เขาโจมตีด้วยกำลังทั้งหมดที่มีเมื่อสถานะของเขาถูกคุกคาม",
  str_monster_ability_2905201 = "มีพลังในการทำลายสิ่งแวดล้อมและรักษาระยะห่างจาก Aurorians เสมอ",
  str_monster_name_2002501 = "กลุ่มทหารอิลลูมินา",
  str_monster_desc_2002501 = "ทหารรบทั่วไปในกองทัพอิลลูมินา เป็นที่รู้จักจากทักษะการใช้ปืนไรเฟิลและมีดต่อสู้ ตลอดจนความดื้อรั้น จรรยาบรรณในการทำงาน ความกระตือรือร้นในการรบ และจิตวิญญาณแห่งการต่อสู้ที่กล้าหาญ",
  str_monster_ability_2002501 = "ใช้การโจมตีระยะไกลมากขึ้น เมื่อการต่อสู้ดุเดือด พุ่งเข้าหาศัตรูและต่อสู้ระยะประชิดเพื่อกำจัดพวกมันให้เร็วที่สุด",
  str_monster_ability_2002502 = "นักสู้ระยะประชิดที่มีทักษะในการตรวจจับและตอบสนองต่อการเคลื่อนไหวของศัตรูในระหว่างการต่อสู้ที่เข้มข้น ทำให้สามารถโจมตีโต้กลับได้อย่างมีประสิทธิภาพ",
  str_monster_passiveskill_name_200250103 = "ความดื้อรั้นในการต่อสู้",
  str_monster_passiveskill_desc_200250103 = "เมื่อ HP ต่ำกว่า 50% การโจมตีด้วยอาวุธทั้งหมดจะกลายเป็นการโจมตีระยะประชิดด้วยมีดต่อสู้ ในเวลาเดียวกัน รอยช้ำที่สะสมทั้งหมดจะเปลี่ยนเป็น HP ที่ฟื้นฟูและเพิ่ม ATK และ DEF",
  str_monster_passiveskill_name_200250113 = "การโต้กลับที่เฉียบคม",
  str_monster_passiveskill_desc_200250113 = "แต่ละครั้งที่ศัตรูใช้สกิลเรียกใช้ ทหารอิลลูมิน่าจะดำเนินการต่อ 1 ช่องและโจมตี",
  str_monster_name_2905301 = "ทดสอบสถานะ Helios",
  str_monster_name_2905301_en = "ทดสอบสถานะ Helios",
  str_monster_desc_2905301 = "หลังจากอยู่คนเดียวมานานกว่าทศวรรษใน Dark Zone ทหาร Illumina คนนี้ได้ลืมทุกอย่างยกเว้นการต่อสู้ สิ่งที่น่ากลัวคือเขาแข็งแกร่งขึ้นในการต่อสู้หลังจากถูกดัดแปลงโดยใครบางคน...",
  str_monster_ability_2905301 = "เอนทิตีที่มีความสามารถในการต่อสู้ที่แข็งแกร่งและสะสมรอยฟกช้ำเมื่อได้รับความเสียหาย เมื่อการโจมตีของเขาพลาดเป้า เครื่องหมาย Terror Mark จะถูกปล่อยออกมาในสนาม ทักษะของ Helios นั้นทรงพลังยิ่งขึ้นเมื่อมี Terror Mark ทุกอันบนสนาม",
  str_monster_passiveskill_name_29053011 = "เย็นชาไร้เยื่อใย",
  str_monster_passiveskill_desc_29053011 = "เมื่อได้รับความเสียหาย Helios จะสะสมรอยช้ำเท่ากับ 50% ของความเสียหายที่ได้รับ",
  str_monster_passiveskill_name_29053012 = "เครื่องหมายความหวาดกลัว",
  str_monster_passiveskill_desc_29053012 = "เมื่อ Dread Rush หรือ Leap of Terror ของ Helios พลาดเป้า เครื่องหมาย Terror Mark จะถูกปล่อยออกมาในสนาม: เขาสร้างความเสียหายให้กับเป้าหมายโดยตรงและสร้างเครื่องหมายบนกระเบื้องที่เป้าหมายอยู่",
  str_monster_passiveskill_name_2904701 = "ชุบชีวิต: เคาน์เตอร์",
  str_monster_passiveskill_desc_2904701 = "หาก Mechanical Huntsman อยู่ยงคงกระพันเมื่อมันลงมือ มันจะใช้พลังงานฟื้นฟูเพื่อฟื้น HP เต็ม ในรอบถัดไปหลังจากฟื้นตัว Mechanical Huntsman จะใช้ทักษะที่อันตรายอย่างยิ่งซึ่งลด HP ของ Aurorians ภายในเขตป้องกันเหลือ 1",
  str_monster_passiveskill_name_2905102 = "การถอดแท่นขุดเจาะ",
  str_monster_passiveskill_desc_2905102 = "Driller และ Driller Platform มี HP แยกกัน ในโหมดแพลตฟอร์ม Driller ผู้เล่นสามารถโจมตี Driller ซึ่งซ่อนอยู่หลังแท่นได้ หากแท่นเจาะไม่สามารถอยู่ยงคงกระพันได้ มันจะแยกชิ้นส่วนโดยอัตโนมัติเพื่อแสดงตัวเจาะ",
  str_monster_passiveskill_name_2905101 = "การควบคุมสว่าน",
  str_monster_passiveskill_desc_2905101 = "เมื่อ Driller ดำเนินการ หากมี 6 Energy Fields บนฟิลด์ มันจะเรียก Driller Platform ซึ่งครอบครอง 5 แผ่นที่มันยืนอยู่",
  str_monster_name_2905401 = "โจชัว: วิญญาณที่แปดเปื้อน",
  str_monster_name_2905401_en = "Joshua: Tainted Soul",
  str_monster_desc_2905401 = "การบุกรุกของสสารชั่วร้ายนำมาซึ่งความเจ็บปวดและความปวดร้าวอย่างไม่หยุดยั้ง... การดำรงอยู่ของเธอซึ่งไม่เคยมีความหมายต่อโลกนี้ ถือกำเนิดขึ้นโดยมัน...",
  str_monster_ability_2905401 = "เธอควบคุมสิ่งรอบข้างได้อย่างมหาศาล และต้านทานการโจมตีปกติและทักษะของพวกออโรเรียนได้บางส่วน",
  str_monster_name_2003201 = "ไมม์ คาร์ติมา",
  str_monster_name_2003201_en = "Mime Kartima",
  str_monster_desc_2003201 = "\"ฉันจะปกป้องเกียรติของ Kartimas\"",
  str_monster_ability_2003201 = "ในขณะที่ถือโล่เพื่อป้องกัน Mime Kartima จะสลับไปมาระหว่างไม้พลองและโล่อย่างเชี่ยวชาญเพื่อโจมตีเป้าหมายตามตำแหน่งของพวกเขา",
  str_monster_name_2003202 = "ลูโมโพลิส แฮมเมอร์การ์ด",
  str_monster_name_2003202_en = "Lumopolis Hammerguard",
  str_monster_desc_2003202 = "ปรับปรุง: ผู้พิทักษ์ชั้นยอดของ Lumopolis โล่และชุดเกราะที่ยากจะหยั่งถึงของพวกเขาตั้งตระหง่านเป็นป้อมปราการ ในขณะที่ค้อนสายฟ้าฟาดก้องเหมือนหิมะถล่มอันยิ่งใหญ่",
  str_monster_ability_2003202 = "ในขณะที่ถือโล่เพื่อป้องกัน Mime Kartima จะสลับไปมาระหว่างไม้พลองและโล่อย่างเชี่ยวชาญเพื่อโจมตีเป้าหมายตามตำแหน่งของพวกเขา",
  str_monster_passiveskill_name_200320105 = "Kartima: Shieldguard",
  str_monster_passiveskill_desc_200320105 = "Kartima เหวี่ยงโล่ของเขา ลดความเสียหายจากการโจมตีด้านหน้า สูญเสียเอฟเฟกต์เมื่อมึนงง หวาดกลัว เป็นอัมพาต หรือได้รับผลกระทบจากการควบคุมอื่น ๆ",
  str_monster_passiveskill_name_200320106 = "Kartima: ไม่ยอม",
  str_monster_passiveskill_desc_200320106 = "Kartima ต้านทานต่อ Stun, Frighten, Paralysis และ Control effect อื่นๆ เป็นเวลา 2 รอบหลังจากเข้าร่วมการต่อสู้",
  str_monster_passiveskill_desc_200320107 = "Kartima ต้านทานต่อ Stun, Frighten, Paralysis และ Control effect อื่นๆ เป็นเวลา 1 รอบหลังจากเข้าร่วมการต่อสู้",
  str_monster_passiveskill_desc_200320108 = "Kartima ต้านทานต่อ Stun, Frighten, Paralysis และ Control effect อื่นๆ เป็นเวลา 3 รอบหลังจากเข้าร่วมการต่อสู้",
  str_monster_passiveskill_desc_200320109 = "Kartima ต้านทานต่อ Stun, Frighten, Paralysis และเอฟเฟกต์การควบคุมอื่นๆ เป็นเวลา 5 รอบหลังจากเข้าร่วมการต่อสู้",
  str_monster_passiveskill_name_200320205 = "ชิลด์การ์ด",
  str_monster_passiveskill_desc_200320205 = "Lumopolis Hammerguard เหวี่ยงโล่ของเขา ลดความเสียหายจากการโจมตีด้านหน้า สูญเสียเอฟเฟกต์เมื่อมึนงง หวาดกลัว เป็นอัมพาต หรือได้รับผลกระทบจากการควบคุมอื่น ๆ",
  str_monster_passiveskill_name_200320206 = "ไร้พ่าย",
  str_monster_passiveskill_desc_200320206 = "ต้านทานต่อ Stun, Frighten, Paralysis และเอฟเฟกต์การควบคุมอื่น ๆ เป็นเวลา 2 รอบหลังจากเข้าร่วมการต่อสู้",
  str_monster_passiveskill_desc_200320207 = "ต้านทานการทำให้มึนงง ทำให้ตกใจ เป็นอัมพาต และเอฟเฟกต์การควบคุมอื่น ๆ เป็นเวลา 1 รอบหลังจากเข้าร่วมการต่อสู้",
  str_monster_passiveskill_desc_200320208 = "ต้านทานต่อ Stun, Frighten, Paralysis และเอฟเฟกต์การควบคุมอื่นๆ เป็นเวลา 3 รอบหลังจากเข้าร่วมการต่อสู้",
  str_monster_passiveskill_name_39002111 = "เรียกหิน",
  str_monster_passiveskill_desc_39002111 = "Umbrahulk เรียก Pebbles แบบสุ่มเข้าสู่สนามรบเมื่อสิ้นสุดแต่ละรอบ",
  str_monster_passiveskill_name_3900452 = "พลังที่ถูกทอดทิ้ง",
  str_monster_passiveskill_desc_3900452 = "เมื่อมอนสเตอร์ที่ถูก Forsaken ได้รับความเสียหาย เอฟเฟกต์ต้านธาตุจะเพิ่มขึ้น 100%\nมอนสเตอร์ที่ถูกทอดทิ้งจะเพิ่มพลังอย่างต่อเนื่องตามความเสียหายที่ได้รับ",
  str_monster_passiveskill_name_3900453 = "พลังที่ถูกทอดทิ้ง",
  str_monster_passiveskill_desc_3900453 = "มอนสเตอร์ที่ถูกทอดทิ้งจะเพิ่มพลังอย่างต่อเนื่องตามความเสียหายที่ได้รับ",
  str_monster_name_2904804 = "ถูกทอดทิ้ง: หนอนทรายสีชมพู",
  str_monster_name_2904804_en = "Forsaken: Pink Sandworm",
  str_monster_name_4904901 = "ถูกทอดทิ้ง: อัศวินทั้งสี่",
  str_monster_name_4904901_en = "Forsaken: The Four Knights",
  str_monster_name_39038011 = "ถูกทอดทิ้ง: แอสเตอร์",
  str_monster_name_39038011_en = "Forsaken: Astor",
  str_monster_name_3100311 = "ถูกทอดทิ้ง: Augean",
  str_monster_name_3100311_en = "Forsaken: Augean",
  str_monster_desc_3900311 = "Forsaken: Augean ต้านทานการโจมตีของ Aurorian ทั้งหมด และเรียกร่างโคลนออกมาเพื่อต่อสู้กับผู้เล่น ความเสียหายที่เกิดขึ้นกับร่างโคลนจะถูกถ่ายโอนไปยังตัวหลัก",
  str_monster_ability_3100311 = "ชุบชีวิตร่างโคลนทุกรอบ ร่างโคลนสามารถโจมตีเป้าหมายได้หลายครั้งและทำให้เลือดไหล เคาน์เตอร์การเคลื่อนไหว: ทุกครั้งที่ Aurorian ใช้ Active Skill รอบนี้ ระยะการเคลื่อนไหวของร่างโคลนจะเพิ่มขึ้น",
  str_monster_name_3100312 = "โคลนที่ถูกทอดทิ้ง",
  str_monster_desc_3900312 = "1. ความเสียหายทั้งหมดที่ได้รับจะถูกถ่ายโอนไปยังตัวหลักทั้งหมด ไม่สามารถป้องกันความเสียหายตามเปอร์เซ็นต์ได้\n2. ตัวโคลนจะมี ATK และ DEF เหมือนกับตัวหลัก Max HP ของร่างโคลนจะเพิ่มขึ้นตามจำนวนความเสียหายที่ทำกับตัวหลัก",
  str_monster_ability_3100312 = "ร่างโคลนสามารถโจมตีเป้าหมายได้หลายครั้ง Movement Counter: ระยะการเคลื่อนที่ของร่างโคลนจะเพิ่มขึ้นทุกครั้งที่ Aurorian ใช้ Active Skill ในระหว่างรอบปัจจุบัน",
  str_monster_name_531400511 = "มีอา: จิตวิญญาณที่แวววาว",
  str_monster_name_531400511_en = "Mia: Lustrous Soul",
  str_monster_desc_531400511 = "อัศวินลูโมโพลิสผู้ใช้ชีวิตอย่างสันโดษในอัมบราตัน",
  str_monster_ability_531400511 = "ได้รับบัฟ ATK เพิ่มเติมเมื่อ HP ต่ำ มอบโล่ให้ตัวเองทุกๆ 3 รอบเพื่อต้านทานความเสียหาย",
  str_monster_name_4902501 = "ถูกทอดทิ้ง: มินอส",
  str_monster_name_4902501_en = "Forsaken: Minos",
  str_monster_passiveskill_name_4902501 = "ถูกทอดทิ้ง: การสลายตัวที่ถูกกำหนด",
  str_monster_passiveskill_desc_4902501 = "สร้างกระเบื้องที่อ่อนแอ 4 แผ่นบนกระเบื้องแนวทแยงทุกรอบ",
  str_monster_passiveskill_name_4902502 = "ถูกทอดทิ้ง: เงาจู่โจม",
  str_monster_passiveskill_desc_4902502 = "ถ้าถูกทอดทิ้ง: มินอสผ่านช่องเสริมพลังหรือช่องอ่อนแอ แฟนท่อมจะถูกเรียกขึ้นมาสร้างดาเมจให้กับออโรเรียน",
  str_monster_name_4900511 = "ถูกทอดทิ้ง: โนซาร์ด",
  str_monster_name_4900511_en = "Forsaken: Nozard",
  str_monster_ability_4900511 = "ด้วยความโกรธ Nozard ตบพื้นอย่างต่อเนื่องเพื่อกระแทกผู้เล่นและเรียก Gloom Ghouls มาช่วยในการต่อสู้ Nozard ไม่ได้รับความเสียหายจากการโจมตีปกติ",
  str_monster_name_2905404 = "โจชัว: ทูตสวรรค์มืด",
  str_monster_name_2905404_en = "Joshua: Dark Angel",
  str_monster_name_2905405 = "โจชัว: ปีศาจขาว",
  str_monster_name_2905405_en = "Joshua: White Demon",
  str_monster_name_2000255 = "ผู้พิทักษ์ลูโม่ที่ถูกสาป",
  str_monster_name_2000285 = "ต้องคำสาป Lumo Shieldmate",
  str_monster_name_2000295 = "Lumo Piker สาปแช่ง",
  str_monster_desc_2905404 = "ในฐานะที่เป็นศูนย์รวมของความเคียดแค้นที่ไม่รู้จบ มันเป็นส่วนที่ฉีกขาดของอารมณ์ของ Joshua ตัวตนที่น่าเกรงขามที่เกิดในความว่างเปล่า เก็บงำความเป็นปฏิปักษ์ต่อวิญญาณทุกดวงที่แผ่ความรักออกมา",
  str_monster_desc_2905405 = "การอัญเชิญที่ไร้ที่ติจากส่วนลึกของการเรียกร้องของแม่ มันหลั่งอารมณ์ที่ไร้ประโยชน์ออกมาเพื่อบรรลุอุดมคติขั้นสูงสุด เป็นนักฆ่าที่สมบูรณ์แบบโดยไม่กระทบกระเทือนความรู้สึก",
  str_monster_desc_2000255 = "ครั้งหนึ่งเคยเป็นองครักษ์ผู้ภักดีของ Lumopolis ตอนนี้ Joshua เสียหายและถูกขับไล่ให้บ้าคลั่ง",
  str_monster_desc_2000285 = "แม้แต่ผู้พิทักษ์ที่แข็งแกร่งที่สุดก็ไม่สามารถต้านทานความเสื่อมทรามของความชั่วร้ายได้ ขอให้กำแพงเมืองลูโมโพลิสกลับมาบริสุทธิ์อีกครั้ง",
  str_monster_desc_2000295 = "ย้อนกลับไปในสมัยก่อน พวกเขากล่าวว่าผู้ที่ถือหอกมีโชคที่เลวร้ายที่สุด ซึ่งกลายเป็นความจริง เนื่องจากการรุกรานของปีศาจทำให้พวกเขาตกเป็นเป้าหมายตั้งแต่แรกเริ่ม",
  str_monster_desc_2000606 = "Eclipsite นี้เกิดมาจากอารมณ์ด้านลบที่จะติดตามผู้ที่ต้องสาปแช่ง",
  str_monster_ability_2905404 = "ปลดปล่อยพลังแห่งคำสาปที่ไม่มีที่สิ้นสุด และเมื่อพลังแห่งคำสาปครอบงำชีวิตที่ได้รับจากแสงสว่าง ความมืดจะกลืนกินทุกสิ่ง",
  str_monster_ability_2905405 = "ปลดปล่อยพลังแห่งคำสาปที่ไม่มีที่สิ้นสุด และเมื่อพลังแห่งคำสาปครอบงำชีวิตที่ได้รับจากแสงสว่าง ความมืดจะกลืนกินทุกสิ่ง",
  str_monster_ability_2000255 = "ผู้พิทักษ์ที่ถูกคำสาปทำให้หมดสติจะฟื้นคืนชีพอีกครั้งเมื่อถูกล้อมโดย Lurker หรือต่อหน้า Joshua ปลดปล่อยพลังแห่งคำสาปผ่านการโจมตีของพวกเขา",
  str_monster_ability_2000285 = "เพื่อนร่วมโล่ที่ถูกคำสาปทำให้หมดสติ จะฟื้นคืนชีพอีกครั้งเมื่อถูก Lurker โอบล้อมหรืออยู่ต่อหน้า Joshua ปลดปล่อยพลังแห่งคำสาปผ่านการโจมตีของพวกเขา",
  str_monster_ability_2000295 = "Pikers ซึ่งหมดสติเพราะคำสาป จะฟื้นคืนชีพอีกครั้งเมื่อถูก Lurker โอบล้อมหรืออยู่ต่อหน้า Joshua ปลดปล่อยพลังแห่งคำสาปผ่านการโจมตีของพวกเขา",
  str_monster_ability_2000606 = "ค้นหาทหารที่ถูกสาปแห่ง Lumopolis เข้าครอบครองและทำให้ทหารที่สลบไสลตื่นขึ้นและตกอยู่ในอาการคลุ้มคลั่ง",
  str_monster_passiveskill_name_2000255 = "ต้องสาป",
  str_monster_passiveskill_desc_2000255 = "เมื่อคุณโจมตี Aurorian ที่ถูกสาป จุดคำสาปจะเพิ่มขึ้น แต่เมื่อตาย Aurorian จะปล่อยแสงสุดท้ายออกมา ลดจุดต้องคำสาป",
  str_monster_passiveskill_desc_4904201 = "เมื่อการอยู่ยงคงกระพันสิ้นสุดลง 1 แฟนทาซัมจะถูกอัญเชิญมาล้อมรอบออโรเรียน",
  str_monster_passiveskill_name_4904202 = "การฟื้นฟูภาพลวงตา",
  str_monster_passiveskill_desc_4904202 = "ภาพลวงตาได้รับความเสียหายจากทักษะเท่านั้นและสามารถถ่ายโอนความเสียหายบางส่วนไปยัง Dreamwalker ได้ เมื่อตาย พวกเขาจะทิ้งกระเบื้องที่แตก 1 แผ่นไว้ที่ฐานก่อนจะฟื้นในรอบต่อไป",
  str_monster_passiveskill_desc_49042021 = "ภาพลวงตาได้รับความเสียหายจากการโจมตีเป้าหมายเดียวและสามารถถ่ายโอนความเสียหายบางส่วนไปยัง Dreamwalker ได้ เมื่อตาย พวกเขาจะทิ้งแผ่นกระเบื้องที่แตก 1 แผ่นไว้ที่ฐานก่อนจะคืนชีพในรอบต่อไป",
  str_monster_name_5900404 = "ชูเมอร์โคลน",
  str_monster_ability_4902501 = "เรียกไพ่ที่อ่อนแอออกมารอบ ๆ ตัวมันทุก ๆ รอบ และดูดซับไพ่ที่เสริมประสิทธิภาพและไพ่ที่อ่อนแรงในสนามเมื่อทำการโจมตี ยิ่งกระเบื้องของ Minos ดูดซับได้มากเท่าไหร่ การโจมตีของ Minos ก็จะยิ่งอันตรายมากขึ้นเท่านั้น",
  str_monster_desc_29009112 = "ศัตรูที่ชั่วร้ายได้กลับมาอีกครั้ง และมันตั้งใจแน่วแน่ที่จะกำจัดศัตรูทั้งหมดของมันในครั้งนี้",
