  str_monster_name_2905601_en = "Denuo Goddess",
  str_monster_desc_2905601 = "ผีเสื้อที่หายากมาก ๆ ซึ่งมีข่าวลือว่าจะปรากฏตัวใกล้ หุบเขาเดนูโอ้ เป็นสิ่งมีชีวิตที่ขี้เกรงใจโดยธรรมชาติ มีประสาทสัมผัสที่คมบางมาก พลังการต่อสู้ของเทพีเดนูโอ้ผู้ใหญ่ไม่ควรถูกมองข้าม",
  str_monster_ability_2905601 = "พวกเขากระตุ้นการเติบโตของพืชผ่านการถ่ายละอองเกสร ป้องกันตัวเองในขณะที่ทำให้ความเสียหายมากให้ศัตรู",
  str_monster_name_2002601 = "Sadesian สาหร่ายมหัศจรรย์",
  str_monster_desc_2002601 = "เริ่มต้นเป็นสิ่งมีชีวิตที่คล้ายกับนิ่ง แต่หลังจากที่เทพีดีนูโอใช้ลูมินากระตุ้นการเติบโต มันจะเปลี่ยนรูปเป็นพืชที่คล้ายกับดอกไม้และสมุนไพร",
