  str_monster_ability_99039011 = "โจมตีศัตรูในระยะประชิดด้วยเสียบปืน หรือโจมตีจากระยะไกลด้วยกระสุน",
  str_monster_desc_9900501 = "พัฒนาจาก Siphorb มันดูดซับ Lumina มากขนาดที่ไม่สามารถควบคุมสีของแสงรอบ ๆ ได้",
  str_monster_passiveskill_name_29060011 = "ความเศร้าโศก: กลายร่าง",
  str_monster_passiveskill_desc_29060011 = "ทุกรอบ อัญเชิญดอกไม้แห่งรุ่งอรุณในตำแหน่งที่กำหนดเพื่อฟื้นฟู HP; ดอกไม้แห่งรุ่งอรุณแต่ละดอกจะช่วยเพิ่มการฟื้นฟูเป็นพิเศษ",
  str_monster_name_2906001 = "อีฟเศร้าโศก",
  str_monster_name_2906001_en = "Grieving Eve",
  str_monster_desc_2906001 = "ความเจ็บปวดจากความโดดเดี่ยวและความกลัวที่จะถูกตัดขาด ความทรงจำในอดีตที่ทนไม่ได้เหล่านั้นได้หล่อหลอมบุคคลที่รู้จักกันในชื่ออีฟในวันนี้",
  str_monster_ability_2906001 = "ในแต่ละรอบ อัญเชิญดอกไม้แห่งรุ่งอรุณในตำแหน่งที่กำหนดในสนามรบ ฟื้นฟู HP ตามจำนวนของดอกไม้แห่งรุ่งอรุณ ในรอบที่กำหนด ได้รับภูมิคุ้มกันหลายกองซ้อน แล้วฟื้นฟู HP ในรอบถัดไปตามกองภูมิคุ้มกัน",
  str_monster_name_2006001 = "ดอกรุ่งอรุณ",
  str_monster_desc_2006001 = "ดอกไม้สีขาวที่เรียบง่าย เล็กและธรรมดาเหล่านี้เป็นความสบายใจที่มีค่าที่สุดในหัวใจของเธอ",
  str_monster_ability_2006001 = "มอบโบนัสฟื้นฟู HP เพิ่มเติมสำหรับ Grieving Eve",
  str_monster_ability_2000401 = "ไม่สามารถเคลื่อนที่หรือโจมตีได้ เชื่อมต่อกับดาร์กซัมมอนเนอร์และให้การลดความเสียหาย",
  str_monster_name_2003001 = "พวกเป่าไฟอิลลูมินา",
  str_monster_desc_2003001 = "\"ลดศัตรูทั้งหมดให้เป็นเถ้าถ่าน\" - คำนี้สะท้อนถึงประสิทธิภาพและความโหดร้ายของกองทัพอิลลูมินา หน้ากากไฟที่คลุกคลานนั้น ชีวิตทุกชีวิตยืนอยู่ในฐานะเท่าเทียมกัน",
  str_monster_ability_2003001 = "สะสมรอยฟกช้ำขณะรับความเสียหาย ทำดาเมจให้เป้าหมายทั้งหมดภายในระยะโจมตี สร้างสถานะเผาไหม้และสร้างเปลวไฟ",
  str_monster_passiveskill_name_2003001 = "คอลัมน์หลักสนามรบ",
  str_monster_passiveskill_desc_2003001 = "เมื่อได้รับความเสียหาย Illumina Flamethrower จะสะสมรอยช้ำเท่ากับ 50% ของความเสียหายที่ได้รับ",
  str_monster_name_2002901 = "ถังอิลลูมินา L5",
  str_monster_desc_2002901 = "ผ่านการปรับปรุงรถบรรทุก รถถัง Illumina L5 มีเกราะเบา ทำให้เหมาะสำหรับการผลิตเป็นจำนวนมาก ความสามารถในการชาร์จและปืนยิงเร็วช่วยให้สามารถกำจัดหน่วยเบาของศัตรูได้อย่างรวดเร็ว",
  str_monster_ability_2002901 = "ตามตำแหน่งของศัตรู เลือกใช้การยิงกระสุนเร็วๆ หรือการพุ่งชนเพื่อโจมตี",
  str_monster_name_2003401 = "ทหารอิลลูมินาผิดคลอง",
  str_monster_name_2003401_en = "ทหารอิลลูมินาผิดคลอง",
  str_monster_desc_2003401 = "เคยเป็นพันธมิตร ตอนนี้กลายเป็นศัตรู - นี่คือความน่ากลัวของอิคลิพส์ ความเมตตาเดียวที่เหลือคือการปล่อยให้พวกเขาหยุดพักผ่อน",
  str_monster_ability_2003401 = "สร้างพื้นโคลนในช่องที่เคลื่อนที่ผ่าน ในขณะที่มี HP ต่ำ จะเพิ่ม ACT อย่างมากและเพิ่ม DEF",
  str_monster_passiveskill_name_20034011 = "จิตใจฉ้อฉล",
  str_monster_passiveskill_desc_20034011 = "หาก HP ต่ำกว่า 40% ณ เริ่มต้นรอบ หน่วยจะเพิ่ม ACT และ DEF และเปลี่ยนรูปแบบการโจมตี",
  str_monster_passiveskill_name_20034012 = "สไตรด์ฉ้อฉล",
  str_monster_passiveskill_desc_20034012 = "สร้างทรายดูดสังหารบนช่องที่เคลื่อนที่ผ่าน",
  str_monster_name_2003101 = "เสือกอิลลูมินา",
  str_monster_desc_2003101 = "ในฐานะเป็นเจ้าหน้าที่ระดับพื้นฐานของกองทัพอิลลูมินา พวกเขามีหน้าที่สั่งการกำลังรบปกติในสนามรบ ส่วนใหญ่จบมาจากโรงเรียนนายร้อย ในขณะที่บางคนถูกเลื่อนขั้นจากกองทหารที่มีประสบการณ์",
  str_monster_ability_2003101 = "การอยู่ใกล้ของพวกเขาเพิ่มความสามารถของทหารอิลลูมินาที่อยู่ใกล้เคียง และช่วยให้พวกเขาฟื้นตัวจากบาดแผล หากพวกเขาตัวเองต้องอยู่ห่างจากพันธมิตรหรือใกล้ชิดกับศัตรู นายสิบคนเหล่านี้จะใช้อาวุธ โจมตีด้วยการตัดที่รุนแรงและการเตะที่มีผลกระทบมาก",
  str_monster_name_2002701 = "อิลลูมินาเสนารักษ์",
