  str_monster_desc_70011041 = "ผู้ว่าการของลูโมโพลิส ผู้ปกครองที่ยิ่งใหญ่ที่สุด มีชื่อเสียงในการทุ่มเทตัวเองอย่างเสียสละ ท่านอาจเข้าสู่สนามประลองด้วยตัวเองเพื่อประเมินความสามารถของทุกคน",
  str_monster_ability_70011041 = "ชวาร์ตษ์ใช้พลังสายฟ้าที่น่าทึ่ง ทำให้เขามีความคล่องตัวและพลังทำลายที่น่าเกรงขาม ผู้ที่ผ่านการทดสอบความแข็งแกร่งของเขาจะถือว่าเป็นคนเลิศค่าย",
  str_monster_name_5352021 = "พลโล่ลูโม",
  str_monster_name_5352021_en = "พลโล่ลูโม",
  str_monster_desc_5352021 = "ทหารคุ้มกันที่ติดโล่ป้องกันชั้นสูง ด้วยความสามารถในการทนต่อการต่อสู้อันดุเดือด ทำให้พวกมันเป็นกำแพงแข็งแกร่งที่คอยปกป้องพวกพ้องของตัวเอง",
  str_monster_ability_5352021 = "ทหารคุ้มกันที่มีความสามารถในการป้องกันอย่างยอดเยี่ยมสามารถเรียกทหารลูโมโพลิสคนอื่น ๆ เข้ามาช่วยในการต่อสู้และเพิ่มความมั่นใจ ถือโล่ที่มีพลังและสามารถใช้โจมตีใกล้ตัวอย่างรุนแรง",
  str_monster_name_2905801 = "จักรพรรดิแห่งความตาย",
  str_monster_name_2905801_en = "จักรพรรดิแห่งความตาย",
  str_monster_desc_2905801 = "พระองค์จักรพรรดิสูงสุดแห่งความวุ่นวาย พ่อของโทรุ ที่เป็นทหารเก่าผู้มีประสบการณ์ในสงครามมากมาย ไม่ว่าเมื่อใดและที่ใด ก็เป็นกำลังอันน่ายืนยันอย่างแน่นอน",
  str_monster_ability_2905801 = "ด้วยพลังที่น่าเกรงขาม เขาใช้ทักษะหลากหลายในการโจมตีผู้เล่นอย่างแม่นยำหรือปล่อยการโจมตีระยะไกล พร้อมกับผลักคู่ต่อสู้ถอยหลัง",
  str_monster_passiveskill_name_2905801 = "ลูมินาอ่อนแรง",
  str_monster_passiveskill_desc_2905801 = "การโจมตีปกติและคอมโบต่อเนื่องของผู้เล่นทำให้ดาเมจลดลงใน 5 ช่องที่บอสครอบครอง ยกเว้นช่องกลาง",
  str_monster_ability_140045106 = "ใช้เนลส์",
  str_monster_ability_150092106 = "ทำดาเมจให้กับศัตรูในพื้นที่รูป X พร้อมกับเปลี่ยนช่องสีแดงที่ไม่ดีต่อผู้สร้างเสียง",
  str_monster_ability_160103106 = "ทำดาเมจให้กับศัตรูที่ใกล้ที่สุด ในขณะที่เปลี่ยนช่องสีน้ำเงินที่เป็นปัญหาสำหรับผู้สร้างเวทย์",
  str_monster_ability_160111106 = "ต่อสู้โดยใช้คริสตัล สร้างความเสียหายให้กับศัตรูทั้งหมดในสนามรบ",
  str_monster_ability_150009106 = "ทำดาเมจให้ศัตรูในพื้นที่รูปดอกจัน และสามารถทำให้เป้าหมายที่ถูกตีรู้สึกหวาดกลัว",
  str_monster_ability_160120106 = "ชุดเกราะขนาดยักษ์ของเธอที่ชื่อว่าปอมเปย์สามารถทำดาเมจในพื้นที่ขนาดใหญ่ พร้อมกับทำดาเมจเพิ่มเติมให้กับศัตรูที่อยู่ในวงรอบตัว 1 ชั้น",
  str_monster_ability_160089106 = "สร้างฝนดาบบึงทองคำต่อเนื่องเพื่อทำดาเมจให้เป้าหมายที่อยู่ติดกัน",
  str_monster_name_39004031 = "ถูกทอดทิ้ง: ชูมเมอร์",
  str_monster_name_39004031_en = "ถูกทอดทิ้ง: ชูมเมอร์",
  str_monster_desc_39004031 = "เดิมทีเคยเป็นเคเลสไทต์ แต่มาเข้าร่วมกับอิคลิพไซท์และมีพลังเพิ่มขึ้นมหาศาล",
  str_monster_ability_39004031 = "เชี่ยวชาญการโจมตีระยะไกลและพื้นที่",
  str_monster_name_39058011 = "Forsaken: จักรพรรดิแห่งความตาย",
  str_monster_name_39058011_en = "Forsaken: จักรพรรดิแห่งความตาย",
  str_monster_desc_39058011 = "พระองค์จักรพรรดิสูงสุดแห่งความวุ่นวาย พ่อของโทรุ ที่เป็นทหารเก่าผู้มีประสบการณ์ในสงครามมากมาย ไม่ว่าเมื่อใดและที่ใด ก็เป็นกำลังอันน่ายืนยันอย่างแน่นอน",
  str_monster_ability_39058011 = "ด้วยพลังที่น่าเกรงขาม เขาใช้ทักษะหลากหลายในการโจมตีผู้เล่นอย่างแม่นยำหรือปล่อยการโจมตีระยะไกล พร้อมกับผลักคู่ต่อสู้ถอยหลัง",
  str_monster_ability_5362001 = "จะซ่อนตัวอยู่ในลูมิวอลล์ ไกลที่สุดจากผู้เล่น การโจมตีสามารถเปลี่ยนธาตุของช่องในเส้นทางโจมตีได้",
  str_monster_name_5362001 = "กรอนรู",
  str_monster_name_5362001_en = "กรอนรู",
  str_monster_desc_5362001 = "สาวนักขับขี่จักรกลยักษ์และเจ้าหน้าที่วิทยาการคนปัจจุบันแห่งสหพันธรัฐอิลลูมินา ว่ากันว่าเธอคืออัจฉริยะที่เกษียณมาจากกองทัพ แม้จะไม่ค่อยสนใจการต่อสู้ แต่ก็เธอหลงใหลในการเรียนรู้และการควบคุมจักรกลขนาดยักษ์ แทบจะเรียกว่าหมกมุ่นเลยทีเดียว",
  str_monster_ability_5362002 = "เชี่ยวชาญการโจมตีระยะประชิด ทำดาเมจในพื้นที่แถวแนวตั้ง",
  str_monster_desc_5362002 = "บุคลากรฝ่ายเทคโนโลยีของเรดีเซล เวรนช์ที่มั่นใจในเทคโนโลยีการสื่อสารของเธอมาก เธอชอบบ่นและตะคอกคนอื่นในช่องสื่อสารแต่กลับหงุดหงิดเมื่อเจอปัญหา",
  str_monster_ability_5362003 = "เชี่ยวชาญการโจมตีระยะไกล สกิลทำให้ติดสถานะพิษ",
  str_monster_name_2909001 = "ราชามนุษย์เงือก",
  str_monster_name_2909001_en = "ราชามนุษย์เงือก",
  str_monster_desc_2909001 = "จากโลกผิวน้ำไปยังเมืองใต้น้ำ มีผู้มีอิทธิพลและโหดร้ายชนชั้นสูง",
  str_monster_ability_2909001 = "การโจมตีทำให้เกิดผลกระเด็น สามารถเรียกปืนยิงกระสุนต่อเนื่องที่ขอบสนามรบได้",
  str_monster_passiveskill_name_290900101 = "การปรับตั้งปืนซัลโว",
  str_monster_passiveskill_desc_290900101 = "ในตอนเริ่มต้นของแต่ละรอบของผู้เล่น หากมี Salvo Guns น้อยกว่า 2 ตัวบนสนามรบ ให้เรียก Salvo Guns 4 ตัวที่ขอบของสนามรบ",
  str_monster_passiveskill_name_290901101 = "การปรับตั้งปืนซัลโว",
  str_monster_passiveskill_desc_290901101 = "ในตอนเริ่มต้นของแต่ละรอบผู้เล่น หากมี Salvo Guns น้อยกว่า 3 ตัวบนสนามรบ เรียก Salvo Guns 4 ตัวที่ขอบสนามรบ",
