  str_monster_name_70011101_en = "Forsaken: เดียโวล่า",
  str_monster_desc_70011101 = "Diavola ชอบที่จะซ่อนตัวและกำจัดศัตรูอย่างลับ ๆ ล่อ ๆ ด้วยพิษ",
  str_monster_ability_70011101 = "เดียโวล่าขยับไม่ได้ ร่างกายของมันถูกห่อหุ้มด้วยใบหนามใหญ่และแข็งแกร่ง ซึ่งช่วยลดความเสียหายที่มันได้รับ",
  str_monster_passiveskill_name_70011101 = "ใบไม้หนาม",
  str_monster_passiveskill_desc_70011101 = "ลดความเสียหายที่รับบน 8 ช่องนอกของ Diavola ลง 30%",
  str_monster_passiveskill_name_70011102 = "ใบไม้หนาม",
  str_monster_passiveskill_desc_70011102 = "ลดความเสียหายที่รับบน 8 กระเบื้องนอกสุดของ Diavola ลง 50%",
  str_monster_name_2003801 = "กัปตันแก๊ง",
  str_monster_desc_2003801 = "หัวหน้าแก๊งที่มีลักษณะแปลกประหลาด มีความชำนาญในการใช้อาวุธปืน การปรากฏตัวของเขาหมายความว่ามีปัญหาเสมอสำหรับอัมบราตัน",
  str_monster_ability_2003801 = "Attacks after moving away from the target, dealing damage 2 times. Can steal the target's attributes.",
  str_monster_passiveskill_name_2003801 = "ยิงอันตราย",
  str_monster_passiveskill_desc_2003801 = "ขโมย ATK พื้นฐานและ DEF พื้นฐานของ Aurorians เมื่อทำความเสียหาย ค่า ATK และ DEF ที่ถูกขโมยจะถูกคืนค่าหลังจาก 2 รอบหรือหลังจากยูนิตนี้ถูกปราบ",
  str_monster_name_2003701 = "แก๊งนักยิงธนู",
  str_monster_desc_2003701 = "แม่นยำ ปลอดภัย ลับๆ และทรงพลังอย่างน่าทึ่ง ธนูได้รับความนิยมในหมู่สมาชิกแก๊งวายร้ายเนื่องจากคุณสมบัติที่ไม่เหมือนใครเหล่านี้ ศัตรูที่เชี่ยวชาญในการใช้งานมักจะเป็นอันตรายอย่างมาก",
  str_monster_ability_2003701 = "สามารถโจมตีเป้าหมายในรูปบวกไปจนสุดระยะ หลังจากโจมตีสำเร็จ ลดการรักษาที่เป้าหมายได้รับ",
  str_monster_passiveskill_name_2003701 = "ลูกศรในเงา",
  str_monster_passiveskill_desc_2003701 = "หลังจากโจมตี Aurorian ลดการรักษาที่ได้รับของพวกเขา 40% เอฟเฟกต์นี้ไม่ซ้อนทับกันและจะถูกนำออกเมื่อ Gang Crossbowman ถูกควบคุม",
  str_monster_name_2009001 = "ปืนซัลโว",
  str_monster_desc_2009001 = "อิคลิพไซท์ที่คล้ายกับลำกล้องปืน ให้การสนับสนุนแก่เพื่อนร่วมทีมและโจมตีทีมของคุณอย่างรุนแรง!",
  str_monster_ability_2009001 = "ยิงศัตรูที่อยู่ในระยะโจมตี หากไม่มีเป้าหมาย การโจมตีจะเพิ่มพลังและรักษาเจ้าพ่อเงือก",
  str_monster_name_8003481 = "เดย์นา",
  str_monster_desc_8003481 = "แม้ว่าอายุของเธอยังน้อย แต่เธอก็เป็นหัวหน้าของสเปียร์โรว์อยู่แล้ว เธอมีชื่อเสียงในการสร้างฐานอันมั่นคงในถนนของอัมบราตันด้วยความมุ่งมั่นที่ไม่มีใครเทียบ และอาวุธลับที่ชั่วร้ายและลับลวง",
  str_monster_ability_8003481 = "โจมตีศัตรูที่ใกล้ที่สุด",
  str_monster_name_8003781 = "โรบิน",
  str_monster_desc_8003781 = "สมาชิกของสเปียร์โรว์ในอัมบราตัน คนขี้อายและเป็นคนเก็บตัว เธอติดตามพี่สาวเดย์นาอย่างใกล้ชิดขณะพยายามอยู่รอดในอัมบราตัน",
  str_monster_ability_8003781 = "ตามผู้เล่นและทำดาเมจพื้นที่ให้ศัตรูที่อยู่ใกล้ๆ",
  str_monster_ability_2300601 = "เลิร์คเกอร์สามารถสิงร่างออโรเรียนในวงรอบตัว 1 ชั้นของตัวเอง หลังจากสิงร่างเสร็จ เลิร์คเกอร์จะสร้างความเสียหายให้กับออโรเรียนและลด ATK ของพวกเขา",
  str_monster_name_2909101 = "เรเบคก้าพันธุ์พิษสวนป่า",
  str_monster_desc_2909101 = "เส้นเลือดของเธอเต้นอยู่ด้วยพิษสีแดงอมชื่น พร้อมที่จะกำจัดความขัดแย้งใด ๆ ที่อาจเป็นอันตรายต่อครอบครัวของเธอ รวมถึงตัวเธอเอง",
  str_monster_ability_2909101 = "ทำให้การโจมตีสามารถทำให้เกิดผลของ Fusion ทำให้เป้าหมายที่ได้รับผลกระทบสูญเสีย HP ในตอนต้นของรอบของพวกเขา ในแต่ละรอบเรียกใช้ Poison Marks บนกระเบื้องรอบ ๆ ซึ่งกำหนด Fusion ให้กับศัตรูที่อยู่ใกล้ที่ผ่านไป; Poison Marks จะเปลี่ยนเป็น Dark Tiles ในตอนท้ายของรอบ",
  str_monster_name_2003901 = "ผู้เชี่ยวชาญการสนับสนุนแก๊ง",
  str_monster_desc_2003901 = "สมาชิกแก๊งค์ขนาดใหญ่ที่มีกำลังมาก มีความชำนาญในการใช้แขนกลของเขาสำหรับการต่อสู้ นอกจากนี้เขายังสามารถให้การสนับสนุนกำลังอื่น ๆ ของอัมบราตันในสนามรบ",
  str_monster_ability_2003901 = "เพิ่มพลังการโจมตีและป้องกันให้กับสมาชิก Umbraton ที่อยู่ในวงรอบตัว 1 ชั้น; ฟื้นฟู HP ของตัวเองเมื่อ HP ตกต่ำเกินกว่าเปอร์เซ็นต์ที่กำหนด",
  str_monster_passiveskill_name_2003901 = "สนับสนุนพิเศษ",
  str_monster_passiveskill_desc_2003901 = "ให้การเพิ่มพลัง ATK และ DEF ให้กับสมาชิก Umbraton ภายใน 1 กลุ่มรอบ ๆ",
  str_monster_name_2004101 = "แก๊งฆาตกร",
  str_monster_desc_2004101 = "\"การแทงที่ดีที่สุดคือการแทงจากด้านหลัง\" ชำนาญในการโจมตีจุดสำคัญ ดาบของหน่วยนี้เป็นอันตรายทั้งในการต่อสู้ในถนนและในสนามรบ",
  str_monster_ability_2004101 = "เปิดการโจมตีต่อเนื่อง 2 ครั้งอย่างรวดเร็วใส่ศัตรู ขโมยพลังโจมตีและป้องกันพื้นฐานของ Aurorians เมื่อทำความเสียหาย พลังโจมตีและป้องกันที่ถูกขโมยจะคืนค่าหลังจาก 2 รอบหรือหลังจากยูนิตนี้ถูกคว่ำ ถอยหลังหลังจากโจมตีเพื่อป้องกันตัวเอง หากเป้าหมายไม่สามารถโจมตีได้ ACT +1 ในรอบนี้",
  str_monster_passiveskill_name_2909101 = "การกัดกร่อนพิษ",
  str_monster_passiveskill_desc_2909101 = "ทำให้การโจมตีสามารถทำให้เกิดผลของ Fusion ทำให้เป้าหมายที่ได้รับผลกระทบสูญเสีย HP ในตอนต้นของรอบของพวกเขา ในแต่ละรอบเรียกใช้ Poison Marks บนกระเบื้องรอบ ๆ ซึ่งก่อให้เกิด Fusion ให้กับศัตรูที่อยู่ใกล้ที่ผ่านไป; Poison Marks จะเปลี่ยนเป็น Dark Tiles ในตอนท้ายของรอบ",
  str_monster_passiveskill_name_2004101 = "ความกระตือรือร้นในการต่อสู้",
  str_monster_passiveskill_desc_2004101 = "ขโมย ATK พื้นฐานและ DEF พื้นฐานของ Aurorians เมื่อทำความเสียหาย ค่า ATK และ DEF ที่ถูกขโมยจะถูกคืนค่าหลังจาก 2 รอบหรือหลังจากยูนิตนี้ถูกปราบ",
  str_monster_name_2909101_en = "เรเบคก้าพันธุ์พิษสวนป่า",
  str_monster_name_2003801_en = "กัปตันแก๊ง",
  str_monster_name_70011071 = "ถูกทอดทิ้ง: คิตตี้พุส",
  str_monster_name_70011071_en = "ถูกทอดทิ้ง: คิตตี้พุส",
  str_monster_desc_70011071 = "สหายคู่ใจของเกรเทล ดูแล้วเหมือนแมวที่มีหลายขา... น่ารักอยู่นะ แต่ก็พิลึกชอบกล",
  str_monster_ability_70011071 = "คิตตี้พุสปล่อยหนวดออกมา ทำดาเมจอย่างรุนแรงกับออโรเรียน จำไว้ว่า: กรงเล็บหนวดของคิตตี้พุสจะส่งต่อดาเมจที่ได้รับทั้งหมดไปให้ร่างต้นของมัน!",
