  str_monster_ability_2004501 = "พลังและป้องกันของรูปแบบชีวิตเครื่องกลที่ได้รับการปรับปรุงนี้ได้รับการปรับปรุงอย่างมาก และมันเป็นเลิศในการโจมตีด้วยการระเบิดและวิธีการอื่น ๆ ที่คล้ายกัน",
  str_monster_name_2004601 = "ซูเปอร์ทหาร Meaugm",
