  str_monster_ability_2004601 = "รูปแบบชีวิตเครื่องจักรที่ถูกปรับเปลี่ยนนี้สามารถใช้เกราะหนาของมันเป็นอาวุธ ทำให้มันยากที่จะจัดการ",
