  str_monster_passiveskill_desc_7001121 = "เมื่อเริ่มต้นรอบของผู้เล่น ถ้ามี Salvo Guns น้อยกว่า 3 ตัวบนสนามรบ จะเรียก Salvo Guns 4 ตัว",
  str_monster_name_2004701 = "ใจร้าย: หนู",
  str_monster_desc_2004701 = "อสูรขนาดเล็กที่กินทั้งพืชและเนื้อสัตว์ มีการปลูกฝังที่ไม่เพียงพอ ยังคงความเถื่อน พวกเขามักจะเล่นงานเข้าไปในที่อยู่ของ Aurorian เพื่อขโมยอาหาร บางตัวที่รุนแรงอาจจะทำให้เกิดความเสียหาย.",
  str_monster_ability_2004701 = "ว่องไวและรวดเร็ว มันเคลื่อนไหวอย่างรวดเร็วไปข้างหลังเป้าหมายหลังจากโจมตี",
  str_monster_passiveskill_name_2004701 = "การกัดของสัตว์หนู",
  str_monster_passiveskill_desc_2004701 = "โจมตี Aurorian ที่มี DEF ต่ำที่สุดในทีมเมื่อทำการโจมตี ทำให้เกิดความเสียหาย",
  str_monster_ability_5412041 = "อิคลิพไซท์ที่มีความสามารถในการเรียกลูกสมุน ไม่สามารถเคลื่อนที่ได้ด้วยตัวเอง มันต่อสู้โดยการเรียกกลูมกูลที่มีความสามารถในการโจมตีระยะไกล กลูมกูลสละ HP ของตัวเองเพื่อรักษา Croweye เมื่อเข้าสู่การต่อสู้และโอนความเสียหายไปยัง Croweye เมื่อได้รับความเสียหาย",
  str_monster_passiveskill_name_5412042 = "สังเวยสัมพันธ์ทางชีวภาพ",
  str_monster_passiveskill_desc_5412042 = "มันสละ HP ของตัวเองเพื่อรักษา Croweye เมื่อเข้าร่วมการต่อสู้และโอนความเสียหายไปยัง Croweye เมื่อได้รับความเสียหาย",
  str_monster_name_541100216 = "Chen'ni",
  str_monster_desc_541100216 = "เด็กที่ขึ้นมาอย่างกะทันหันจากที่ไร้คนอยู่ดูเหมือนจะเป็นปีศาจน้อยที่แปลกประหลาดที่มีลักษณะคล้ายเราหรือเปล่า?",
  str_monster_ability_541100216 = "ความสามารถของเธอนั้นทึ่งมาก!",
  str_monster_passiveskill_desc_541301215 = "ในตอนเริ่มต้นรอบของผู้เล่น ถ้ามี Salvo Guns น้อยกว่า 2 อันบนสนามรบ จะเรียก Salvo Guns 4 อัน",
  str_monster_name_2909301 = "Fiendling: Nian",
  str_monster_name_2909301_en = "Fiendling: Nian",
  str_monster_desc_2909301 = "ตำนานกล่าวไว้ว่าในวันก่อนเทศกาลฤดูใบไม้ผลิ, สัตว์ร้ายที่เหมือนอสูรจะลงมาที่หลงโจว ทำให้เกิดความวุ่นวาย ผู้ที่สามารถขับไล่มันได้จะได้รับความสงบสุขและโชคดีตลอดทั้งปี",
  str_monster_ability_2909301 = "เนียนจะทำลายทุกอย่างที่เห็นได้เมื่อเข้าใกล้หมู่บ้าน ชาวออโรเรียนที่มีสกิลที่ทรงพลังเท่านั้นที่สามารถหยุดมันได้",
  str_monster_passiveskill_name_2909301 = "สัตว์โบราณที่น่าเกรงขาม",
  str_monster_passiveskill_desc_2909301 = "ความเข้มข้นของ Nian น่ากลัวมาก! ช่องที่อยู่ในวงรอบ 1 กลุ่มไม่สามารถเลือกเป็นจุดลงที่ของ Aurorian ได้",
  str_monster_passiveskill_name_2909302 = "ฝ่าฟันผ่านประตู",
  str_monster_passiveskill_desc_2909302 = "สัตว์นิอานจะทำลายประตูและเมื่อเข้าไป จะทำลายทุกอย่าง ทำให้การต่อสู้ล้มเหลว",
  str_monster_name_70011251 = "Forsaken: เซอร์ริทัส",
  str_monster_name_70011251_en = "Forsaken: เซอร์ริทัส",
  str_monster_desc_70011251 = "Eclipsite ใหม่ที่พบในระหว่างการสำรวจดูเหมือนจะแตกต่างจาก Eclipsite ที่ทรงพลัง เว้นแต่จะบ้าคลั่งกว่าและทำลายล้างได้มากกว่า",
  str_monster_ability_70011251 = "ถูกทอดทิ้ง: Cerritus พุ่งเข้าใส่ Aurorians โดยเรียกก้อนกรวดและสร้างกระเบื้องที่อ่อนแออย่างต่อเนื่องบนสนาม มันยังสามารถเพิ่ม ACT ของตัวเองในระหว่างการต่อสู้",
  str_monster_name_70011261 = "ถูกทอดทิ้ง: แชนดรา",
  str_monster_name_70011261_en = "ถูกทอดทิ้ง: แชนดรา",
  str_monster_desc_70011261 = "นักวิจัยอิลลูมินาผู้มองโลกในแง่ดีและร่าเริง เธอมีความสามารถพิเศษในการซึมซับอารมณ์ด้านลบจากคนอื่นและรักษาแผลในจิตใจของพวกเขาได้",
  str_monster_ability_70011261 = "ถูกทอดทิ้ง: แชนดราสามารถโจมตี Aurorians จากระยะไกลและเพิ่มจำนวนครั้งที่สกิลของเธอสร้างความเสียหายอย่างต่อเนื่อง",
  str_monster_passiveskill_name_70011261 = "ถูกทอดทิ้ง: รวมพลังอารมณ์ด้านลบ",
  str_monster_passiveskill_desc_70011261 = "กับการสร้างแต่ละครั้งของ Forsaken: Negative Emotion Project สกิลจะโจมตีเพิ่มอีก 1 ครั้งในครั้งถัดไป ทำให้ความเสียหายรวมเพิ่มขึ้น",
  str_monster_passiveskill_name_80051412 = "กลยุทธ์สนามรบ",
  str_monster_passiveskill_desc_80051412 = "The Courier สามารถเก็บพลังงานการต่อสู้เพื่อกระตุ้นมอนสเตอร์ เมื่อมีพลังงานการต่อสู้มากกว่า 30 แต้ม จะให้การเพิ่ม ATK ถาวร 10% ให้กับมอนสเตอร์ทั้งหมดในสนามในทุกรอบที่สิ้นสุด อย่างไรก็ตาม The Courier จะทำการระเบิดพลังงานเมื่อตาย ทำให้มอนสเตอร์ทั้งหมดในสนามได้รับความเสียหายอย่างมาก",
  str_monster_passiveskill_name_80051413 = "การเข้าถึงพลังงาน",
  str_monster_passiveskill_desc_80051413 = "Courier จะกู้คืนพลังงานการต่อสู้ 10 สแต็คโดยอัตโนมัติในตอนเริ่มแต่ละรอบ หาก Aurorian ปล่อย Active Skill ในสนาม จะลดสแต็คพลังงานการต่อสู้ของ Courier ลง 4 สแต็ค นอกจากนี้ Courier ยังจะสูญเสียพลังงานการต่อสู้ 1 สแต็คเมื่อถูกโจมตีด้วยการโจมตีปกติของ Aurorian",
  str_monster_name_2909401 = "ไอรา",
  str_monster_name_2909401_en = "ไอรา",
  str_monster_desc_2909401 = "เจตภูตที่ลึกลับและน่ากลัว ท่องทุ่งเพื่อการฝึกฝน ลมหายใจของเขาส่งออกความหวาดกลัว คาดการณ์ว่าจะมีความหายนะสำหรับผู้ที่ทำให้เขาระเบิดวราธ",
  str_monster_ability_2909401 = "สามารถเรียก Shadowfire ด้วย Darkflow ในการต่อสู้\nหมายเหตุ: Darkflow Meteorite ของ Ira ที่ประกอบด้วยเปลวไฟที่รุนแรง สามารถฆ่า Aurorians ภายในระยะทันที",
  str_monster_name_2004801 = "Shadowfire",
  str_monster_passiveskill_name_2004801 = "Shadowfire Ashes",
  str_monster_passiveskill_desc_2004801 = "เมื่อถูกกำจัด Shadowfire จะทิ้ง Dark Tiles ไว้ที่ตำแหน่งของมัน",
  str_monster_ability_5435071 = "การโจมตีทำให้ศัตรูถอยหลัง สามารถเรียกปืนซัลโวมาที่ช่องที่อยู่ใกล้เคียงเพื่อป้องกันตัวเอง",
  str_monster_ability_5435112 = "หลบซ่อนในที่ที่ปลอดภัย สละส่วนหนึ่งของ HP ในแต่ละรอบเพื่อฟื้นฟู HP ให้กับฟิเล็กซ์",
  str_monster_name_70011271 = "ถูกทอดทิ้ง: คาราคาลูน",
  str_monster_name_70011271_en = "ถูกทอดทิ้ง: คาราคาลูน",
  str_monster_name_70011281 = "Forsaken: ม้อด โซลัส",
  str_monster_name_70011281_en = "Forsaken: ม้อด โซลัส",
  str_monster_ability_70011271 = "เก่งในการใช้การโจมตีพื้นที่ขนาดใหญ่ ล็อคองค์ประกอบของกระเบื้องรอบๆ หลังจากที่มันเคลื่อนที่",
  str_monster_name_70011321 = "ถูกทอดทิ้ง: ราชินีแมงมุม",
  str_monster_name_70011321_en = "Forsaken: Arachnid Queen",
  str_monster_ability_70011321 = "มีความสามารถในการสืบพันธุ์ที่แข็งแกร่ง มันสานใยแมงมุมในสภาพแวดล้อมการล่าสัตว์และเรียกลูกๆ แมงมุมจำนวนมากเข้าร่วมการต่อสู้ทุก 3 รอบ",
  str_monster_name_70110011 = "ถูกทอดทิ้ง: อีฟที่กำลังเศร้าใจ",
  str_monster_name_70110011_en = "Forsaken:อีฟที่กำลังเศร้าใจ",
  str_monster_desc_70110011 = "ความเจ็บปวดจากความโดดเดี่ยวและความกลัวที่จะถูกตัดขาด ความทรงจำในอดีตที่ทนไม่ได้เหล่านั้นได้หล่อหลอมบุคคลที่รู้จักกันในชื่ออีฟในวันนี้",
  str_monster_ability_70110011 = "ทุกรอบ, เรียกดอว์นฟลาวเวอร์ที่ตำแหน่งที่กำหนดบนสนามรบ, เพิ่ม DEF ตามจำนวนของดอว์นฟลาวเวอร์",
  str_monster_passiveskill_name_70110011 = "ความเศร้าโศก: กลายร่าง",
  str_monster_passiveskill_desc_70110011 = "ทุกรอบ จะเรียกดอว์นฟลาวเวอร์ที่ตำแหน่งที่กำหนดเพื่อเพิ่ม DEF; ดอว์นฟลาวเวอร์แต่ละดอกจะมอบการเพิ่ม DEF เพิ่มเติม",
  str_monster_name_70110012 = "ดอกรุ่งอรุณ",
  str_monster_desc_70110012 = "ดอกไม้สีขาวที่เรียบง่าย เล็กและธรรมดาเหล่านี้เป็นความสบายใจที่มีค่าที่สุดในหัวใจของเธอ",
  str_monster_ability_70110012 = "ให้โบนัส DEF เพิ่มเติมสำหรับ Grieving Eve",
  str_monster_name_7001134 = "ถูกทอดทิ้ง: Bennuguardian",
  str_monster_name_7001134_en = "ถูกทอดทิ้ง:Bennuguardian",
  str_monster_ability_7001134 = "มีพลังอันยิ่งใหญ่ สะสม Fury เมื่อถูกโจมตี เมื่อ Fury ถึงระดับหนึ่ง จะเข้าสู่สถานะ Enraged ลดความเสียหายที่ได้รับและร่ายทักษะที่ทรงพลังเพิ่มเติม",
  str_monster_name_2004901 = "ควันหมอก",
  str_monster_desc_2004901 = "สร้างขึ้นจากการสะสมพลังความมืดรอบ ๆ อิคลิพไซท์ที่ตายอย่างรวดเร็ว ระวัง! ความโกรธและความเคียดครั้งของอิคลิพไซท์ยังอยู่ภายในมัน",
  str_monster_ability_2004901 = "ความเสียหายทั้งหมดที่มันได้รับจะลดลงเหลือ 1 มันไม่สามารถโจมตีได้ แต่จะยังคงเคลื่อนที่เข้าหา Aurorians",
  str_monster_passiveskill_name_2004901 = "หมอกพันธุ์เกี่ยว",
  str_monster_passiveskill_desc_2004901 = "ความเสียหายทั้งหมดที่มันได้รับจะลดลงเหลือ 1 มันไม่สามารถโจมตีได้ แต่จะยังคงเคลื่อนที่เข้าหา Aurorians และจะหายไปถ้าได้รับผลกระทบจากการเคลื่อนย้าย หายไปตามปกติหลังจาก 2 รอบ",
  str_monster_passiveskill_desc_2004902 = "ความเสียหายทั้งหมดที่มันได้รับจะลดลงเหลือ 1 มันไม่สามารถโจมตีได้ แต่จะยังคงเคลื่อนที่เข้าหา Aurorians และจะหายไปถ้าได้รับผลกระทบจากการเคลื่อนย้าย จะหายไปตามปกติหลังจาก 3 รอบ",
  str_monster_name_2909501 = "แครอท: โรคไฟท์",
  str_monster_name_2909501_en = "แครอท: โรคไฟท์",
  str_monster_desc_2909501 = "หลังจากดูดซับความเคียดแค้นจำนวนมากในที่ที่มืดมิดและเน่าเปื่อย แครอทตัวนี้ได้ขยายตัวเป็นสิ่งมีชีวิตที่แปลกประหลาด และแสวงหาการแก้แค้นหลังจากได้รับพลังความมืด",
  str_monster_ability_2909501 = "โยนแครอท ทำให้เกิดความเสียหายหลายครั้ง ในขณะที่หมุนด้วยความเร็วสูง จะทำให้เกิดความเสียหายหลายครั้งให้กับศัตรูในพื้นที่ขนาดใหญ่และผลักพวกเขาให้กระเด็นถอยหลัง",
  str_monster_ability_2909502 = "โยนแครอททำดาเมจหลายครั้ง ในขณะที่หมุนด้วยความเร็วสูง จะทำดาเมจหลายครั้งใส่ศัตรูในพื้นที่กว้างและผลักให้กระเด็นถอยหลัง ในสถานการณ์ฉุกเฉิน สามารถย่อตัวและขุดหลุมลงไปใต้ดินแล้วดำเนินการต่อสู้จากที่นั่น",
  str_monster_passiveskill_name_2909502 = "ไบไลท์: ขุดหลุม",
  str_monster_passiveskill_desc_2909502 = "ถ้ามันอยู่ในสภาพที่ไม่สามารถทำลายได้เมื่อมันลงมือ มันจะกลายเป็นขนาดเล็กลง ซุกลงไปใต้ดิน และฟื้นฟู HP ของมันเต็ม",
  str_monster_ability_5455121 = "สามารถใช้การโจมตีรูปบวกหรือทั้งจอ และเรียกสายฟ้าได้",
  str_monster_ability_4910302 = "มี ATK สูง และสามารถสร้างความเสียหายหนักในรูปทรงรัศมีจนถึงระยะสูงสุด",
  str_monster_ability_5455091 = "คิตตี้พุสสะบัดหนวดของมันเพื่อทำดาเมจอย่างรุนแรงต่อออโรเรียน",
  str_monster_name_2909701 = "Magmite ไม่รู้จักพอ",
  str_monster_name_2909701_en = "Magmite ไม่รู้จักพอ",
  str_monster_desc_2909701 = "ประเภทของอิคลิพไซท์ที่ผิดปกติที่ใช้ทั้งลาวาและพลังความมืดในการทำความเสียหาย",
  str_monster_ability_2909701 = "สามารถทำดาเมจในพื้นที่ขนาดใหญ่ และเรียกโล่ละลายเพื่อป้องกันตัวเอง",
  str_monster_passiveskill_name_2909701 = "ลาวาสะท้อน",
  str_monster_passiveskill_desc_2909701 = "ขณะที่ได้รับการป้องกันด้วยโล่ละลาย จะสะท้อนการโจมตีปกติทั้งหมดจาก Aurorians กลับไป",
  str_monster_name_80063701 = "ฮู้ดลำในเมือง",
  str_monster_desc_80063701 = "อันธพาลที่เชี่ยวชาญในการใช้ธนูและรู้วิธีการโจมตีอย่างแม่นยำ อย่างลับ ๆ ล่อ ๆ และสำคัญที่สุด... อย่างปลอดภัย",
  str_monster_ability_80063701 = "สามารถโจมตีเป้าหมายเป็นรูปบวกไปจนถึงสุดระยะที่สุดของมัน",
  str_monster_name_80063801 = "ฮู้ดลำชั้นนำของเมือง",
  str_monster_desc_80063801 = "ถูกกล่าวว่าพวกเขาเป็นนักรบชั้นยอดที่เชี่ยวชาญในการใช้อาวุธปืนและมีความคล่องแคล่วที่น่าทึ่ง",
  str_monster_ability_80063801 = "ทำความเสียหายสองครั้งหลังจากใช้ความคล่องแคล่วที่น่าทึ่งเพื่อสร้างระยะห่างจากเป้าหมาย",
  str_monster_ability_2910242 = "เป็นเลิศเรื่องการโจมตีพื้นที่ขนาดใหญ่ การโจมตีระยะไกลพิเศษทำดาเมจมากขึ้นให้กับเป้าหมายที่อยู่ไกลออกไป",
  str_monster_ability_2920232 = "Vani สามารถใช้ Energy เพื่อโจมตีจากระยะไกล",
  str_monster_passiveskill_name_20007011 = "การส่งเสริม",
  str_monster_passiveskill_desc_20007011 = "เมื่อถึงขอบกระดาน Alchemy จะได้เลื่อนขั้นเป็นเรือเกรี้ยวกราด อัศวินทรยศ บิชอปอิคลิพส์ หรือราชินีผู้มากเล่ห์ ตามลำดับที่ไปถึง",
  str_monster_passiveskill_name_20007111 = "การส่งเสริญขั้นสูง",
  str_monster_passiveskill_desc_20007111 = "เมื่อถึงขอบกระดาน Alchemy จะได้เลื่อนขั้นเป็นเรือเกรี้ยวกราด - RAM, อัศวินทรยศ - CHARGE, บิชอปอิคลิพส์ - EX, หรือราชินีผู้มากเล่ห์ ตามลำดับที่ไปถึง",
  str_monster_passiveskill_name_2910242 = "อย่ายอมแพ้",
  str_monster_passiveskill_desc_2910242 = "แมดฮอร์นจะกลายเป็นที่แข็งแกร่งขึ้นทุกครั้งที่แถบ HP ปัจจุบันลดลงเป็นศูนย์",
  str_monster_passiveskill_name_2010171 = "กำลังชาร์จ",
  str_monster_passiveskill_desc_2010171 = "ลดคูลดาวน์สกิลของกัปตัน Aurorian ลง 1 เมื่อถูกกำจัด",
  str_monster_passiveskill_name_2914001 = "ไม่หวั่นเกรง",
  str_monster_passiveskill_desc_2914001 = "ได้รับดาเมจ 1 จากการโจมตีเท่านั้น",
  str_monster_passiveskill_name_29140011 = "ผู้ติดตาม",
  str_monster_passiveskill_desc_29140011 = "วานี่ฟื้นฟู HP เท่ากับ 200% ของความเสียหายที่ Bennuguardian ทำให้",
  str_monster_passiveskill_name_2920232 = "ยืนหยัด",
  str_monster_passiveskill_desc_2920232 = "เพิ่ม DEF เมื่อ HP ลดลง",
  str_monster_passiveskill_name_2010715 = "การทำให้อ่อนแอ",
  str_monster_passiveskill_desc_2010715 = "ลด DEF ของราชินีผู้มากเล่ห์ทุกครั้งที่ Eclipsite ตาย",
  str_monster_passiveskill_name_20107152 = "การป้องกัน",
  str_monster_passiveskill_desc_20107152 = "ถ้าราชินีผู้มากเล่ห์มี Safeguard เมื่อดำเนินการ จะให้ 3 สแต็กของ Safeguard กับอิคลิพไซท์ทั้งหมดอื่น ๆ",
  str_monster_passiveskill_name_2910801 = "อย่ายอมแพ้",
  str_monster_passiveskill_desc_2910801 = "กษัตริย์ผู้โดดเดี่ยวจะกลายเป็นที่แข็งแกร่งขึ้นทุกครั้งที่แถบ HP ของเขาลดลงเป็นศูนย์ อิคลิพไซท์ที่กำลังหลับบางตัวจะถูกปลุกขึ้นมาด้วย",
  str_monster_passiveskill_name_29006411 = "ล็อก",
  str_monster_passiveskill_desc_29006411 = "ตอบโต้สกิลใช้งานของออโรเรียน สร้างความเสียหายให้กับออโรเรียนและเรียกกระเบื้องที่ถูกล็อกบน 4 กระเบื้องรอบๆ พวกเขา",
  str_monster_passiveskill_name_29006611 = "ทุบกระหน่ำ",
  str_monster_passiveskill_desc_29006611 = "ตอบโต้สกิลใช้งานของ Aurorian โดยสุ่มเรียกกระเบื้องที่ได้รับความเสียหาย",
  str_monster_name_1502001 = "Forsaken: แอนาโทลี",
  str_monster_name_1502001_en = "แอนาโทลี",
  str_monster_desc_1502001 = "เจ้าหน้าที่ข่าวกรองที่ใจเย็นและไว้ใจได้ของสมาพันธ์อิลลูมินาซึ่งส่งเรื่องร้องเรียนที่คาดไม่ถึงในบางครั้ง ไม่มีใครรู้ว่าการร้องเรียนเหล่านี้เกิดขึ้นโดยตั้งใจหรือไม่ตั้งใจ",
  str_monster_ability_1502001 = "ดึงยูนิตศัตรูเข้ามาเพื่อควบคุมสถานการณ์การต่อสู้ได้ง่ายขึ้น",
  str_monster_name_1501761 = "ถูกทอดทิ้ง: เบเร็ตตา",
  str_monster_name_1501761_en = "เบเร็ตตา",
  str_monster_desc_1501761 = "A Lumopolis combat doctor was once saved by a doctor called John. Since then, she has made up her mind to become a good doctor.",
  str_monster_ability_1501761 = "ใช้ความชำนาญในการใช้ ออสตราลิสสเปียร์ เพื่อสร้างความเสียหายให้กับศัตรู มีความสามารถในการตอบโต้ Aurorian Active Skills.",
  str_monster_passiveskill_name_1501761 = "เคาน์เตอร์ออสตราลิส",
  str_monster_passiveskill_desc_1501761 = "ตอบโต้ Aurorian Active Skills โดยให้ 1 สัญลักษณ์ Australis Spear สร้างความเสียหายเพิ่ม 1 ครั้งเมื่อร่าย Australis Tempest.",
  str_monster_name_70011291 = "ถูกทอดทิ้ง: มังกรปีศาจฮาคุโดมะ",
  str_monster_name_70011291_en = "ถูกทอดทิ้ง: มังกรปีศาจฮาคุโดมะ",
  str_monster_name_5471001 = "ไรน์ฮาร์ต",
  str_monster_name_5471001_en = "ไรน์ฮาร์ต",
  str_monster_desc_5471001 = "จอมทัพผู้ยิ่งใหญ่ที่แท้จริงแห่งสหพันธรัฐอิลลูมินา เธอไม่เพียงแต่กล้าหาญและมีทักษะในสนามรบเท่านั้น แต่ยังเป็นผู้นำที่จริงใจและมีความสามารถสูงซึ่งทุกคนในอิลลูมินาต่างก็ยอมรับนับถือ",
  str_monster_ability_5471001 = "มี ATK สูงและสามารถสร้างความเสียหายหนักแก่เป้าหมายที่อยู่รอบ ๆ",
  str_monster_desc_5471002 = "หุ่นยนต์ต่อสู้ที่ถูกปรับเปลี่ยนโดยสหพันธรัฐ Illumina ถูกปรับแต่งตามคุณสมบัติเฉพาะของ Reinhardt มันมีความสามารถบางอย่างของเธอ",
  str_monster_name_2909801 = "หัวหอก: Rotbone Stinger",
  str_monster_name_2909801_en = "หัวหอก: Rotbone Stinger",
  str_monster_desc_2909801 = "เคยเป็นยักษ์ใหญ่ที่เข้าร่วมการต่อสู้และกระโดดเข้าสู่การวุ่นวายในนามของ Eclipse ตอนนี้มันเพียงแค่กองซากที่แตกสลาย ภัยคุกคามสุดท้ายที่ยังคงอยู่อยู่ในกระดูกหางของมัน",
  str_monster_ability_2909801 = "สามารถทำดาเมจให้เป้าหมายในพื้นที่ขนาดใหญ่และสร้างหน่วยรอบข้างที่เคลื่อนที่ในรูปแบบกลุ่มเพื่อป้องกัน Aurorians",
  str_monster_name_2005101 = "ปลุกปั่นแถวนี้",
  str_monster_desc_2005101 = "เดิมเป็นส่วนหนึ่งของหาง Spearhead, ชิ้นส่วนเหล่านี้หลุดออกมาทีละชิ้นและกระจัดกระจายไปทั่วซากปรัมปรายใต้ดิน",
  str_monster_ability_2005101 = "มอนสเตอร์บินที่ถูกควบคุมด้วยกำลังลึกลับ สร้างรูปแบบที่แปลกประหลาดอย่างต่อเนื่องเพื่อเริ่มการโจมตีระยะใกล้ต่อผู้บุกรุก",
  str_monster_name_70011421 = "Forsaken: ฟิเจอรัลด์",
  str_monster_name_70011421_en = "Forsaken: ฟิเจอรัลด์",
  str_monster_name_70011431 = "ถูกทอดทิ้ง: ไอรา",
  str_monster_name_70011431_en = "ถูกทอดทิ้ง: ไอรา",
  str_monster_passiveskill_name_2905201 = "ก้าวเข้าสู่ความว่างเปล่า",
  str_monster_passiveskill_desc_2905201 = "กระเบื้องที่ Aurorian เคลื่อนไปจะพังทลายลงมา กระเบื้องจะไม่ยุบใน Aurora Time หลังจากที่ Aurorian เคลื่อนตัวไป Sanity จะลดลง 30 เมื่อฉากพังทลายลง",
  str_monster_name_2910101 = "David Porfirio",
  str_monster_name_2910101_en = "David Porfirio",
  str_monster_desc_2910101 = "หัวหน้าครอบครัญชีพ Porfirio เขาเป็นคนที่ชอบครองคนอื่น และไร้ความยั้งคิดในการไล่ตามอำนาจด้วยทุกวิธีที่เป็นไปได้",
  str_monster_ability_2910101 = "ใช้สกิลต่างๆ ต่อสู้กับ Aurorians ขึ้นอยู่กับสุขภาพจิต: เรียก Necroservants หรือโจมตีเพื่อฟื้นฟูสุขภาพของตัวเอง",
  str_monster_passiveskill_name_29101011 = "ความวิกลจริต",
  str_monster_passiveskill_desc_29101011 = "เมื่อค่าสุขภาพจิตลดลง ดาวิด พอร์ฟิริโอจะเพิ่มความเข้มข้น ด้วย DEF ที่ต่ำลง แต่ ATK ที่สูงขึ้น",
  str_monster_passiveskill_name_29101012 = "การยับยั้งความกลัว",
  str_monster_passiveskill_desc_29101012 = "รับเฉพาะ 10% ของความเสียหายครั้งแรกจาก Aurorian ในแต่ละรอบ",
  str_monster_name_2005201 = "เนโครเซอร์แวนท์",
  str_monster_desc_2005201 = "วิญญาณผู้ล่วงลับที่เศร้าสลด ถูกหลอกลวงและกักขังตลอดกาล ตอนนี้พวกเขาออกเร่ร่อน แสวงหาโลหิตอุ่นๆสดใหม่สำหรับพระเจ้าของพวกเขา",
  str_monster_ability_2005201 = "ทำให้ผลกระทบความเสียหายที่แตกต่างกันต่อ Aurorians ขึ้นอยู่กับ Sanity: การระบาย Sanity หรือการบริโภค HP.",
  str_monster_name_2910001 = "ซิวร์ตอน",
  str_monster_desc_2910001 = "ทหารรบที่ยักษ์ยืนกราน แม้ว่าจะสูญเสียส่วนหนึ่งของร่างกาย ก็ยังสามารถทำลายสิ่งก่อสร้างบนพื้นดินได้",
  str_monster_ability_2910001 = "สามารถโจมตี Aurorians ด้วยส่วนต่าง ๆ ของร่างกาย การทำให้ส่วนใดส่วนหนึ่งของ Syurton เสียหายจะทำให้มันได้รับความเจ็บปวด",
  str_monster_name_2910001_en = "ซิวร์ตอน",
  str_monster_passiveskill_name_2910001 = "ปฏิเสธแสงอาทิตย์",
  str_monster_passiveskill_desc_2910001 = "หางของ Syurton มีภูมิคุ้มกันต่อการโจมตีปกติและความเสียหายในพื้นที่",
  str_monster_name_2909901 = "Stone Giant of the Ruins",
  str_monster_name_2909901_en = "ยักษ์หินของซากโบราณ",
  str_monster_desc_2909901 = "In the eyes of future Aurorians, extraordinary advanced technology may be seen as equivalent to magic, and in Fleur's eyes, the stone giant is akin to a mecha.",
  str_monster_ability_2909901 = "มีความสามารถในการรักษาที่ทรงพลัง",
  str_monster_passiveskill_name_2909901 = "กดใช้ NULL",
  str_monster_passiveskill_desc_2909901 = "หลังจากที่ Aurorian Active Skill ถูกใช้งานทุก 3 ครั้ง ยักษ์หินของซากปรักษ์จะตอบโต้ ทำให้การใช้ Active Skill ครั้งถัดไปไม่มีผล สิ่งนี้ไม่ส่งผลกระทบต่อระบบทางยุทธวิธี",
  str_monster_name_70011451 = "ฟอร์เซคเคนดาร์กซัมมอนเนอร์",
  str_monster_name_70011451_en = "ฟอร์เซคเคนดาร์กซัมมอนเนอร์",
  str_monster_name_70011461 = "The Forsaken: ยักษ์หินของซากโบราณ",
  str_monster_name_70011461_en = "The Forsaken: ยักษ์หินของซากโบราณ",
  str_monster_name_700201901 = "เรจินาผู้ถูกทอดทิ้ง",
  str_monster_name_700201901_en = "The Forsaken: ยักษ์หินของซากโบราณ",
  str_monster_desc_700201901 = "ธรรมชาติที่กล้าหาญและโผงผาง รวมทั้งความหุนหันพลันแล่นของเธอเป็นเครื่องหมายของจิตวิญญาณชาวร็อกแอนด์โรลตัวจริง! สไตล์ดนตรีที่ดุดันทำให้เธอโด่งดังอย่างมากในเรดีเซล เวรนช์ ไม่เพียงแต่สร้างแรงบันดาลใจให้กับกองทหารเท่านั้น แต่ยังเป็นผู้นำในการจู่โจมอีกด้วย",
  str_monster_ability_700201901 = "ไม่สามารถเคลื่อนที่ได้ แต่เป็นเลิศในการทำดาเมจพื้นที่ขนาดใหญ่และผลักศัตรูให้ถอยหลัง",
  str_monster_ability_70011451 = "เรียกประภาคารและได้ลดดาเมจตามจำนวนประภาคารรอบตัว สกิลมีระยะโจมตีรูปบวก โดยดาเมจและระยะของสกิลชาร์จได้ขึ้นอยู่กับจำนวนประภาคาร",
  str_monster_name_2910201 = "Stellandine: ต้นแบบ",
  str_monster_name_2910201_en = "Stellandine : ต้นแบบ",
  str_monster_desc_2910201 = "ปิดบังในปลอมปิดตัว มันร้องเพลงและร้องไห้เพื่อดึงดูดเหยื่อของมัน เมื่อปลอมปิดตัวถูกถอดออก มันเอาชนะศัตรูด้วยความรุนแรงและพิษ ตลอดทั้งเวลา มันไม่สามารถเข้าใจได้ว่าความรักคือการปราบปรามธรรมชาติของตนเอง",
  str_monster_ability_2910201 = "อัญเชิญอิคลิพไซท์จำนวนมากเพื่อสนับสนุน สร้างความเป็นภัยต่อหน่วยศัตรูรอบ ๆ ตัวเอง",
  str_monster_passiveskill_name_2910201 = "เสียงกระซิบของทะเลลึก",
  str_monster_passiveskill_desc_2910201 = "ในตอนเริ่มต้นของแต่ละรอบ ความเสียหายที่ส่งไปยัง Aurorians ภายใน 1 กลุ่มรอบๆ จะถูกคำนวณตามเปอร์เซ็นต์ของ HP ปัจจุบันของพวกเขา",
  str_monster_name_2005301 = "ปืนซัลโว",
  str_monster_desc_2005301 = "มันกำลังเรียนรู้เกี่ยวกับออโรเรียน แต่ก็ยากที่จะเข้าใจว่าเมื่อไหร่ควรยิงปืนเพื่อแสดงความเคารพ ทั้งที่มันต้องการเพียงแค่กระซิบเบา ๆ แต่กลับกลายเป็นพิษทะเลลึกที่กัดกร่อนทุกคนที่เข้าใกล้.",
